CREATE OR REPLACE FUNCTION public.auto_calculate_contract_fx()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_result RECORD;
    v_should_calculate BOOLEAN := false;
BEGIN
    -- Determinar si debemos calcular FX
    IF TG_OP = 'INSERT' THEN
        -- En INSERT, solo calcular si el contrato ya viene en estado Firmado/Activo
        IF NEW.status IN ('Firmado', 'Activo') THEN
            v_should_calculate := true;
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        -- En UPDATE, calcular si:
        -- 1. El estado cambió a Firmado o Activo
        IF (OLD.status NOT IN ('Firmado', 'Activo') AND NEW.status IN ('Firmado', 'Activo')) THEN
            v_should_calculate := true;
        -- 2. O si YA está en Firmado/Activo y cambiaron campos relevantes
        ELSIF NEW.status IN ('Firmado', 'Activo') AND (
            OLD.total_value IS DISTINCT FROM NEW.total_value OR
            OLD.contract_currency IS DISTINCT FROM NEW.contract_currency OR
            OLD.booking_date IS DISTINCT FROM NEW.booking_date
        ) THEN
            v_should_calculate := true;
        END IF;
    END IF;

    -- Solo ejecutar cálculo si se cumplieron las condiciones
    IF v_should_calculate THEN
        SELECT * INTO v_result FROM public.calculate_contract_fx_amounts(NEW.id);

        IF NOT v_result.success THEN
            RAISE WARNING 'Failed to calculate FX amounts for contract %: %', NEW.id, v_result.message;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_calculate_pricing_fields()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_prices RECORD;
  v_frequency_multiplier INTEGER;
BEGIN
  -- Sincronizar campos anuales <-> mensuales (común a quote_items y contract_items)
  IF NEW.price_entry_mode = 'annual' AND NEW.annual_unit_price IS NOT NULL THEN
    NEW.unit_price := ROUND(NEW.annual_unit_price / 12.0, 6);
    NEW.annual_price := ROUND(NEW.annual_unit_price * COALESCE(NEW.quantity, 1), 2);
  ELSE
    IF NEW.unit_price IS NOT NULL THEN
      NEW.annual_unit_price := ROUND(NEW.unit_price * 12.0, 6);
      NEW.annual_price := ROUND(NEW.annual_unit_price * COALESCE(NEW.quantity, 1), 2);
    END IF;
    IF NEW.price_entry_mode IS NULL THEN
      NEW.price_entry_mode := 'monthly';
    END IF;
  END IF;

  -- Rama contract_items: la columna `categoria` solo existe aquí.
  -- IMPORTANTE: el IF que referencia NEW.categoria DEBE estar anidado dentro
  -- de un IF separado por TG_TABLE_NAME — no en la misma expresión booleana
  -- con AND. PG planea cada expresión SQL contra el tipo de NEW al ejecutarla;
  -- si NEW.categoria aparece en la misma expresión que el gate, el plan falla
  -- en quote_items aunque la condición sea false (no hay short-circuit a
  -- nivel de planning, solo a nivel de evaluación).
  IF TG_TABLE_NAME = 'contract_items' THEN
    IF COALESCE(NEW.categoria, '') IN ('CHURN', 'DOWNSELL')
       AND COALESCE(NEW.term_months, 0) > 0
       AND NEW.final_price IS NOT NULL
    THEN
      NEW.monthly_price := ROUND(NEW.final_price / NEW.term_months, 2);

      CASE LOWER(COALESCE(NEW.billing_frequency, 'mensual'))
        WHEN 'mensual' THEN v_frequency_multiplier := 1;
        WHEN 'trimestral' THEN v_frequency_multiplier := 3;
        WHEN 'semestral' THEN v_frequency_multiplier := 6;
        WHEN 'anual' THEN v_frequency_multiplier := 12;
        WHEN 'bianual' THEN v_frequency_multiplier := 24;
        ELSE v_frequency_multiplier := 1;
      END CASE;
      NEW.billing_period_price := ROUND(NEW.monthly_price * v_frequency_multiplier, 2);

      RETURN NEW;
    END IF;
  END IF;

  -- Flujo normal: quote_items siempre, y contract_items no CHURN/DOWNSELL
  SELECT * INTO v_prices
  FROM public.calculate_monthly_and_period_prices(
    NEW.unit_price, NEW.quantity, NEW.billing_frequency, NEW.is_recurring,
    NEW.final_price, NEW.term_months, NEW.discount_type, NEW.discount_value
  );

  NEW.monthly_price := v_prices.monthly_price;
  NEW.billing_period_price := v_prices.billing_period_price;

  -- Override billing_period_price desde annual_price si mode=annual
  IF NEW.price_entry_mode = 'annual' AND NEW.annual_price IS NOT NULL AND COALESCE(NEW.is_recurring, false) THEN
    CASE LOWER(COALESCE(NEW.billing_frequency, 'mensual'))
      WHEN 'mensual' THEN v_frequency_multiplier := 1;
      WHEN 'trimestral' THEN v_frequency_multiplier := 3;
      WHEN 'semestral' THEN v_frequency_multiplier := 6;
      WHEN 'anual' THEN v_frequency_multiplier := 12;
      WHEN 'bianual' THEN v_frequency_multiplier := 24;
      ELSE v_frequency_multiplier := 1;
    END CASE;
    NEW.billing_period_price := ROUND(NEW.annual_price * v_frequency_multiplier / 12.0, 2);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_populate_invoice_fx_to_system()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_system_currency TEXT;
  v_fx_policy TEXT;
  v_contract_currency TEXT;
  v_fx_result RECORD;
  v_issue_date DATE;
BEGIN
  -- Solo procesar si el invoice tiene contract_id
  IF NEW.contract_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Obtener contract_currency del contrato
  SELECT contract_currency INTO v_contract_currency
  FROM public.contracts
  WHERE id = NEW.contract_id;

  IF v_contract_currency IS NULL THEN
    RETURN NEW;
  END IF;

  -- Obtener system_currency y fx_system_policy del holding
  SELECT system_currency, fx_system_policy
  INTO v_system_currency, v_fx_policy
  FROM public.holding_settings
  WHERE holding_id = NEW.holding_id;

  -- Defaults si no hay configuración
  v_system_currency := COALESCE(v_system_currency, 'USD');
  v_fx_policy := COALESCE(v_fx_policy, 'monthly_avg');

  -- Si las monedas son iguales, fx = 1
  IF v_contract_currency = v_system_currency THEN
    NEW.fx_contract_to_system := 1.0;
    NEW.system_currency := v_system_currency;
    NEW.amount_system_currency := NEW.amount_contract_currency;

    -- ✅ tax_rate está en PORCENTAJE (0-100), dividir por 100
    NEW.total_system_currency := ROUND(
      NEW.amount_system_currency * (1 + COALESCE(NEW.tax_rate, 0) / 100.0),
      2
    );

    RETURN NEW;
  END IF;

  -- Determinar fecha para buscar FX rate
  v_issue_date := COALESCE(NEW.issue_date, NEW.scheduled_at, NEW.original_issue_date, CURRENT_DATE);

  -- Usar calculate_system_fx_rate con holding_id
  SELECT rate, source, reference_date
  INTO v_fx_result
  FROM public.calculate_system_fx_rate(
    NEW.holding_id,
    v_contract_currency,
    v_system_currency,
    v_issue_date,
    v_fx_policy
  );

  -- Asignar el FX rate encontrado
  IF v_fx_result.rate IS NOT NULL THEN
    NEW.fx_contract_to_system := v_fx_result.rate;
    NEW.system_currency := v_system_currency;

    -- ✅ FIX: DIVIDIR en lugar de multiplicar
    -- Los rates están configurados como inversos (1 USD = X moneda)
    -- Para convertir moneda → USD debemos DIVIDIR
    NEW.amount_system_currency := ROUND(NEW.amount_contract_currency / NULLIF(v_fx_result.rate, 0), 2);

    -- ✅ FIX: Calcular total_system desde amount_system y tax_rate en PORCENTAJE
    NEW.total_system_currency := ROUND(
      NEW.amount_system_currency * (1 + COALESCE(NEW.tax_rate, 0) / 100.0),
      2
    );
  ELSE
    -- Si no se encuentra FX rate, dejar NULL y loguear
    RAISE WARNING 'No FX rate found for holding % from % to % on date %', 
      NEW.holding_id, v_contract_currency, v_system_currency, v_issue_date;
    NEW.fx_contract_to_system := NULL;
    NEW.system_currency := v_system_currency;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_populate_invoice_item_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice_record RECORD;
  v_contract_item_record RECORD;
BEGIN
  -- Obtener datos de la factura
  SELECT contract_id, status, issue_date
  INTO v_invoice_record
  FROM public.invoices
  WHERE id = NEW.invoice_id;

  -- Auto-poblar desde invoice
  NEW.contract_id := v_invoice_record.contract_id;
  NEW.status := v_invoice_record.status;
  NEW.issue_date := v_invoice_record.issue_date;

  -- Si hay contract_item_id, obtener product_id y currency
  IF NEW.contract_item_id IS NOT NULL THEN
    SELECT product_id, currency
    INTO v_contract_item_record
    FROM public.contract_items
    WHERE id = NEW.contract_item_id;

    IF FOUND THEN
      NEW.product_id := v_contract_item_record.product_id;
      -- CORREGIDO: Usar contract_currency e invoice_currency en lugar de currency
      NEW.contract_currency := v_contract_item_record.currency;
      NEW.invoice_currency := COALESCE(NEW.invoice_currency, v_contract_item_record.currency);
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_populate_invoice_tax_rate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_tax_rate NUMERIC;
BEGIN
  IF NEW.company_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.tax_rate IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT tax_rate INTO v_company_tax_rate
  FROM public.companies
  WHERE id = NEW.company_id;

  IF v_company_tax_rate IS NULL THEN
    RAISE EXCEPTION 'TAX_RATE_NOT_CONFIGURED: La empresa no tiene configurada una tasa de impuesto (tax_rate). Configure el impuesto en la empresa antes de crear facturas.'
      USING ERRCODE = 'P0001';
  END IF;

  NEW.tax_rate := v_company_tax_rate;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.bulk_activate_contracts(p_contract_ids uuid[], p_booking_mode text DEFAULT 'keep_existing'::text, p_booking_date date DEFAULT NULL::date, p_comments text DEFAULT NULL::text)
 RETURNS TABLE(contract_id uuid, success boolean, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_holding_id uuid;
  v_contract RECORD;
  v_booking date;
  v_prev_step uuid;
  v_cid uuid;
BEGIN
  -- Resolver usuario actual
  SELECT public.get_current_user_id() INTO v_user_id;
  IF v_user_id IS NULL THEN
    -- Retornar error para todos los contratos
    FOREACH v_cid IN ARRAY p_contract_ids LOOP
      contract_id := v_cid;
      success := false;
      message := 'Usuario no autenticado';
      RETURN NEXT;
    END LOOP;
    RETURN;
  END IF;

  -- Resolver holding del usuario
  SELECT public.get_current_user_holding_id() INTO v_holding_id;
  IF v_holding_id IS NULL THEN
    FOREACH v_cid IN ARRAY p_contract_ids LOOP
      contract_id := v_cid;
      success := false;
      message := 'Usuario sin holding asociado';
      RETURN NEXT;
    END LOOP;
    RETURN;
  END IF;

  -- Procesar cada contrato
  FOREACH v_cid IN ARRAY p_contract_ids LOOP
    BEGIN
      -- Obtener datos del contrato
      SELECT c.* INTO v_contract
      FROM public.contracts c
      WHERE c.id = v_cid AND c.holding_id = v_holding_id;

      IF NOT FOUND THEN
        contract_id := v_cid;
        success := false;
        message := 'Contrato no encontrado o sin permisos';
        RETURN NEXT;
        CONTINUE;
      END IF;

      -- Validar estado actual
      IF v_contract.status = 'Activo' THEN
        contract_id := v_cid;
        success := false;
        message := 'El contrato ya está activo';
        RETURN NEXT;
        CONTINUE;
      END IF;

      IF v_contract.status IN ('Cancelado', 'Expirado') THEN
        contract_id := v_cid;
        success := false;
        message := 'No se puede activar un contrato ' || v_contract.status;
        RETURN NEXT;
        CONTINUE;
      END IF;

      -- Validar FX policy si aplica
      IF v_contract.contract_currency IS DISTINCT FROM (
        SELECT currency FROM public.companies WHERE id = v_contract.company_id
      ) THEN
        IF v_contract.fx_company_confirmed_at IS NULL THEN
          contract_id := v_cid;
          success := false;
          message := 'FX policy no configurada para este contrato';
          RETURN NEXT;
          CONTINUE;
        END IF;
      END IF;

      -- Guardar step anterior para historial
      v_prev_step := v_contract.current_step_id;

      -- Resolver booking_date según modo
      v_booking := CASE 
        WHEN lower(coalesce(p_booking_mode, 'keep_existing')) = 'set_date' AND p_booking_date IS NOT NULL 
          THEN p_booking_date
        WHEN lower(coalesce(p_booking_mode, 'keep_existing')) = 'today' 
          THEN CURRENT_DATE
        ELSE COALESCE(v_contract.booking_date, CURRENT_DATE)
      END;

      -- Actualizar contrato a Activo
      UPDATE public.contracts
      SET 
        status = 'Activo',
        current_step_id = NULL,
        workflow_completed_at = now(),
        booking_date = v_booking
      WHERE id = v_cid;

      -- Registrar historial de workflow
      INSERT INTO public.contract_workflow_history (
        contract_id,
        workflow_step_id,
        status,
        comments,
        transition_type,
        metadata,
        user_id,
        completed_at
      ) VALUES (
        v_cid,
        v_prev_step,
        'completed',
        COALESCE(p_comments, 'Contrato activado mediante activación masiva'),
        'manual',
        jsonb_build_object(
          'bulk_activation', true,
          'previous_step_id', v_prev_step,
          'booking_mode', p_booking_mode,
          'timestamp', now()
        ),
        v_user_id,
        now()
      );

      contract_id := v_cid;
      success := true;
      message := 'Contrato activado exitosamente';
      RETURN NEXT;

    EXCEPTION WHEN OTHERS THEN
      contract_id := v_cid;
      success := false;
      message := 'Error: ' || SQLERRM;
      RETURN NEXT;
    END;
  END LOOP;

  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.bulk_confirm_fx_policy(p_contract_ids uuid[], p_fx_policy text DEFAULT 'monthly_avg'::text)
 RETURNS TABLE(contract_id uuid, success boolean, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_holding_id uuid;
  v_contract RECORD;
  v_cid uuid;
BEGIN
  -- Resolver usuario actual
  SELECT public.get_current_user_id() INTO v_user_id;
  IF v_user_id IS NULL THEN
    FOREACH v_cid IN ARRAY p_contract_ids LOOP
      contract_id := v_cid;
      success := false;
      message := 'Usuario no autenticado';
      RETURN NEXT;
    END LOOP;
    RETURN;
  END IF;

  -- Resolver holding del usuario
  SELECT public.get_current_user_holding_id() INTO v_holding_id;
  IF v_holding_id IS NULL THEN
    FOREACH v_cid IN ARRAY p_contract_ids LOOP
      contract_id := v_cid;
      success := false;
      message := 'Usuario sin holding asociado';
      RETURN NEXT;
    END LOOP;
    RETURN;
  END IF;

  -- Validar política FX
  IF p_fx_policy NOT IN ('fixed_period', 'monthly_avg') THEN
    FOREACH v_cid IN ARRAY p_contract_ids LOOP
      contract_id := v_cid;
      success := false;
      message := 'Política FX inválida. Use fixed_period o monthly_avg';
      RETURN NEXT;
    END LOOP;
    RETURN;
  END IF;

  -- Procesar cada contrato
  FOREACH v_cid IN ARRAY p_contract_ids LOOP
    BEGIN
      -- Obtener datos del contrato
      SELECT c.* INTO v_contract
      FROM public.contracts c
      WHERE c.id = v_cid AND c.holding_id = v_holding_id;

      IF NOT FOUND THEN
        contract_id := v_cid;
        success := false;
        message := 'Contrato no encontrado o sin permisos';
        RETURN NEXT;
        CONTINUE;
      END IF;

      -- Verificar si ya está confirmado
      IF v_contract.fx_company_confirmed_at IS NOT NULL THEN
        contract_id := v_cid;
        success := false;
        message := 'La política FX ya está confirmada';
        RETURN NEXT;
        CONTINUE;
      END IF;

      -- Si es fixed_period, verificar que existan tasas configuradas
      IF p_fx_policy = 'fixed_period' THEN
        IF NOT EXISTS (
          SELECT 1 FROM public.contract_fx_period_rates 
          WHERE contract_id = v_cid
        ) THEN
          contract_id := v_cid;
          success := false;
          message := 'Política fixed_period requiere tasas FX configuradas';
          RETURN NEXT;
          CONTINUE;
        END IF;
      END IF;

      -- Actualizar contrato con política confirmada
      UPDATE public.contracts
      SET 
        fx_company_policy = p_fx_policy,
        fx_company_confirmed_at = now()
      WHERE id = v_cid;

      contract_id := v_cid;
      success := true;
      message := 'Política FX confirmada exitosamente';
      RETURN NEXT;

    EXCEPTION WHEN OTHERS THEN
      contract_id := v_cid;
      success := false;
      message := 'Error: ' || SQLERRM;
      RETURN NEXT;
    END;
  END LOOP;

  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.bulk_emit_invoices_safe(p_invoice_ids uuid[], p_issue_date date)
 RETURNS TABLE(invoice_id uuid, success boolean, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice_id UUID;
  v_result RECORD;
BEGIN
  FOREACH v_invoice_id IN ARRAY p_invoice_ids
  LOOP
    SELECT * INTO v_result FROM public.emit_invoice_safe(v_invoice_id, p_issue_date);
    RETURN QUERY SELECT v_invoice_id, v_result.success, v_result.message;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.bulk_emit_invoices_with_scheduled_dates(p_invoice_ids uuid[])
 RETURNS TABLE(invoice_id uuid, success boolean, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice_id UUID;
  v_result RECORD;
  v_scheduled_date DATE;
BEGIN
  FOREACH v_invoice_id IN ARRAY p_invoice_ids
  LOOP
    -- Para cada factura, usar su fecha programada (scheduled_at) como fecha de emisión
    SELECT i.scheduled_at INTO v_scheduled_date FROM public.invoices i WHERE i.id = v_invoice_id;

    -- Llamar a emit_invoice_safe con la fecha programada de cada factura
    SELECT * INTO v_result FROM public.emit_invoice_safe(v_invoice_id, v_scheduled_date);
    RETURN QUERY SELECT v_invoice_id, v_result.success, v_result.message;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.bulk_reconcile_legacy_invoices(p_invoice_ids uuid[], p_contract_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_holding_id uuid;
  v_invoice_id uuid;
  v_invoice_record record;
  v_item_record record;
  v_match_record record;
  v_contract_record record;
  v_reconciled_count integer := 0;
  v_failed_count integer := 0;
  v_errors jsonb := '[]'::jsonb;
  v_new_invoice_id uuid;
  v_subtotal_invoice_currency numeric;
  v_subtotal_contract_currency numeric;
  v_tax_rate numeric;
  v_tax_amount_invoice_currency numeric;
  v_tax_amount_contract_currency numeric;
  v_total_invoice_currency numeric;
  v_system_currency text;
  v_fx_contract_to_system numeric;
  v_fx_contract_to_invoice numeric;
  v_amount_system_currency numeric;
  v_total_system_currency numeric;
BEGIN
  v_holding_id := get_current_user_holding_id();

  IF v_holding_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Usuario no tiene holding_id asignado',
      'reconciled_count', 0,
      'failed_count', 0
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_holdings
    WHERE user_id = p_user_id
    AND holding_id = v_holding_id
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Usuario no autorizado',
      'reconciled_count', 0,
      'failed_count', 0
    );
  END IF;

  SELECT
    c.*,
    COALESCE(h.system_currency, 'USD') as system_currency
  INTO v_contract_record
  FROM public.contracts c
  LEFT JOIN public.company_holdings h ON h.id = c.holding_id
  WHERE c.id = p_contract_id
    AND c.holding_id = v_holding_id
    AND c.is_legacy = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Contrato no encontrado o no es legacy',
      'reconciled_count', 0,
      'failed_count', 0
    );
  END IF;

  v_system_currency := v_contract_record.system_currency;

  SELECT COALESCE(
    (SELECT rate FROM public.exchange_rates
     WHERE from_currency = v_contract_record.contract_currency
     AND to_currency = v_system_currency
     ORDER BY rate_date DESC LIMIT 1),
    1.0
  ) INTO v_fx_contract_to_system;

  FOREACH v_invoice_id IN ARRAY p_invoice_ids
  LOOP
    BEGIN
      SELECT * INTO v_invoice_record
      FROM public.invoices_legacy
      WHERE id = v_invoice_id
        AND holding_id = v_holding_id;

      IF NOT FOUND THEN
        v_failed_count := v_failed_count + 1;
        v_errors := v_errors || jsonb_build_object(
          'invoice_id', v_invoice_id,
          'error', 'Factura no encontrada'
        );
        CONTINUE;
      END IF;

      IF v_invoice_record.reconciliation_status = 'migrated' THEN
        v_failed_count := v_failed_count + 1;
        v_errors := v_errors || jsonb_build_object(
          'invoice_id', v_invoice_id,
          'error', 'Factura ya reconciliada'
        );
        CONTINUE;
      END IF;

      SELECT tax_rate INTO v_tax_rate
      FROM public.companies
      WHERE id = v_invoice_record.company_id;
      IF v_tax_rate IS NULL THEN
        v_failed_count := v_failed_count + 1;
        v_errors := v_errors || jsonb_build_object(
          'invoice_id', v_invoice_id,
          'error', 'TAX_RATE_NOT_CONFIGURED: Company sin tax_rate configurado'
        );
        CONTINUE;
      END IF;
      v_tax_rate := v_tax_rate / 100.0;

      SELECT
        COALESCE(SUM(subtotal), 0),
        COALESCE(SUM(subtotal * v_tax_rate), 0),
        COALESCE(SUM(subtotal * (1 + v_tax_rate)), 0)
      INTO
        v_subtotal_invoice_currency,
        v_tax_amount_invoice_currency,
        v_total_invoice_currency
      FROM public.invoice_items_legacy
      WHERE invoices_legacy_id = v_invoice_id;

      SELECT
        COALESCE(SUM(m.amount_contract_currency), 0)
      INTO v_subtotal_contract_currency
      FROM public.invoice_items_legacy il
      LEFT JOIN public.invoice_items_legacy_match m ON m.invoice_item_legacy_id = il.id
      WHERE il.invoices_legacy_id = v_invoice_id;

      IF v_subtotal_contract_currency = 0 THEN
        v_subtotal_contract_currency := v_subtotal_invoice_currency;
      END IF;

      v_tax_amount_contract_currency := (v_tax_amount_invoice_currency / NULLIF(v_subtotal_invoice_currency / NULLIF(v_subtotal_contract_currency, 0), 0));

      IF v_tax_amount_contract_currency IS NULL OR v_tax_amount_contract_currency = 0 THEN
        v_tax_amount_contract_currency := v_subtotal_contract_currency * v_tax_rate;
      END IF;

      IF v_subtotal_contract_currency > 0 THEN
        v_fx_contract_to_invoice := v_subtotal_invoice_currency / v_subtotal_contract_currency;
      ELSE
        v_fx_contract_to_invoice := 1.0;
      END IF;

      v_amount_system_currency := v_subtotal_contract_currency * v_fx_contract_to_system;
      v_total_system_currency := (v_subtotal_contract_currency + v_tax_amount_contract_currency) * v_fx_contract_to_system;

        INSERT INTO public.invoices (
          holding_id, contract_id, client_id, client_entity_id,
          invoice_number, issue_date, original_issue_date, due_date,
          invoice_currency, contract_currency, system_currency,
          subtotal_invoice_currency, tax_amount_invoice_currency, total_invoice_currency,
          amount_invoice_currency, amount_contract_currency, amount_system_currency, total_system_currency,
          vat, fx_contract_to_invoice, fx_contract_to_system,
          status, is_legacy, legacy_invoice_id, legacy_source_system, pdf_url, notes
        )
        VALUES (
          v_holding_id, p_contract_id, v_contract_record.client_id, v_contract_record.client_entity_id,
          v_invoice_record.invoice_number, v_invoice_record.issue_date, v_invoice_record.issue_date, v_invoice_record.due_date,
          v_invoice_record.currency, v_contract_record.contract_currency, v_system_currency,
          v_subtotal_invoice_currency, v_tax_amount_invoice_currency, v_total_invoice_currency,
          v_subtotal_invoice_currency, v_subtotal_contract_currency, v_amount_system_currency, v_total_system_currency,
          v_tax_amount_invoice_currency, v_fx_contract_to_invoice, v_fx_contract_to_system,
          COALESCE(v_invoice_record.status, 'Pagada'), true, v_invoice_id,
          COALESCE(v_invoice_record.source_system, 'Legacy Import'), v_invoice_record.pdf_url,
          'Migrada desde factura legacy mediante reconciliación masiva. ' || COALESCE(v_invoice_record.notes, '')
        )
        RETURNING id INTO v_new_invoice_id;

      FOR v_item_record IN
        SELECT
          il.*,
          m.amount_contract_currency,
          m.amount_invoice_currency as matched_amount_invoice,
          m.fx_contract_to_invoice as matched_fx,
          m.contract_item_id,
          m.quantity as matched_quantity,
          m.unit_of_measure as matched_unit_of_measure,
          ci.unit_price as contract_unit_price,
          ci.discount_value as contract_discount_pct
        FROM public.invoice_items_legacy il
        LEFT JOIN public.invoice_items_legacy_match m ON m.invoice_item_legacy_id = il.id
        LEFT JOIN public.contract_items ci ON ci.id = m.contract_item_id
        WHERE il.invoices_legacy_id = v_invoice_id
      LOOP
        DECLARE
          v_item_quantity numeric;
          v_item_unit_of_measure text;
          v_item_unit_price_contract numeric;
          v_item_unit_price_invoice numeric;
          v_item_discount_pct numeric;
          v_item_subtotal_contract numeric;
          v_item_subtotal_invoice numeric;
          v_item_tax_contract numeric;
          v_item_tax_invoice numeric;
          v_item_total_contract numeric;
          v_item_total_invoice numeric;
          v_item_fx numeric;
        BEGIN
          v_item_quantity := COALESCE(v_item_record.matched_quantity, v_item_record.quantity, 1);
          v_item_unit_of_measure := COALESCE(v_item_record.matched_unit_of_measure, v_item_record.unit_of_measure, 'UNIDAD');

          IF v_item_record.amount_contract_currency IS NOT NULL THEN
            v_item_subtotal_contract := v_item_record.amount_contract_currency;
            v_item_subtotal_invoice := COALESCE(v_item_record.matched_amount_invoice, v_item_record.subtotal);

            IF v_item_record.contract_unit_price IS NOT NULL THEN
              v_item_unit_price_contract := v_item_record.contract_unit_price;
              v_item_discount_pct := COALESCE(v_item_record.contract_discount_pct, 0);
            ELSE
              IF v_item_quantity > 0 THEN
                v_item_unit_price_contract := v_item_subtotal_contract / v_item_quantity;
              ELSE
                v_item_unit_price_contract := v_item_subtotal_contract;
              END IF;
              v_item_discount_pct := 0;
            END IF;

            v_item_unit_price_invoice := v_item_unit_price_contract * v_fx_contract_to_invoice;
            v_item_fx := v_fx_contract_to_invoice;
          ELSE
            v_item_subtotal_contract := COALESCE(v_item_record.subtotal, 0);
            v_item_subtotal_invoice := COALESCE(v_item_record.subtotal, 0);
            v_item_fx := 1.0;
            v_item_discount_pct := 0;

            IF v_item_quantity > 0 THEN
              v_item_unit_price_contract := v_item_subtotal_contract / v_item_quantity;
              v_item_unit_price_invoice := v_item_subtotal_invoice / v_item_quantity;
            ELSE
              v_item_unit_price_contract := v_item_subtotal_contract;
              v_item_unit_price_invoice := v_item_subtotal_invoice;
            END IF;
          END IF;

          v_item_tax_contract := v_item_subtotal_contract * v_tax_rate;
          v_item_tax_invoice := v_item_subtotal_invoice * v_tax_rate;
          v_item_total_contract := v_item_subtotal_contract + v_item_tax_contract;
          v_item_total_invoice := v_item_subtotal_invoice + v_item_tax_invoice;

          INSERT INTO public.invoice_items (
            invoice_id, holding_id, contract_id, contract_item_id, description,
            quantity, unit_of_measure, discount_pct, issue_date, status,
            invoice_currency, contract_currency,
            unit_price_invoice_currency, subtotal_invoice_currency, tax_amount_invoice_currency, total_invoice_currency,
            unit_price_contract_currency, subtotal_contract_currency, tax_amount_contract_currency, total_contract_currency,
            fx_contract_to_invoice, legacy_item_id
          )
          VALUES (
            v_new_invoice_id, v_holding_id, p_contract_id, v_item_record.contract_item_id, v_item_record.description,
            v_item_quantity, v_item_unit_of_measure, v_item_discount_pct, v_invoice_record.issue_date,
            COALESCE(v_invoice_record.status, 'Pagada'),
            v_invoice_record.currency, v_contract_record.contract_currency,
            v_item_unit_price_invoice, v_item_subtotal_invoice, v_item_tax_invoice, v_item_total_invoice,
            v_item_unit_price_contract, v_item_subtotal_contract, v_item_tax_contract, v_item_total_contract,
            v_item_fx, v_item_record.id
          );
        END;

        INSERT INTO public.invoice_items_legacy_match (
          invoice_item_legacy_id, contract_id, contract_item_id, contract_currency,
          fx_contract_to_invoice, amount_contract_currency, amount_invoice_currency,
          quantity, unit_of_measure, status, notes,
          created_by, confirmed_by, confirmed_at, holding_id
        )
        VALUES (
          v_item_record.id, p_contract_id, v_item_record.contract_item_id,
          v_contract_record.contract_currency,
          COALESCE(v_item_record.matched_fx, 1.0),
          COALESCE(v_item_record.amount_contract_currency, v_item_record.subtotal, 0),
          COALESCE(v_item_record.matched_amount_invoice, v_item_record.subtotal, 0),
          v_item_quantity, v_item_unit_of_measure, 'confirmed', 'Reconciliación masiva',
          p_user_id, p_user_id, NOW(), v_holding_id
        )
        ON CONFLICT (invoice_item_legacy_id)
        DO UPDATE SET
          status = 'confirmed',
          confirmed_by = p_user_id,
          confirmed_at = NOW();
      END LOOP;

      UPDATE public.invoices_legacy
      SET reconciliation_status = 'migrated',
          contract_id = p_contract_id
      WHERE id = v_invoice_id;

      PERFORM public.update_legacy_reconciliation_pct(p_contract_id);

      v_reconciled_count := v_reconciled_count + 1;

    EXCEPTION WHEN OTHERS THEN
      v_failed_count := v_failed_count + 1;
      v_errors := v_errors || jsonb_build_object(
        'invoice_id', v_invoice_id,
        'error', SQLERRM
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'reconciled_count', v_reconciled_count,
    'failed_count', v_failed_count,
    'errors', v_errors
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.bulk_reconcile_legacy_invoices(p_contract_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_holding_id uuid;
  v_invoice_record record;
  v_item_record record;
  v_invoice_id uuid;
  v_contract_record record;
  v_reconciled_count integer := 0;
  v_failed_count integer := 0;
  v_errors jsonb := '[]'::jsonb;
  v_new_invoice_id uuid;
  v_subtotal_invoice_currency numeric;
  v_subtotal_contract_currency numeric;
  v_tax_rate numeric;
  v_tax_amount_invoice_currency numeric;
  v_tax_amount_contract_currency numeric;
  v_total_invoice_currency numeric;
  v_system_currency text;
  v_fx_contract_to_system numeric;
  v_fx_contract_to_invoice numeric;
  v_amount_system_currency numeric;
  v_total_system_currency numeric;
  v_company_tax_rate numeric;
  v_total_legacy numeric;
  v_total_pending numeric;
  v_item_subtotal_invoice numeric;
  v_item_unit_price_invoice numeric;
BEGIN
  v_holding_id := get_current_user_holding_id();

  IF v_holding_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Usuario no tiene holding_id asignado',
      'reconciled_count', 0,
      'failed_count', 0
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_holdings
    WHERE user_id = auth.uid() AND holding_id = v_holding_id
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Usuario no tiene permisos para este holding',
      'reconciled_count', 0,
      'failed_count', 0
    );
  END IF;

  SELECT * INTO v_contract_record
  FROM public.contracts
  WHERE id = p_contract_id
    AND holding_id = v_holding_id
    AND is_legacy = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Contrato no encontrado, no pertenece al holding o no es legacy',
      'reconciled_count', 0,
      'failed_count', 0
    );
  END IF;

  SELECT
    hs.system_currency,
    COALESCE(
      (SELECT rate FROM public.fx_rates
       WHERE holding_id = v_holding_id
         AND from_currency = v_contract_record.contract_currency
         AND to_currency = hs.system_currency
         AND effective_date <= CURRENT_DATE
       ORDER BY effective_date DESC
       LIMIT 1),
      1.0
    ) as fx_rate
  INTO v_system_currency, v_fx_contract_to_system
  FROM public.holding_settings hs
  WHERE hs.holding_id = v_holding_id;

  v_system_currency := COALESCE(v_system_currency, 'USD');
  v_fx_contract_to_system := COALESCE(v_fx_contract_to_system, 1.0);

  FOR v_invoice_record IN
    SELECT
      il.*,
      c.tax_rate as company_tax_rate
    FROM public.invoices_legacy il
    LEFT JOIN public.companies c ON c.id = il.company_id
    WHERE il.contract_id = p_contract_id
      AND il.holding_id = v_holding_id
      AND il.reconciliation_status != 'confirmed'
    ORDER BY il.issue_date
  LOOP
    BEGIN
      v_invoice_id := v_invoice_record.id;

      v_tax_rate := v_invoice_record.company_tax_rate;
      IF v_tax_rate IS NULL THEN
        v_failed_count := v_failed_count + 1;
        v_errors := v_errors || jsonb_build_object(
          'invoice_id', v_invoice_id,
          'error', 'TAX_RATE_NOT_CONFIGURED: Company sin tax_rate configurado'
        );
        CONTINUE;
      END IF;
      v_tax_rate := v_tax_rate / 100.0;

      IF EXISTS (
        SELECT 1 FROM public.invoices
        WHERE legacy_invoice_id = v_invoice_id
          AND is_legacy = true
      ) THEN
        v_failed_count := v_failed_count + 1;
        v_errors := v_errors || jsonb_build_object(
          'invoice_id', v_invoice_id,
          'error', 'Factura ya reconciliada'
        );
        CONTINUE;
      END IF;

      SELECT
        COALESCE(SUM(COALESCE(m.amount_invoice_currency, il.subtotal)), 0),
        COALESCE(SUM(COALESCE(m.amount_invoice_currency, il.subtotal) * v_tax_rate), 0),
        COALESCE(SUM(COALESCE(m.amount_invoice_currency, il.subtotal) * (1 + v_tax_rate)), 0)
      INTO
        v_subtotal_invoice_currency,
        v_tax_amount_invoice_currency,
        v_total_invoice_currency
      FROM public.invoice_items_legacy il
      LEFT JOIN public.invoice_items_legacy_match m ON m.invoice_item_legacy_id = il.id
      WHERE il.invoices_legacy_id = v_invoice_id;

      SELECT
        COALESCE(SUM(m.amount_contract_currency), 0)
      INTO v_subtotal_contract_currency
      FROM public.invoice_items_legacy il
      LEFT JOIN public.invoice_items_legacy_match m ON m.invoice_item_legacy_id = il.id
      WHERE il.invoices_legacy_id = v_invoice_id;

      IF v_subtotal_contract_currency = 0 THEN
        v_subtotal_contract_currency := v_subtotal_invoice_currency;
      END IF;

      v_tax_amount_contract_currency := v_subtotal_contract_currency * v_tax_rate;

      IF v_subtotal_contract_currency > 0 THEN
        v_fx_contract_to_invoice := v_subtotal_invoice_currency / v_subtotal_contract_currency;
      ELSE
        v_fx_contract_to_invoice := 1.0;
      END IF;

      v_amount_system_currency := v_subtotal_contract_currency * v_fx_contract_to_system;
      v_total_system_currency := v_subtotal_contract_currency * (1 + v_tax_rate) * v_fx_contract_to_system;

        INSERT INTO public.invoices (
          holding_id, contract_id, client_id, client_entity_id, company_id,
          invoice_number, issue_date, original_issue_date, due_date,
          invoice_currency, contract_currency, system_currency,
          subtotal_invoice_currency, tax_amount_invoice_currency, total_invoice_currency,
          amount_invoice_currency, amount_contract_currency, amount_system_currency, total_system_currency,
          vat, tax_rate, fx_contract_to_invoice, fx_contract_to_system,
          status, is_legacy, legacy_invoice_id, legacy_source_system, pdf_url, notes
        )
        VALUES (
          v_holding_id, p_contract_id, v_contract_record.client_id, v_contract_record.client_entity_id, v_invoice_record.company_id,
          v_invoice_record.invoice_number, v_invoice_record.issue_date, v_invoice_record.issue_date, v_invoice_record.due_date,
          v_invoice_record.invoice_currency, v_contract_record.contract_currency, v_system_currency,
          v_subtotal_invoice_currency, v_tax_amount_invoice_currency, v_total_invoice_currency,
          v_subtotal_invoice_currency, v_subtotal_contract_currency, v_amount_system_currency, v_total_system_currency,
          v_tax_amount_invoice_currency, v_tax_rate, v_fx_contract_to_invoice, v_fx_contract_to_system,
          COALESCE(v_invoice_record.status, 'Pagada'), true, v_invoice_id,
          COALESCE(v_invoice_record.source_system, 'Legacy Import'), v_invoice_record.pdf_url,
          'Migrada desde factura legacy mediante reconciliación masiva. ' || COALESCE(v_invoice_record.notes, '')
        )
        RETURNING id INTO v_new_invoice_id;

      FOR v_item_record IN
        SELECT
          il.*,
          m.amount_contract_currency,
          m.amount_invoice_currency as matched_amount_invoice,
          m.contract_item_id,
          ci.product_name,
          ci.unit_price as contract_unit_price,
          ci.currency as contract_currency,
          ci.unit_of_measure,
          ci.quantity as contract_quantity
        FROM public.invoice_items_legacy il
        LEFT JOIN public.invoice_items_legacy_match m ON m.invoice_item_legacy_id = il.id
        LEFT JOIN public.contract_items ci ON ci.id = m.contract_item_id
        WHERE il.invoices_legacy_id = v_invoice_id
      LOOP
        v_item_subtotal_invoice := COALESCE(v_item_record.matched_amount_invoice, v_item_record.subtotal);
        v_item_unit_price_invoice := CASE
          WHEN COALESCE(v_item_record.quantity, 1) > 0
          THEN v_item_subtotal_invoice / v_item_record.quantity
          ELSE v_item_subtotal_invoice
        END;

        INSERT INTO public.invoice_items (
          holding_id, invoice_id, contract_item_id, product_name, quantity, unit_of_measure,
          unit_price_contract_currency, unit_price_invoice_currency,
          subtotal_contract_currency, subtotal_invoice_currency,
          tax_rate, tax_amount_contract_currency, tax_amount_invoice_currency,
          total_contract_currency, total_invoice_currency, notes
        )
        VALUES (
          v_holding_id, v_new_invoice_id, v_item_record.contract_item_id,
          COALESCE(v_item_record.product_name, v_item_record.description),
          COALESCE(v_item_record.quantity, 1), v_item_record.unit_of_measure,
          COALESCE(v_item_record.contract_unit_price, v_item_record.unit_price), v_item_unit_price_invoice,
          COALESCE(v_item_record.amount_contract_currency, v_item_record.subtotal), v_item_subtotal_invoice,
          v_tax_rate,
          COALESCE(v_item_record.amount_contract_currency, v_item_record.subtotal) * v_tax_rate,
          v_item_subtotal_invoice * v_tax_rate,
          COALESCE(v_item_record.amount_contract_currency, v_item_record.subtotal) * (1 + v_tax_rate),
          v_item_subtotal_invoice * (1 + v_tax_rate),
          'Migrado desde item legacy. ' || COALESCE(v_item_record.notes, '')
        );
      END LOOP;

      UPDATE public.invoices_legacy
      SET reconciliation_status = 'confirmed',
          reconciled_invoice_id = v_new_invoice_id
      WHERE id = v_invoice_id;

      v_reconciled_count := v_reconciled_count + 1;

    EXCEPTION WHEN OTHERS THEN
      v_failed_count := v_failed_count + 1;
      v_errors := v_errors || jsonb_build_object(
        'invoice_id', v_invoice_id,
        'error', SQLERRM
      );
    END;
  END LOOP;

  SELECT COALESCE(SUM(amount_contract_currency), 0)
  INTO v_total_legacy
  FROM invoices
  WHERE contract_id = p_contract_id
    AND COALESCE(is_legacy, false) = true;

  v_total_pending := COALESCE(v_contract_record.total_value, 0) - v_total_legacy;

  UPDATE contract_invoices
  SET is_satisfied = true,
      updated_at = NOW()
  WHERE contract_id = p_contract_id;

  RAISE NOTICE '[BULK_RECONCILE] Marked all contract_invoices as satisfied for contract %', p_contract_id;

  IF v_total_pending > 0 THEN
    INSERT INTO contract_invoices (
      contract_id, holding_id, invoice_date, amount, currency, status, is_satisfied, is_editable, contract_item_details
    ) VALUES (
      p_contract_id, v_holding_id,
      COALESCE(v_contract_record.legacy_cutoff_date, CURRENT_DATE) + INTERVAL '1 day',
      v_total_pending, v_contract_record.contract_currency,
      'Programada', false, true, '[]'::jsonb
    );

    RAISE NOTICE '[BULK_RECONCILE] Created pending contract_invoice for % % (difference)',
      v_total_pending, v_contract_record.contract_currency;
  ELSE
    RAISE NOTICE '[BULK_RECONCILE] No pending amount, all invoices covered by legacy';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'reconciled_count', v_reconciled_count,
    'failed_count', v_failed_count,
    'errors', v_errors,
    'total_legacy', v_total_legacy,
    'total_pending', v_total_pending
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.bulk_restructure_contract_start_dates(p_contract_ids uuid[], p_cutoff_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_holding_id uuid;
  v_contract_id       uuid;
  v_processed         jsonb := '[]'::jsonb;
  v_skipped           jsonb := '[]'::jsonb;
  v_errors            jsonb := '[]'::jsonb;
  v_new_min_start     date;
  v_items_updated     int;
  v_inv_deleted       int;
  v_status            text;
  v_contract_holding  uuid;
  v_has_erp_invoice   boolean;
  v_regen_result      jsonb;
  v_gen_count         int;
  v_gen_record        record;
BEGIN
  IF p_contract_ids IS NULL OR array_length(p_contract_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('processed', '[]'::jsonb, 'skipped', '[]'::jsonb, 'errors', '[]'::jsonb);
  END IF;
  IF p_cutoff_date IS NULL THEN
    RAISE EXCEPTION 'p_cutoff_date no puede ser NULL';
  END IF;

  v_caller_holding_id := get_current_user_holding_id();
  IF v_caller_holding_id IS NULL THEN
    RAISE EXCEPTION 'Caller sin holding válido';
  END IF;

  FOREACH v_contract_id IN ARRAY p_contract_ids LOOP
    BEGIN
      SELECT status, holding_id
        INTO v_status, v_contract_holding
        FROM contracts
       WHERE id = v_contract_id;

      IF NOT FOUND THEN
        v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
          'contract_id', v_contract_id, 'reason', 'not_found'));
        CONTINUE;
      END IF;

      IF v_contract_holding IS DISTINCT FROM v_caller_holding_id THEN
        v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
          'contract_id', v_contract_id, 'reason', 'forbidden_holding'));
        CONTINUE;
      END IF;

      SELECT EXISTS (
        SELECT 1 FROM invoices
         WHERE contract_id = v_contract_id
           AND odoo_invoice_id IS NOT NULL
           AND COALESCE(is_legacy, false) = false
           AND is_active = true
      ) INTO v_has_erp_invoice;

      IF v_has_erp_invoice THEN
        v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
          'contract_id', v_contract_id, 'reason', 'has_erp_invoice'));
        CONTINUE;
      END IF;

      WITH shifted AS (
        UPDATE contract_items
           SET start_date  = compute_new_contract_start(start_date, p_cutoff_date),
               term_months = GREATEST(1, months_between_dates(
                               (end_date + INTERVAL '1 day')::date,
                               compute_new_contract_start(start_date, p_cutoff_date)
                             ))
         WHERE contract_id = v_contract_id
           AND start_date IS NOT NULL
           AND term_months IS NOT NULL
           AND end_date IS NOT NULL
           AND start_date <= p_cutoff_date
           AND end_date > p_cutoff_date
        RETURNING start_date
      )
      SELECT MIN(start_date), COUNT(*) INTO v_new_min_start, v_items_updated FROM shifted;

      IF COALESCE(v_items_updated, 0) = 0 THEN
        v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
          'contract_id', v_contract_id, 'reason', 'no_items_to_shift'));
        CONTINUE;
      END IF;

      UPDATE contracts
         SET booking_date       = v_new_min_start,
             legacy_cutoff_date = p_cutoff_date
       WHERE id = v_contract_id;

      DELETE FROM invoice_items
       WHERE invoice_id IN (
         SELECT id FROM invoices
          WHERE contract_id = v_contract_id
            AND status = 'Por Emitir'
       );
      WITH del AS (
        DELETE FROM invoices
         WHERE contract_id = v_contract_id
           AND status = 'Por Emitir'
        RETURNING id
      )
      SELECT COUNT(*) INTO v_inv_deleted FROM del;

      v_regen_result := regenerate_contract_invoices_for_restructure(v_contract_id);
      IF NOT COALESCE((v_regen_result->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'regenerate_contract_invoices_for_restructure failed: %',
          COALESCE(v_regen_result->>'error', 'unknown');
      END IF;

      v_gen_count := 0;
      IF v_status = 'Activo' THEN
        FOR v_gen_record IN
          SELECT * FROM generate_missing_invoices_for_contract(v_contract_id)
        LOOP
          v_gen_count := COALESCE(v_gen_record.generated_count, 0);
        END LOOP;
      END IF;

      v_processed := v_processed || jsonb_build_array(jsonb_build_object(
        'contract_id',             v_contract_id,
        'status',                  v_status,
        'new_start_date',          v_new_min_start,
        'items_updated',           v_items_updated,
        'invoices_deleted',        v_inv_deleted,
        'contract_invoices_regen', COALESCE((v_regen_result->>'invoices_created')::int, 0),
        'invoices_regen',          v_gen_count
      ));

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'contract_id', v_contract_id,
        'error',       SQLERRM
      ));
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', v_processed,
    'skipped',   v_skipped,
    'errors',    v_errors
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_billing_period(p_item_start_date date, p_period_index integer, p_frequency_months integer, p_billing_method text)
 RETURNS TABLE(period_start date, period_end date, scheduled_date date)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_period_start DATE;
  v_period_end DATE;
  v_scheduled_date DATE;
BEGIN
  -- Calcular inicio del periodo
  v_period_start := p_item_start_date + (p_period_index * p_frequency_months || ' months')::INTERVAL;

  -- Calcular fin del periodo (un día antes del siguiente periodo)
  v_period_end := p_item_start_date + ((p_period_index + 1) * p_frequency_months || ' months')::INTERVAL - INTERVAL '1 day';

  -- Calcular fecha de emisión según método de facturación
  IF LOWER(p_billing_method) LIKE '%vencid%' OR LOWER(p_billing_method) LIKE '%arrear%' THEN
    -- Vencido: facturar un periodo después del inicio
    v_scheduled_date := p_item_start_date + ((p_period_index + 1) * p_frequency_months || ' months')::INTERVAL;
  ELSE
    -- Anticipado: facturar al inicio del periodo
    v_scheduled_date := v_period_start;
  END IF;

  RETURN QUERY SELECT v_period_start, v_period_end, v_scheduled_date;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_contract_fx_amounts(p_contract_id uuid)
 RETURNS TABLE(success boolean, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_contract RECORD;
    v_holding_id uuid;
    v_system_currency text;
    v_fx_policy text;
    v_fx_rate_system numeric;
    v_total_system numeric;
    v_fx_result RECORD;
BEGIN
    -- Get contract data
    SELECT * INTO v_contract
    FROM public.contracts
    WHERE id = p_contract_id;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 'Contract not found';
        RETURN;
    END IF;

    v_holding_id := v_contract.holding_id;

    -- Get system currency and FX policy
    SELECT hs.system_currency, COALESCE(hs.fx_system_policy, 'monthly_avg')
    INTO v_system_currency, v_fx_policy
    FROM public.holding_settings hs
    WHERE hs.holding_id = v_holding_id;

    IF v_system_currency IS NULL THEN
        RETURN QUERY SELECT false, 'System currency not configured for holding';
        RETURN;
    END IF;

    -- =====================================================
    -- Calculate FX to system currency
    -- =====================================================
    IF v_contract.contract_currency = v_system_currency THEN
        v_fx_rate_system := 1.0;
        v_total_system := v_contract.total_value;
    ELSE
        SELECT rate, source, reference_date
        INTO v_fx_result
        FROM public.calculate_system_fx_rate(
            v_holding_id,
            v_contract.contract_currency,
            v_system_currency,
            COALESCE(v_contract.booking_date, CURRENT_DATE),
            COALESCE(v_fx_policy, 'monthly_avg')
        );

        IF v_fx_result.rate IS NULL OR v_fx_result.rate = 0 THEN
            RETURN QUERY
            SELECT
                false,
                'No FX rate found for ' || v_contract.contract_currency || ' -> ' || v_system_currency ||
                ' (holding_id=' || v_holding_id || ', booking_date=' ||
                COALESCE(v_contract.booking_date, CURRENT_DATE)::text ||
                ', policy=' || COALESCE(v_fx_policy, 'monthly_avg') ||
                ', source=' || COALESCE(v_fx_result.source, 'null') ||
                ', reference_date=' || COALESCE(v_fx_result.reference_date::text, 'null') || ')';
            RETURN;
        END IF;

        v_fx_rate_system := v_fx_result.rate;

        -- DIVIDE by fx_rate because rates are configured as inverse (1 USD = X currency)
        v_total_system := v_contract.total_value / NULLIF(v_fx_rate_system, 0);
    END IF;

    UPDATE public.contracts
    SET
        fx_rate_to_system = v_fx_rate_system,
        total_value_system_currency = ROUND(v_total_system, 2),
        system_currency = v_system_currency
    WHERE id = p_contract_id;

    RETURN QUERY SELECT true, 'FX amounts calculated successfully';

EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT false, 'Error calculating FX amounts: ' || SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_contract_fx_amounts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_company_currency text;
  v_system_currency text;
  v_fx_policy text;
  v_rate_to_company numeric;
  v_rate_to_system numeric;
BEGIN
  -- Obtener moneda de la compañía desde la tabla companies
  SELECT currency INTO v_company_currency
  FROM public.companies
  WHERE id = NEW.company_id;

  -- Obtener moneda del sistema desde holding_settings
  SELECT system_currency INTO v_system_currency
  FROM public.holding_settings
  WHERE holding_id = NEW.holding_id;

  -- Si no hay configuración, usar USD como default
  v_company_currency := COALESCE(v_company_currency, 'USD');
  v_system_currency := COALESCE(v_system_currency, 'USD');

  -- Guardar monedas en el contrato
  NEW.company_currency := v_company_currency;
  NEW.system_currency := v_system_currency;

  -- Calcular tasas FX si las monedas son diferentes
  IF NEW.contract_currency = v_company_currency THEN
    NEW.fx_rate_to_company := 1.0;
    NEW.total_value_company_currency := NEW.total_value;
  ELSE
    -- Obtener política FX (si está configurada en el contrato)
    v_fx_policy := COALESCE(NEW.fx_company_policy, 'monthly_avg');

    -- Usar la función fx_rate_v2 para obtener la tasa
    SELECT fx_rate_v2(
      NEW.contract_currency,
      v_company_currency,
      COALESCE(NEW.booking_date, CURRENT_DATE),
      v_fx_policy,
      NEW.holding_id
    ) INTO v_rate_to_company;

    NEW.fx_rate_to_company := COALESCE(v_rate_to_company, 1.0);
    NEW.total_value_company_currency := NEW.total_value * NEW.fx_rate_to_company;
  END IF;

  -- Calcular conversión a moneda del sistema
  IF NEW.contract_currency = v_system_currency THEN
    NEW.fx_rate_to_system := 1.0;
    NEW.total_value_system_currency := NEW.total_value;
  ELSE
    -- Obtener política FX del sistema desde holding_settings
    SELECT fx_system_policy INTO v_fx_policy
    FROM public.holding_settings
    WHERE holding_id = NEW.holding_id;

    v_fx_policy := COALESCE(v_fx_policy, 'monthly_avg');

    SELECT fx_rate_v2(
      NEW.contract_currency,
      v_system_currency,
      COALESCE(NEW.booking_date, CURRENT_DATE),
      v_fx_policy,
      NEW.holding_id
    ) INTO v_rate_to_system;

    NEW.fx_rate_to_system := COALESCE(v_rate_to_system, 1.0);
    NEW.total_value_system_currency := NEW.total_value * NEW.fx_rate_to_system;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_contract_fx_rate(p_contract_id uuid, p_conversion_type fx_conversion_type, p_date date)
 RETURNS TABLE(rate numeric, source text, reference_date date)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_policy RECORD;
  v_contract RECORD;
  v_from_currency TEXT;
  v_to_currency TEXT;
  v_rate NUMERIC;
  v_source TEXT;
  v_ref_date DATE;
  v_holding_settings RECORD;
  v_period_rate RECORD;
BEGIN
  -- Obtener contrato con holding_id
  SELECT 
    c.id,
    c.contract_currency,
    c.company_currency,
    c.system_currency,
    c.holding_id
  INTO v_contract
  FROM public.contracts c
  WHERE c.id = p_contract_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contrato no encontrado: %', p_contract_id;
  END IF;

  -- Determinar monedas origen y destino
  IF p_conversion_type = 'to_company' THEN
    v_from_currency := v_contract.contract_currency;
    v_to_currency := v_contract.company_currency;
  ELSE -- to_system
    v_from_currency := v_contract.contract_currency;
    v_to_currency := v_contract.system_currency;
  END IF;

  -- Si las monedas son iguales, retornar 1
  IF v_from_currency = v_to_currency THEN
    RETURN QUERY SELECT 1.0::NUMERIC, 'same_currency'::TEXT, p_date;
    RETURN;
  END IF;

  -- Obtener política FX del contrato
  SELECT *
  INTO v_policy
  FROM public.contract_fx_policies
  WHERE contract_id = p_contract_id;

  -- Si no hay política, usar holding_default
  IF NOT FOUND THEN
    v_policy.company_fx_policy := 'holding_default'::fx_policy_type;
    v_policy.system_fx_policy := 'holding_default'::fx_policy_type;
  END IF;

  -- Obtener configuración del holding
  SELECT fx_strategy
  INTO v_holding_settings
  FROM public.holding_fx_settings
  WHERE holding_id = v_contract.holding_id;

  -- Aplicar política según tipo de conversión
  IF p_conversion_type = 'to_company' THEN
    CASE v_policy.company_fx_policy
      WHEN 'holding_default' THEN
        -- Usar estrategia del holding (spot o monthly_avg)
        IF v_holding_settings.fx_strategy = 'spot_or_invoice' THEN
          v_rate := fx_rate_with_indirect(p_date, v_from_currency, v_to_currency);
          v_source := 'spot';
        ELSIF v_holding_settings.fx_strategy = 'monthly_average' THEN
          -- Calcular promedio del mes
          SELECT AVG(rate)
          INTO v_rate
          FROM (
            SELECT fx_rate_with_indirect(d::DATE, v_from_currency, v_to_currency) AS rate
            FROM generate_series(
              date_trunc('month', p_date)::DATE,
              (date_trunc('month', p_date) + INTERVAL '1 month - 1 day')::DATE,
              '1 day'::INTERVAL
            ) d
            WHERE d::DATE <= p_date
          ) rates
          WHERE rate IS NOT NULL AND rate > 0;
          v_source := 'monthly_avg';
        END IF;

      WHEN 'spot' THEN
        v_rate := fx_rate_with_indirect(p_date, v_from_currency, v_to_currency);
        v_source := 'spot';

      WHEN 'monthly_avg' THEN
        SELECT AVG(rate)
        INTO v_rate
        FROM (
          SELECT fx_rate_with_indirect(d::DATE, v_from_currency, v_to_currency) AS rate
          FROM generate_series(
            date_trunc('month', p_date)::DATE,
            (date_trunc('month', p_date) + INTERVAL '1 month - 1 day')::DATE,
            '1 day'::INTERVAL
          ) d
          WHERE d::DATE <= p_date
        ) rates
        WHERE rate IS NOT NULL AND rate > 0;
        v_source := 'monthly_avg';

      WHEN 'fixed' THEN
        v_rate := v_policy.company_fx_fixed_rate;
        v_source := 'fixed';

      WHEN 'period_fixed', 'table' THEN
        -- Buscar tasa del período
        SELECT rate, period_start
        INTO v_period_rate
        FROM public.contract_fx_policy_rates
        WHERE fx_policy_id = v_policy.id
          AND conversion_type = 'to_company'
          AND p_date >= period_start
          AND p_date <= period_end
        ORDER BY period_start DESC
        LIMIT 1;

        IF FOUND THEN
          v_rate := v_period_rate.rate;
          v_source := 'period_table';
          v_ref_date := v_period_rate.period_start;
        ELSE
          -- Fallback a spot si no hay tasa del período
          v_rate := fx_rate_with_indirect(p_date, v_from_currency, v_to_currency);
          v_source := 'spot_fallback';
        END IF;
    END CASE;

  ELSE -- to_system
    CASE v_policy.system_fx_policy
      WHEN 'holding_default' THEN
        IF v_holding_settings.fx_strategy = 'spot_or_invoice' THEN
          v_rate := fx_rate_with_indirect(p_date, v_from_currency, v_to_currency);
          v_source := 'spot';
        ELSIF v_holding_settings.fx_strategy = 'monthly_average' THEN
          SELECT AVG(rate)
          INTO v_rate
          FROM (
            SELECT fx_rate_with_indirect(d::DATE, v_from_currency, v_to_currency) AS rate
            FROM generate_series(
              date_trunc('month', p_date)::DATE,
              (date_trunc('month', p_date) + INTERVAL '1 month - 1 day')::DATE,
              '1 day'::INTERVAL
            ) d
            WHERE d::DATE <= p_date
          ) rates
          WHERE rate IS NOT NULL AND rate > 0;
          v_source := 'monthly_avg';
        END IF;

      WHEN 'spot' THEN
        v_rate := fx_rate_with_indirect(p_date, v_from_currency, v_to_currency);
        v_source := 'spot';

      WHEN 'monthly_avg' THEN
        SELECT AVG(rate)
        INTO v_rate
        FROM (
          SELECT fx_rate_with_indirect(d::DATE, v_from_currency, v_to_currency) AS rate
          FROM generate_series(
            date_trunc('month', p_date)::DATE,
            (date_trunc('month', p_date) + INTERVAL '1 month - 1 day')::DATE,
            '1 day'::INTERVAL
          ) d
          WHERE d::DATE <= p_date
        ) rates
        WHERE rate IS NOT NULL AND rate > 0;
        v_source := 'monthly_avg';

      WHEN 'fixed' THEN
        v_rate := v_policy.system_fx_fixed_rate;
        v_source := 'fixed';

      WHEN 'period_fixed', 'table' THEN
        SELECT rate, period_start
        INTO v_period_rate
        FROM public.contract_fx_policy_rates
        WHERE fx_policy_id = v_policy.id
          AND conversion_type = 'to_system'
          AND p_date >= period_start
          AND p_date <= period_end
        ORDER BY period_start DESC
        LIMIT 1;

        IF FOUND THEN
          v_rate := v_period_rate.rate;
          v_source := 'period_table';
          v_ref_date := v_period_rate.period_start;
        ELSE
          v_rate := fx_rate_with_indirect(p_date, v_from_currency, v_to_currency);
          v_source := 'spot_fallback';
        END IF;
    END CASE;
  END IF;

  -- Retornar resultado
  RETURN QUERY SELECT 
    COALESCE(v_rate, 1.0),
    COALESCE(v_source, 'fallback'),
    COALESCE(v_ref_date, p_date);
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_fx_suggestion(p_from_currency text, p_to_currency text, p_reference_date date)
 RETURNS TABLE(suggested_rate numeric, rate_source text, rate_date date, confidence text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rate NUMERIC;
  v_source TEXT;
  v_date DATE;
BEGIN
  IF p_from_currency = p_to_currency THEN
    RETURN QUERY SELECT 1.0::NUMERIC, 'same_currency'::TEXT, p_reference_date, 'high'::TEXT;
    RETURN;
  END IF;

  SELECT avg_rate, 'monthly_avg', DATE(p_reference_date)
  INTO v_rate, v_source, v_date
  FROM exchange_rates_monthly_avg
  WHERE from_currency = p_from_currency
    AND to_currency = p_to_currency
    AND year = EXTRACT(YEAR FROM p_reference_date)
    AND month = EXTRACT(MONTH FROM p_reference_date)
  LIMIT 1;

  IF v_rate IS NOT NULL THEN
    RETURN QUERY SELECT v_rate, v_source, v_date, 'high'::TEXT;
    RETURN;
  END IF;

  SELECT rate, 'daily_rate', rate_date
  INTO v_rate, v_source, v_date
  FROM exchange_rates
  WHERE from_currency = p_from_currency
    AND to_currency = p_to_currency
    AND rate_date = p_reference_date
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_rate IS NOT NULL THEN
    RETURN QUERY SELECT v_rate, v_source, v_date, 'medium'::TEXT;
    RETURN;
  END IF;

  SELECT rate, 'nearest_rate', rate_date
  INTO v_rate, v_source, v_date
  FROM exchange_rates
  WHERE from_currency = p_from_currency
    AND to_currency = p_to_currency
    AND ABS(rate_date - p_reference_date) <= 7
  ORDER BY ABS(rate_date - p_reference_date), created_at DESC
  LIMIT 1;

  IF v_rate IS NOT NULL THEN
    RETURN QUERY SELECT v_rate, v_source, v_date, 'low'::TEXT;
    RETURN;
  END IF;

  RETURN QUERY SELECT NULL::NUMERIC, 'not_found'::TEXT, NULL::DATE, 'none'::TEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_monthly_and_period_prices(p_unit_price numeric, p_quantity numeric, p_billing_frequency text, p_is_recurring boolean, p_final_price numeric DEFAULT NULL::numeric, p_term_months integer DEFAULT NULL::integer, p_discount_type text DEFAULT NULL::text, p_discount_value numeric DEFAULT NULL::numeric)
 RETURNS TABLE(monthly_price numeric, billing_period_price numeric)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_monthly_price NUMERIC;
  v_billing_period_price NUMERIC;
  v_frequency_multiplier INTEGER;
  v_term_months INTEGER;
  v_monthly_equivalent NUMERIC;
  v_base_monthly_price NUMERIC;
BEGIN
  -- Calcular monthly_price
  -- Para items recurrentes: (unit_price × quantity) con descuento aplicado
  IF COALESCE(p_is_recurring, false) THEN
    -- Calcular precio base mensual (unit_price × quantity)
    v_base_monthly_price := COALESCE(p_unit_price, 0) * COALESCE(p_quantity, 1);

    -- Aplicar descuento según el tipo
    IF p_discount_value IS NOT NULL AND p_discount_value > 0 AND p_discount_type IS NOT NULL THEN
      IF p_discount_type = 'Porcentaje' THEN
        -- Para descuento porcentual: aplicar % al precio mensual base
        v_monthly_price := v_base_monthly_price * (1 - p_discount_value / 100.0);
      ELSIF p_discount_type = 'Monto fijo' THEN
        -- Para descuento de monto fijo: usar final_price / term_months
        -- final_price ya tiene el descuento aplicado al total del contrato
        IF p_final_price IS NOT NULL AND p_term_months IS NOT NULL AND p_term_months > 0 THEN
          v_monthly_price := p_final_price / p_term_months;
        ELSE
          -- Fallback: aplicar descuento directo (puede no ser correcto)
          v_monthly_price := v_base_monthly_price - p_discount_value;
        END IF;
      ELSE
        v_monthly_price := v_base_monthly_price;
      END IF;
    ELSE
      -- Sin descuento
      v_monthly_price := v_base_monthly_price;
    END IF;

    -- Asegurar que el precio no sea negativo y redondear
    v_monthly_price := GREATEST(ROUND(v_monthly_price, 2), 0);
  ELSE
    v_monthly_price := NULL;
  END IF;

  -- Determinar multiplicador de frecuencia de facturación
  CASE LOWER(COALESCE(p_billing_frequency, 'mensual'))
    WHEN 'mensual' THEN v_frequency_multiplier := 1;
    WHEN 'trimestral' THEN v_frequency_multiplier := 3;
    WHEN 'semestral' THEN v_frequency_multiplier := 6;
    WHEN 'anual' THEN v_frequency_multiplier := 12;
    WHEN 'bianual' THEN v_frequency_multiplier := 24;
    ELSE v_frequency_multiplier := 1;
  END CASE;

  -- Calcular billing_period_price
  IF COALESCE(p_is_recurring, false) THEN
    -- Para recurrentes: monthly_price × frequency_multiplier
    v_billing_period_price := ROUND(
      COALESCE(v_monthly_price, 0) * v_frequency_multiplier, 
      2
    );
  ELSE
    -- Para one-time: calcular precio mensual equivalente y multiplicar por frecuencia
    v_term_months := GREATEST(COALESCE(p_term_months, 1), 1);
    v_monthly_equivalent := COALESCE(p_final_price, 0) / v_term_months;
    v_billing_period_price := ROUND(v_monthly_equivalent * v_frequency_multiplier, 2);
  END IF;

  RETURN QUERY SELECT v_monthly_price, v_billing_period_price;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_mrr_legacy_fields()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.is_recurring THEN
    -- MRR = subtotal_contract_currency / term
    NEW.mrr_legacy := NEW.subtotal_contract_currency / NEW.term;
    NEW.momentum := 'EOP';
  ELSE
    NEW.mrr_legacy := NULL;
    NEW.momentum := NULL;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.change_contract_commercial_client(p_contract_id uuid, p_new_client_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_contract record;
  v_new_client record;
  v_new_entity record;
  v_holding_id uuid;
  v_old_client_name text;
  v_new_client_name text;
BEGIN
  -- Obtener holding del usuario actual
  SELECT get_current_user_holding_id() INTO v_holding_id;

  IF v_holding_id IS NULL THEN
    RAISE EXCEPTION 'No se pudo obtener el holding del usuario';
  END IF;

  -- Obtener datos del contrato
  SELECT * INTO v_contract
  FROM contracts
  WHERE id = p_contract_id
    AND holding_id = v_holding_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contrato no encontrado o no pertenece al holding del usuario';
  END IF;

  -- Validar que el contrato NO esté en estado Activo, Firmado, Cancelado o Expirado
  IF v_contract.status IN ('Activo', 'Firmado', 'Cancelado', 'Expirado') THEN
    RAISE EXCEPTION 'No se puede cambiar el cliente comercial de un contrato en estado: %', v_contract.status;
  END IF;

  -- Obtener datos del nuevo cliente comercial
  SELECT * INTO v_new_client
  FROM clients
  WHERE id = p_new_client_id
    AND holding_id = v_holding_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente comercial no encontrado o no pertenece al holding del usuario';
  END IF;

  -- Guardar nombre del cliente anterior para el log
  SELECT name_commercial INTO v_old_client_name
  FROM clients
  WHERE id = v_contract.client_id;

  v_new_client_name := v_new_client.name_commercial;

  -- Buscar una client_entity que tenga el mismo tax_id y esté asignada al nuevo cliente
  -- AHORA usando la junction table
  IF v_contract.client_entity_id IS NOT NULL THEN
    SELECT ce.* INTO v_new_entity
    FROM client_entities ce
    INNER JOIN client_entity_clients cec ON cec.client_entity_id = ce.id
    WHERE cec.client_id = p_new_client_id
      AND ce.holding_id = v_holding_id
      AND ce.tax_id = (
        SELECT tax_id 
        FROM client_entities 
        WHERE id = v_contract.client_entity_id
      )
    LIMIT 1;

    -- Si no existe una entidad con el mismo tax_id para el nuevo cliente, lanzar error
    IF NOT FOUND THEN
      RAISE EXCEPTION 'No existe una razón social con el mismo Tax ID asignada al nuevo cliente comercial. Primero debes asignar la razón social al cliente.';
    END IF;
  ELSE
    -- Si el contrato no tiene client_entity_id, buscar cualquier entidad del nuevo cliente
    SELECT ce.* INTO v_new_entity
    FROM client_entities ce
    INNER JOIN client_entity_clients cec ON cec.client_entity_id = ce.id
    WHERE cec.client_id = p_new_client_id
      AND ce.holding_id = v_holding_id
    LIMIT 1;
  END IF;

  -- Actualizar el contrato con el nuevo cliente y su entidad
  UPDATE contracts
  SET 
    client_id = p_new_client_id,
    client_entity_id = v_new_entity.id,
    client_name_commercial = v_new_client.name_commercial,
    legal_client_name = v_new_entity.legal_name
  WHERE id = p_contract_id;

  -- Retornar información de la operación
  RETURN json_build_object(
    'success', true,
    'contract_id', p_contract_id,
    'old_client_id', v_contract.client_id,
    'old_client_name', v_old_client_name,
    'new_client_id', p_new_client_id,
    'new_client_name', v_new_client_name,
    'new_entity_id', v_new_entity.id,
    'message', format('Cliente comercial cambiado de "%s" a "%s"', v_old_client_name, v_new_client_name)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.change_contract_currency(p_contract_id uuid, p_new_currency text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_holding_id uuid; v_contract record;
  v_items_updated int := 0; v_invoices_updated int := 0;
BEGIN
  IF p_new_currency IS NULL OR length(trim(p_new_currency)) = 0 THEN
    RAISE EXCEPTION 'Moneda destino requerida'; END IF;
  SELECT public.get_current_user_holding_id() INTO v_holding_id;
  IF v_holding_id IS NULL THEN
    RAISE EXCEPTION 'No se pudo obtener el holding del usuario'; END IF;
  SELECT * INTO v_contract FROM public.contracts
  WHERE id = p_contract_id AND holding_id = v_holding_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contrato no encontrado o fuera del holding del usuario'; END IF;
  IF v_contract.status IN ('Firmado', 'Activo', 'Cancelado', 'Expirado') THEN
    RAISE EXCEPTION 'No se puede cambiar la moneda de un contrato en estado: %', v_contract.status; END IF;
  IF v_contract.contract_currency = p_new_currency
     AND NOT EXISTS (SELECT 1 FROM public.contract_items
       WHERE contract_id = p_contract_id AND currency IS DISTINCT FROM p_new_currency) THEN
    RETURN json_build_object('items_updated', 0, 'invoices_updated', 0, 'noop', true); END IF;
  PERFORM set_config('sapira.skip_currency_validation', 'on', true);
  UPDATE public.contracts SET contract_currency = p_new_currency
    WHERE id = p_contract_id AND contract_currency IS DISTINCT FROM p_new_currency;
  WITH upd AS (UPDATE public.contract_items SET currency = p_new_currency
    WHERE contract_id = p_contract_id AND currency IS DISTINCT FROM p_new_currency RETURNING 1)
  SELECT count(*) INTO v_items_updated FROM upd;
  WITH upd AS (UPDATE public.contract_invoices SET currency = p_new_currency
    WHERE contract_id = p_contract_id AND status = 'Programada'
      AND currency IS DISTINCT FROM p_new_currency RETURNING 1)
  SELECT count(*) INTO v_invoices_updated FROM upd;
  PERFORM set_config('sapira.skip_currency_validation', 'off', true);
  RETURN json_build_object('items_updated', v_items_updated,
    'invoices_updated', v_invoices_updated, 'noop', false);
END; $function$

CREATE OR REPLACE FUNCTION public.check_contract_item_continuity(p_contract_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ci record; v_expected_total numeric; v_actual_total numeric := 0;
  v_gaps jsonb := '[]'::jsonb; v_overlaps jsonb := '[]'::jsonb;
  v_prev_end date; v_prev_item_start date; v_prev_item_end date;
  v_item record; v_n_items int := 0; v_tolerance numeric; v_contract_id uuid;
  v_has_unified boolean := false;
BEGIN
  SELECT id, start_date, end_date, final_price, contract_id INTO v_ci
  FROM contract_items WHERE id = p_contract_item_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'contract_item no existe'); END IF;
  v_expected_total := COALESCE(v_ci.final_price, 0);
  v_contract_id := v_ci.contract_id;
  v_prev_end := v_ci.start_date - INTERVAL '1 day';
  v_prev_item_start := NULL; v_prev_item_end := NULL;

  FOR v_item IN
    -- Facturas que contienen líneas de ESTE ítem (por contract_item_id, no por
    -- el contract_id del header: así las líneas dentro de un documento
    -- unificado multi-contrato también cuentan para continuidad/conservación).
    WITH target_invoices AS (
      SELECT DISTINCT ii.invoice_id
      FROM invoice_items ii JOIN invoices i ON i.id = ii.invoice_id
      WHERE ii.contract_item_id = p_contract_item_id
        AND COALESCE(i.is_active, true) = true AND i.status <> 'Cancelada'),
    inv_items AS (
      SELECT ii.id, ii.contract_item_id, ii.billing_period_start, ii.billing_period_end,
        COALESCE(ii.subtotal_contract_currency, ii.total_contract_currency, 0) AS raw_value,
        i.id AS invoice_id, i.amount_contract_currency, i.status, i.invoice_number,
        COALESCE(i.invoice_type, '') AS invoice_type
      FROM invoice_items ii JOIN invoices i ON i.id = ii.invoice_id
      WHERE ii.invoice_id IN (SELECT invoice_id FROM target_invoices)),
    with_sum AS (SELECT *, SUM(raw_value) OVER (PARTITION BY invoice_id) AS sum_raw FROM inv_items)
    SELECT id, billing_period_start, billing_period_end,
      -- Prorrateo del header solo en facturas normales; en un documento
      -- unificado el header agrega varios contratos (y puede estar en otra
      -- moneda), así que la línea vale por sí misma.
      CASE WHEN invoice_type <> 'Unificada'
             AND amount_contract_currency IS NOT NULL AND amount_contract_currency > 0 AND sum_raw > 0
        THEN ROUND((amount_contract_currency * raw_value / sum_raw)::numeric, 2) ELSE raw_value END AS amount_net,
      status, invoice_number, invoice_type
    FROM with_sum WHERE contract_item_id = p_contract_item_id
    ORDER BY billing_period_start NULLS FIRST, id
  LOOP
    IF v_item.invoice_type IN ('Unificada', 'Consolidada') THEN v_has_unified := true; END IF;
    v_actual_total := v_actual_total + v_item.amount_net;
    v_n_items := v_n_items + 1;
    IF v_item.billing_period_start IS NULL OR v_item.billing_period_end IS NULL THEN
      v_gaps := v_gaps || jsonb_build_object('type', 'missing_period', 'item_id', v_item.id, 'invoice_number', v_item.invoice_number);
      CONTINUE;
    END IF;
    -- Cuota concurrente: mismo (start, end) que anterior → no overlap, no gap
    IF v_prev_item_start IS NOT NULL
       AND v_item.billing_period_start = v_prev_item_start
       AND v_item.billing_period_end = v_prev_item_end THEN
      v_prev_item_start := v_item.billing_period_start;
      v_prev_item_end := v_item.billing_period_end;
      IF v_item.billing_period_end > v_prev_end THEN v_prev_end := v_item.billing_period_end; END IF;
      CONTINUE;
    END IF;
    IF v_item.billing_period_start > (v_prev_end + INTERVAL '1 day')::date THEN
      v_gaps := v_gaps || jsonb_build_object('type', 'period_gap',
        'from', (v_prev_end + INTERVAL '1 day')::date, 'to', (v_item.billing_period_start - INTERVAL '1 day')::date);
    END IF;
    IF v_item.billing_period_start <= v_prev_end THEN
      v_overlaps := v_overlaps || jsonb_build_object('item_id', v_item.id,
        'overlap_start', v_item.billing_period_start, 'previous_ended_at', v_prev_end);
    END IF;
    IF v_item.billing_period_end > v_prev_end THEN v_prev_end := v_item.billing_period_end; END IF;
    v_prev_item_start := v_item.billing_period_start;
    v_prev_item_end := v_item.billing_period_end;
  END LOOP;
  IF v_prev_end < v_ci.end_date THEN
    v_gaps := v_gaps || jsonb_build_object('type', 'tail_gap',
      'from', (v_prev_end + INTERVAL '1 day')::date, 'to', v_ci.end_date);
  END IF;
  IF v_prev_end > v_ci.end_date THEN
    v_overlaps := v_overlaps || jsonb_build_object('type', 'exceeds_contract_end',
      'last_period_end', v_prev_end, 'contract_item_end', v_ci.end_date);
  END IF;
  v_tolerance := GREATEST(0.01, 0.01 * v_n_items);
  RETURN jsonb_build_object('ok', (jsonb_array_length(v_gaps) = 0 AND jsonb_array_length(v_overlaps) = 0 AND ABS(v_expected_total - v_actual_total) <= v_tolerance),
    'expected_total', v_expected_total, 'actual_total', v_actual_total,
    'delta', v_expected_total - v_actual_total, 'tolerance', v_tolerance, 'n_items', v_n_items,
    'gaps', v_gaps, 'overlaps', v_overlaps,
    'has_unified_lines', v_has_unified,
    'contract_item_start', v_ci.start_date, 'contract_item_end', v_ci.end_date);
END; $function$

CREATE OR REPLACE FUNCTION public.check_user_has_holding()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    user_record_id UUID;
    has_holding BOOLEAN := false;
BEGIN
    -- Obtener el ID del usuario en la tabla public.users usando auth.uid()
    SELECT id INTO user_record_id 
    FROM public.users 
    WHERE auth_id = auth.uid();

    -- Si no encontramos por auth_id, intentar por email
    IF user_record_id IS NULL THEN
        SELECT id INTO user_record_id 
        FROM public.users 
        WHERE email = (SELECT email FROM auth.users WHERE id = auth.uid());
    END IF;

    -- Verificar si tiene holding
    IF user_record_id IS NOT NULL THEN
        SELECT EXISTS(
            SELECT 1 FROM public.user_holdings 
            WHERE user_id = user_record_id
        ) INTO has_holding;
    END IF;

    RETURN has_holding;
END;
$function$

CREATE OR REPLACE FUNCTION public.classify_invoice_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    invoice_name TEXT;
    invoice_number TEXT;
    existing_invoice RECORD;
    has_changes BOOLEAN := FALSE;
BEGIN
    -- ✅ REGLA: SIEMPRE permitir la inserción

    -- Extraer identificadores únicos de la factura
    BEGIN
        invoice_name := (NEW.raw_data::JSONB) ->> 'name';
        invoice_number := (NEW.raw_data::JSONB) ->> 'invoice_number';

        -- Si no hay name, usar display_name como fallback
        IF invoice_name IS NULL OR invoice_name = '' THEN
            invoice_name := (NEW.raw_data::JSONB) ->> 'display_name';
        END IF;

    EXCEPTION WHEN OTHERS THEN
        invoice_name := NULL;
        invoice_number := NULL;
    END;

    -- Si no hay identificadores únicos, marcar como CREATE
    IF (invoice_name IS NULL OR invoice_name = '') AND (invoice_number IS NULL OR invoice_number = '') THEN
        NEW.processing_status := 'create';
        NEW.integration_notes := 'Factura sin identificadores únicos - marcada para creación';
        RETURN NEW;
    END IF;

    -- Búsqueda de factura existente por name o invoice_number
    BEGIN
        SELECT * INTO existing_invoice
        FROM invoices_legacy 
        WHERE holding_id = NEW.holding_id
            AND (
                invoice_number = COALESCE(invoice_number, invoice_name) OR
                invoice_number = invoice_name OR
                odoo_integration_id = (NEW.raw_data::JSONB ->> 'id')
            );

    EXCEPTION WHEN OTHERS THEN
        existing_invoice := NULL;
    END;

    -- Si no existe, marcar como CREATE
    IF existing_invoice IS NULL THEN
        NEW.processing_status := 'create';
        NEW.integration_notes := 'Factura nueva - marcada para creación';
        RETURN NEW;
    END IF;

    -- ✅ COMPARACIÓN DINÁMICA USANDO MAPEO
    BEGIN
        has_changes := detect_invoice_changes_with_dynamic_mapping(
            NEW.raw_data::JSONB,
            existing_invoice.id,
            NEW.holding_id
        );

    EXCEPTION WHEN OTHERS THEN
        has_changes := TRUE;
        NEW.integration_notes := 'Error en comparación dinámica: ' || SQLERRM;
    END;

    -- Determinar estado final
    IF has_changes THEN
        NEW.processing_status := 'update';
        IF NEW.integration_notes IS NULL THEN
            NEW.integration_notes := 'Factura existente con cambios - marcada para actualización';
        END IF;
    ELSE
        NEW.processing_status := 'processed';
        NEW.integration_notes := 'Factura idéntica a la existente - marcada como procesada';
    END IF;

    -- ✅ SIEMPRE retornar NEW (nunca rechazar)
    RETURN NEW;

EXCEPTION WHEN OTHERS THEN
    -- ✅ Incluso con errores, SIEMPRE insertar
    NEW.processing_status := 'error';
    NEW.integration_notes := 'Error general en trigger: ' || SQLERRM;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_duplicate_partners_by_vat(holding_id_param uuid, batch_size integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    deleted_count INTEGER := 0;
    current_batch INTEGER;
BEGIN
    -- Eliminar registros duplicados por VAT (mantener el más reciente)
    LOOP
        DELETE FROM odoo_partners_stg 
        WHERE id IN (
            SELECT s1.id 
            FROM odoo_partners_stg s1
            JOIN (
                SELECT raw_data ->> 'vat' as vat, MAX(created_at) as max_created
                FROM odoo_partners_stg 
                WHERE holding_id = holding_id_param
                    AND processing_status IN ('create', 'update')
                    AND raw_data ->> 'vat' IS NOT NULL
                GROUP BY raw_data ->> 'vat'
                HAVING COUNT(*) > 1
            ) s2 ON s1.raw_data ->> 'vat' = s2.vat
            WHERE s1.holding_id = holding_id_param
                AND s1.processing_status IN ('create', 'update')
                AND s1.created_at < s2.max_created
            LIMIT batch_size
        );

        GET DIAGNOSTICS current_batch = ROW_COUNT;
        deleted_count := deleted_count + current_batch;

        -- Salir si no hay más registros para eliminar
        EXIT WHEN current_batch = 0;

        -- Pequeña pausa para evitar saturar la base de datos
        PERFORM pg_sleep(0.1);
    END LOOP;

    RETURN deleted_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_duplicate_pending_records(batch_size integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    deleted_count INTEGER := 0;
    current_batch INTEGER;
BEGIN
    -- Eliminar registros pending duplicados (mantener el más reciente)
    LOOP
        DELETE FROM odoo_partners_stg 
        WHERE id IN (
            SELECT s1.id 
            FROM odoo_partners_stg s1
            JOIN (
                SELECT odoo_id, MAX(created_at) as max_created
                FROM odoo_partners_stg 
                WHERE processing_status = 'pending'
                GROUP BY odoo_id
                HAVING COUNT(*) > 1
            ) s2 ON s1.odoo_id = s2.odoo_id
            WHERE s1.processing_status = 'pending'
                AND s1.created_at < s2.max_created
            LIMIT batch_size
        );

        GET DIAGNOSTICS current_batch = ROW_COUNT;
        deleted_count := deleted_count + current_batch;

        -- Salir si no hay más registros para eliminar
        EXIT WHEN current_batch = 0;

        -- Pequeña pausa para evitar saturar la base de datos
        PERFORM pg_sleep(0.1);
    END LOOP;

    RETURN deleted_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_old_processed_records(days_old integer DEFAULT 30, batch_size integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    deleted_count INTEGER := 0;
    current_batch INTEGER;
BEGIN
    -- Eliminar registros procesados antiguos en lotes
    LOOP
        DELETE FROM odoo_partners_stg 
        WHERE id IN (
            SELECT id 
            FROM odoo_partners_stg
            WHERE processing_status = 'processed'
                AND last_integrated_at < NOW() - INTERVAL '1 day' * days_old
            LIMIT batch_size
        );

        GET DIAGNOSTICS current_batch = ROW_COUNT;
        deleted_count := deleted_count + current_batch;

        -- Salir si no hay más registros para eliminar
        EXIT WHEN current_batch = 0;

        -- Pequeña pausa para evitar saturar la base de datos
        PERFORM pg_sleep(0.1);
    END LOOP;

    RETURN deleted_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.close_period_until(p_holding_id uuid, p_company_id uuid, p_until_date date, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current_cutoff date;
  v_user_id uuid;
  v_user_name text;
  v_user_email text;
  v_event_id uuid;
  v_is_super boolean;
  v_is_admin boolean;
  v_user_holding uuid;
BEGIN
  v_is_super := public.is_super_admin();
  v_is_admin := public.is_holding_admin();
  IF NOT (v_is_super OR v_is_admin) THEN
    RAISE EXCEPTION 'Solo admins (holding o super) pueden cerrar períodos'
      USING ERRCODE = '42501';
  END IF;

  IF NOT v_is_super THEN
    v_user_holding := public.get_current_user_holding_id();
    IF v_user_holding IS DISTINCT FROM p_holding_id THEN
      RAISE EXCEPTION 'No autorizado para operar sobre el holding %', p_holding_id
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 10 THEN
    RAISE EXCEPTION 'El motivo es obligatorio y debe tener al menos 10 caracteres'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_until_date <> (date_trunc('month', p_until_date) + interval '1 month' - interval '1 day')::date THEN
    RAISE EXCEPTION 'p_until_date debe ser el último día de un mes (recibido: %)', p_until_date
      USING ERRCODE = 'P0001';
  END IF;

  SELECT cutoff_date INTO v_current_cutoff
    FROM public.accounting_period_cutoff
   WHERE holding_id = p_holding_id AND company_id = p_company_id;

  IF v_current_cutoff IS NOT NULL AND p_until_date < v_current_cutoff THEN
    RAISE EXCEPTION
      'No se puede cerrar a una fecha anterior al cutoff actual (cutoff=%, nueva=%). Para retroceder se debe usar reopen_period_from.',
      v_current_cutoff, p_until_date
      USING ERRCODE = 'P0001';
  END IF;

  v_user_id := public.get_current_user_id();   -- FIX: antes auth.uid()
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'No se pudo identificar al usuario en public.users'
      USING ERRCODE = '42501';
  END IF;
  SELECT name, email INTO v_user_name, v_user_email
    FROM public.users WHERE id = v_user_id;

  INSERT INTO public.accounting_period_cutoff (
    holding_id, company_id, cutoff_date,
    last_action, last_action_at, last_action_by,
    last_action_by_name, last_action_by_email, last_action_reason
  ) VALUES (
    p_holding_id, p_company_id, p_until_date,
    'CLOSED', now(), v_user_id,
    v_user_name, v_user_email, p_reason
  )
  ON CONFLICT (holding_id, company_id) DO UPDATE
    SET cutoff_date = EXCLUDED.cutoff_date,
        last_action = EXCLUDED.last_action,
        last_action_at = EXCLUDED.last_action_at,
        last_action_by = EXCLUDED.last_action_by,
        last_action_by_name = EXCLUDED.last_action_by_name,
        last_action_by_email = EXCLUDED.last_action_by_email,
        last_action_reason = EXCLUDED.last_action_reason;

  INSERT INTO public.accounting_period_events (
    holding_id, company_id, action,
    cutoff_date_before, cutoff_date_after,
    performed_by, performed_by_name, performed_by_email,
    reason
  ) VALUES (
    p_holding_id, p_company_id, 'CLOSED',
    v_current_cutoff, p_until_date,
    v_user_id, v_user_name, v_user_email,
    p_reason
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END $function$

CREATE OR REPLACE FUNCTION public.compute_new_contract_start(p_start date, p_cutoff date)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_day        int;
  v_next_month date;
  v_last_day   int;
BEGIN
  IF p_start IS NULL OR p_cutoff IS NULL THEN
    RETURN p_start;
  END IF;
  IF p_start > p_cutoff THEN
    RETURN p_start;
  END IF;
  v_day := EXTRACT(DAY FROM p_start)::int;
  v_next_month := date_trunc('month', p_cutoff + INTERVAL '1 month')::date;
  v_last_day := EXTRACT(DAY FROM (v_next_month + INTERVAL '1 month - 1 day'))::int;
  RETURN v_next_month + (LEAST(v_day, v_last_day) - 1);
END;
$function$

CREATE OR REPLACE FUNCTION public.convert_amount(p_holding_id uuid, p_amount numeric, p_from_currency text, p_to_currency text, p_reference_date date, p_policy text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rate numeric;
  v_source text;
  v_ref_date date;
  v_converted numeric;
BEGIN
  IF p_holding_id IS NULL OR p_holding_id <> public.get_current_user_holding_id() THEN
    RAISE EXCEPTION 'invalid holding_id';
  END IF;

  SELECT r.rate, r.source, r.reference_date
  INTO v_rate, v_source, v_ref_date
  FROM public.get_fx_rate(
    p_holding_id,
    p_from_currency,
    p_to_currency,
    p_reference_date,
    p_policy
  ) AS r;

  IF p_amount IS NULL THEN
    v_converted := NULL;
  ELSIF v_rate IS NULL THEN
    v_converted := NULL;
  ELSE
    v_converted := ROUND(p_amount * v_rate, 2);
  END IF;

  RETURN jsonb_build_object(
    'amount', p_amount,
    'from_currency', p_from_currency,
    'to_currency', p_to_currency,
    'reference_date', p_reference_date,
    'rate', v_rate,
    'fx_source', v_source,
    'fx_reference_date', v_ref_date,
    'converted_amount', v_converted
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_contract_churn(p_contract_id uuid, p_effective_date date, p_reason text DEFAULT NULL::text, p_risk_level text DEFAULT NULL::text, p_retention_action text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_holding_id uuid; v_items jsonb; v_reason_id uuid;
BEGIN
  v_holding_id := public.get_contract_holding(p_contract_id);
  IF v_holding_id IS NULL THEN RAISE EXCEPTION 'Contrato no encontrado o sin permisos'; END IF;

  SELECT jsonb_agg(jsonb_build_object('item_id', id)) INTO v_items
  FROM public.contract_items
  WHERE contract_id = p_contract_id AND COALESCE(is_recurring, false) = true
    AND churn_date IS NULL AND COALESCE(categoria, '') NOT IN ('CHURN', 'DOWNSELL');

  IF v_items IS NULL OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'El contrato no tiene items recurrentes activos para cancelar';
  END IF;

  IF p_reason IS NOT NULL AND p_reason <> '' THEN
    SELECT id INTO v_reason_id FROM public.churn_reasons
    WHERE holding_id = v_holding_id AND is_active AND lower(name) = lower(p_reason) LIMIT 1;
  END IF;

  RETURN public.apply_contract_contraction(
    p_contract_id, 'CHURN', v_items, p_effective_date, v_reason_id,
    COALESCE(NULLIF(p_notes, ''), NULLIF(p_retention_action, ''), NULLIF(p_risk_level, ''))
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_contract_cross_sell(p_contract_id uuid, p_items jsonb, p_effective_date date, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_approval_required boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_holding uuid;
  v_user uuid;
  v_item jsonb;
  v_result jsonb;
  v_total_delta numeric := 0;
  v_items_summary jsonb := '[]'::jsonb;
BEGIN
  SELECT public.get_contract_holding(p_contract_id) INTO v_holding;
  IF v_holding IS NULL THEN
    RAISE EXCEPTION 'Contrato no encontrado';
  END IF;

  SELECT public.get_current_user_id() INTO v_user;

  INSERT INTO public.contract_amendments(
    contract_id, holding_id, type, status, effective_date, reason, metadata, approval_required, requested_by
  ) VALUES (
    p_contract_id,
    v_holding,
    'CROSS_SELL',
    CASE WHEN p_approval_required THEN 'Pending' ELSE 'Approved' END,
    p_effective_date,
    p_reason,
    COALESCE(p_metadata, '{}'::jsonb),
    p_approval_required,
    v_user
  ) RETURNING id INTO v_id;

  IF p_items IS NOT NULL THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
      INSERT INTO public.contract_amendment_items(
        amendment_id, holding_id, original_item_id, price_delta, quantity_delta,
        start_date_override, end_date_override, scope, notes, item_metadata
      ) VALUES (
        v_id,
        v_holding,
        NULLIF(v_item->>'original_item_id', '')::uuid,
        (v_item->>'price_delta')::numeric,
        (v_item->>'quantity_delta')::numeric,
        NULLIF(v_item->>'start_date_override', '')::date,
        NULLIF(v_item->>'end_date_override', '')::date,
        NULLIF(v_item->>'scope', '')::amendment_scope_type,
        v_item->>'notes',
        COALESCE(v_item->'item_metadata', '{}'::jsonb)
      );

      -- Acumular delta para el resumen
      v_total_delta := v_total_delta + COALESCE((v_item->>'price_delta')::numeric, 0);
      v_items_summary := v_items_summary || jsonb_build_array(
        jsonb_build_object(
          'product_name', v_item->'item_metadata'->>'product_name',
          'price', v_item->'item_metadata'->>'price'
        )
      );
    END LOOP;
  END IF;

  IF NOT p_approval_required THEN
    v_result := public.approve_contract_amendment(v_id, true, 'Auto-aprobado');
    -- El evento ya se registra dentro de approve_contract_amendment
  END IF;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_contract_downsell(p_contract_id uuid, p_effective_date date, p_items jsonb, p_scope text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_approval_required boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_holding uuid;
  v_user uuid;
  v_item jsonb;
  v_result jsonb;
  v_scope_enum public.amendment_scope_type;
BEGIN
  RAISE NOTICE 'DEPRECATED (2026-05-27): create_contract_downsell será eliminada en sesión futura. Use apply_contract_contraction(p_type=''DOWNSELL'') directamente. Ver docs/contratos/contraccion-unificada.md.';

  v_scope_enum := p_scope::public.amendment_scope_type;

  SELECT public.get_contract_holding(p_contract_id) INTO v_holding;
  IF v_holding IS NULL THEN
    RAISE EXCEPTION 'Contrato no encontrado';
  END IF;

  SELECT public.get_current_user_id() INTO v_user;

  INSERT INTO public.contract_amendments(
    contract_id, holding_id, type, status, effective_date, reason, metadata, approval_required, requested_by
  ) VALUES (
    p_contract_id,
    v_holding,
    'DOWNSELL',
    CASE WHEN p_approval_required THEN 'Pending' ELSE 'Approved' END,
    p_effective_date,
    p_reason,
    COALESCE(p_metadata, '{}'::jsonb),
    p_approval_required,
    v_user
  ) RETURNING id INTO v_id;

  IF p_items IS NOT NULL THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
      INSERT INTO public.contract_amendment_items(
        amendment_id, holding_id, original_item_id, price_delta, quantity_delta,
        start_date_override, end_date_override, scope, notes, item_metadata
      ) VALUES (
        v_id,
        v_holding,
        (v_item->>'original_item_id')::uuid,
        (v_item->>'price_delta')::numeric,
        (v_item->>'quantity_delta')::numeric,
        (v_item->>'start_date_override')::date,
        (v_item->>'end_date_override')::date,
        COALESCE(
          NULLIF(v_item->>'scope', '')::public.amendment_scope_type,
          v_scope_enum
        ),
        v_item->>'notes',
        COALESCE(v_item->'item_metadata', '{}'::jsonb)
      );
    END LOOP;
  END IF;

  IF NOT p_approval_required THEN
    SELECT public.approve_contract_amendment(v_id, true, NULL) INTO v_result;
  END IF;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_contract_from_mrr_legacy(p_group_data jsonb, p_form_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contract_id uuid;
  v_holding_id uuid;
  v_client_name_commercial text;
  v_legal_client_name text;
  v_total_value numeric := 0;
  v_contract_end_date date;
  v_max_end_date date;
  v_product jsonb;
  v_product_end_date date;
  v_contract_item_id uuid;
  v_contract_items uuid[] := ARRAY[]::uuid[];
  v_invoice_date date;
  v_invoice_amount numeric;
  v_item_details jsonb;
  v_max_term integer;
  v_is_anticipada boolean;
  v_monthly_price numeric;
  v_billing_period_price numeric;
  v_price_before_discount numeric;
  v_discount_pct numeric;
  v_custom_fields jsonb;
  v_start_date date;
  v_i integer;
  v_j integer;
  v_record_ids uuid[];
  v_fx_result RECORD;
BEGIN
  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] ========== INICIO ==========';
  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] Group: %, Form: %', p_group_data->>'client_id', p_form_data->>'company_id';

  -- =====================================================
  -- PASO 1: Obtener holding_id del usuario actual
  -- =====================================================

  SELECT get_current_user_holding_id() INTO v_holding_id;

  IF v_holding_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no tiene empresa asociada';
  END IF;

  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] Holding ID: %', v_holding_id;

  -- =====================================================
  -- PASO 2: Obtener client_name_commercial y legal_client_name
  -- =====================================================

  SELECT name_commercial INTO v_client_name_commercial
  FROM clients
  WHERE id = (p_group_data->>'client_id')::uuid;

  -- Obtener legal_client_name desde client_entities si existe client_entity_id
  IF (p_form_data->>'client_entity_id') IS NOT NULL THEN
    SELECT legal_name INTO v_legal_client_name
    FROM client_entities
    WHERE id = (p_form_data->>'client_entity_id')::uuid;
  END IF;

  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] Client: %, Legal Name: %', v_client_name_commercial, v_legal_client_name;

  -- =====================================================
  -- PASO 3: Calcular total_value y contract_end_date
  -- =====================================================

  v_start_date := (p_form_data->>'start_date')::date;
  v_max_end_date := v_start_date;

  FOR v_product IN SELECT * FROM jsonb_array_elements(p_form_data->'products')
  LOOP
    -- Sumar al total_value
    v_total_value := v_total_value + (v_product->>'final_price')::numeric;

    -- Calcular end_date del producto
    IF v_product->>'end_date' IS NOT NULL AND v_product->>'end_date' != '' THEN
      v_product_end_date := (v_product->>'end_date')::date;
    ELSIF v_product->>'term_months' IS NOT NULL THEN
      v_product_end_date := (v_start_date + ((v_product->>'term_months')::integer || ' months')::interval - interval '1 day')::date;
    ELSE
      -- Si no hay term_months, usar 12 meses por defecto
      v_product_end_date := (v_start_date + interval '12 months' - interval '1 day')::date;
    END IF;

    -- Actualizar máximo
    IF v_product_end_date > v_max_end_date THEN
      v_max_end_date := v_product_end_date;
    END IF;
  END LOOP;

  -- Asegurar que contract_end_date siempre tenga un valor
  v_contract_end_date := COALESCE(v_max_end_date, v_start_date + interval '12 months' - interval '1 day');

  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] Total Value: %, End Date: %', v_total_value, v_contract_end_date;

  -- =====================================================
  -- PASO 4: Crear contrato (ahora incluye auto_invoice)
  -- =====================================================

  INSERT INTO contracts (
    client_id,
    company_id,
    status,
    booking_date,
    holding_id,
    contract_number,
    contract_currency,
    requires_references_for_billing,
    auto_invoice,
    type,
    notes,
    fx_company_policy,
    client_entity_id,
    total_value,
    client_name_commercial,
    legal_client_name,
    contract_end_date
  ) VALUES (
    (p_group_data->>'client_id')::uuid,
    (p_form_data->>'company_id')::uuid,
    'En revisión',
    v_start_date,
    v_holding_id,
    p_form_data->>'contract_number',
    p_group_data->>'contract_currency',
    COALESCE((p_form_data->>'requires_references')::boolean, false),
    COALESCE((p_form_data->>'auto_invoice')::boolean, false),
    p_form_data->>'contract_type',
    p_form_data->>'notes',
    p_form_data->>'fx_company_policy',
    (p_form_data->>'client_entity_id')::uuid,
    v_total_value,
    v_client_name_commercial,
    v_legal_client_name,
    v_contract_end_date
  )
  RETURNING id INTO v_contract_id;

  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] Contract created: %', v_contract_id;

  -- =====================================================
  -- PASO 5: Crear contract_items
  -- =====================================================

  FOR v_product IN SELECT * FROM jsonb_array_elements(p_form_data->'products')
  LOOP
    -- Calcular monthly_price
    v_monthly_price := (v_product->>'final_price')::numeric / (v_product->>'term_months')::integer;

    -- Calcular billing_period_price según frecuencia
    v_billing_period_price := v_monthly_price;
    CASE LOWER(v_product->>'billing_frequency')
      WHEN 'trimestral' THEN v_billing_period_price := v_monthly_price * 3;
      WHEN 'semestral' THEN v_billing_period_price := v_monthly_price * 6;
      WHEN 'anual' THEN v_billing_period_price := v_monthly_price * 12;
      WHEN 'bianual' THEN v_billing_period_price := v_monthly_price * 24;
      ELSE v_billing_period_price := v_monthly_price;
    END CASE;

    -- Calcular precio antes de descuento
    v_discount_pct := COALESCE((v_product->>'discount_pct')::numeric, 0);
    IF v_discount_pct > 0 THEN
      v_price_before_discount := (v_product->>'final_price')::numeric / (1 - v_discount_pct / 100);
    ELSE
      v_price_before_discount := (v_product->>'final_price')::numeric;
    END IF;

    -- Extraer custom_fields (campos que empiezan con cf_)
    v_custom_fields := '{}'::jsonb;
    -- Nota: En SQL no podemos iterar dinámicamente sobre keys de jsonb como en JS
    -- Los custom_fields deben venir ya procesados desde el frontend en el jsonb
    IF v_product ? 'custom_fields' THEN
      v_custom_fields := v_product->'custom_fields';
    END IF;

    -- Calcular end_date (consistente con cálculo del contrato)
    IF v_product->>'end_date' IS NOT NULL AND v_product->>'end_date' != '' THEN
      v_product_end_date := (v_product->>'end_date')::date;
    ELSIF v_product->>'term_months' IS NOT NULL THEN
      v_product_end_date := (v_start_date + ((v_product->>'term_months')::integer || ' months')::interval - interval '1 day')::date;
    ELSE
      -- Si no hay term_months, usar 12 meses por defecto
      v_product_end_date := (v_start_date + interval '12 months' - interval '1 day')::date;
    END IF;

    -- Insertar contract_item
    INSERT INTO contract_items (
      contract_id,
      product_id,
      product_name,
      price,
      final_price,
      monthly_price,
      billing_period_price,
      currency,
      billing_frequency,
      billing_method,
      term_months,
      start_date,
      end_date,
      categoria,
      item_type,
      unit_of_measure,
      unit_price,
      quantity,
      discount_type,
      discount_value,
      is_recurring,
      auto_renew,
      auto_renew_term_months,
      holding_id,
      custom_fields
    ) VALUES (
      v_contract_id,
      (v_product->>'product_id')::uuid,
      v_product->>'product_name',
      v_price_before_discount,
      (v_product->>'final_price')::numeric,
      v_monthly_price,
      v_billing_period_price,
      v_product->>'currency',
      v_product->>'billing_frequency',
      CASE WHEN v_product->>'billing_type' = 'anticipada' THEN 'Anticipado' ELSE 'Vencido' END,
      (v_product->>'term_months')::integer,
      v_start_date,
      v_product_end_date,
      'RENEWAL',
      v_product->>'item_type',
      v_product->>'unit_of_measure',
      (v_product->>'unit_price')::numeric,
      (v_product->>'quantity')::numeric,
      CASE WHEN v_discount_pct > 0 THEN 'Porcentaje' ELSE NULL END,
      CASE WHEN v_discount_pct > 0 THEN v_discount_pct ELSE NULL END,
      true,
      COALESCE((v_product->>'auto_renew')::boolean, false),
      (v_product->>'auto_renew_term_months')::integer,
      v_holding_id,
      CASE WHEN jsonb_typeof(v_custom_fields) = 'object' AND v_custom_fields != '{}'::jsonb THEN v_custom_fields ELSE NULL END
    )
    RETURNING id INTO v_contract_item_id;

    v_contract_items := array_append(v_contract_items, v_contract_item_id);
  END LOOP;

  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] Contract items created: %', array_length(v_contract_items, 1);

  -- =====================================================
  -- PASO 6: Crear contract_invoices (schedule programado)
  -- =====================================================

  -- Obtener max term y tipo de facturación
  SELECT MAX((value->>'term_months')::integer) INTO v_max_term
  FROM jsonb_array_elements(p_form_data->'products');

  SELECT value->>'billing_type' = 'anticipada' INTO v_is_anticipada
  FROM jsonb_array_elements(p_form_data->'products')
  LIMIT 1;

  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] Generating contract_invoices: max_term=%, anticipada=%', v_max_term, v_is_anticipada;

  -- Loop para cada período
  FOR v_i IN 0..(v_max_term - 1)
  LOOP
    -- Calcular fecha de factura
    IF v_is_anticipada THEN
      v_invoice_date := v_start_date + (v_i || ' months')::interval;
    ELSE
      v_invoice_date := v_start_date + ((v_i + 1) || ' months')::interval;
    END IF;

    -- Calcular monto y detalles de items para esta factura
    v_invoice_amount := 0;
    v_item_details := '[]'::jsonb;

    v_j := 0;
    FOR v_product IN SELECT * FROM jsonb_array_elements(p_form_data->'products')
    LOOP
      -- Solo incluir si el producto está activo en este período
      IF v_i < (v_product->>'term_months')::integer THEN
        v_monthly_price := (v_product->>'final_price')::numeric / (v_product->>'term_months')::integer;
        v_invoice_amount := v_invoice_amount + v_monthly_price;

        -- Agregar detalle del item
        v_item_details := v_item_details || jsonb_build_object(
          'contract_item_id', v_contract_items[v_j + 1],
          'product_name', v_product->>'product_name',
          'amount', v_monthly_price,
          'quantity', COALESCE((v_product->>'quantity')::numeric, 1),
          'unit_of_measure', v_product->>'unit_of_measure'
        );
      END IF;

      v_j := v_j + 1;
    END LOOP;

    -- Insertar contract_invoice si hay monto
    IF v_invoice_amount > 0 THEN
      INSERT INTO contract_invoices (
        contract_id,
        invoice_date,
        amount,
        currency,
        status,
        contract_item_details,
        holding_id
      ) VALUES (
        v_contract_id,
        v_invoice_date,
        v_invoice_amount,
        p_group_data->>'contract_currency',
        'Programada',
        v_item_details,
        v_holding_id
      );
    END IF;
  END LOOP;

  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] Contract invoices created';

  -- =====================================================
  -- PASO 7: Actualizar mrr_legacy records
  -- =====================================================

  -- Extraer record_ids del group_data
  SELECT ARRAY(SELECT jsonb_array_elements_text(p_group_data->'record_ids'))::uuid[]
  INTO v_record_ids;

  UPDATE mrr_legacy
  SET 
    migrated_to_contract_id = v_contract_id,
    migrated_at = NOW()
  WHERE id = ANY(v_record_ids);

  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] MRR legacy records updated: %', array_length(v_record_ids, 1);

  -- =====================================================
  -- PASO 7.5: Calcular FX rates para el contrato
  -- =====================================================

  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] Calculating FX rates for contract...';

  BEGIN
    -- Llamar a calculate_contract_fx_amounts para calcular FX
    SELECT * INTO v_fx_result 
    FROM calculate_contract_fx_amounts(v_contract_id);

    IF v_fx_result.success THEN
      RAISE NOTICE '[MRR_LEGACY_ACTIVATION] ✅ FX rates calculated successfully';
    ELSE
      RAISE WARNING '[MRR_LEGACY_ACTIVATION] ⚠️ FX calculation warning: %', v_fx_result.message;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- No fallar la transacción completa si falla el cálculo FX
    -- El contrato se crea igual y el FX se puede calcular después
    RAISE WARNING '[MRR_LEGACY_ACTIVATION] ⚠️ Error calculating FX (non-fatal): %', SQLERRM;
  END;

  -- =====================================================
  -- PASO 8: Retornar resultado
  -- =====================================================

  RAISE NOTICE '[MRR_LEGACY_ACTIVATION] ========== ÉXITO ==========';

  RETURN jsonb_build_object(
    'success', true,
    'contract_id', v_contract_id,
    'contract_items_count', array_length(v_contract_items, 1),
    'message', 'Contrato creado exitosamente en estado En revisión'
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE NOTICE '[MRR_LEGACY_ACTIVATION] ========== ERROR ==========';
    RAISE NOTICE '[MRR_LEGACY_ACTIVATION] Error: %', SQLERRM;

    -- Retornar error
    RETURN jsonb_build_object(
      'success', false,
      'error', SQLERRM,
      'message', 'Error al crear contrato desde MRR Legacy'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_contract_renewal(p_contract_id uuid, p_effective_date date, p_items jsonb DEFAULT '[]'::jsonb, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_approval_required boolean DEFAULT true)
 RETURNS TABLE(success boolean, amendment_id uuid, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_holding_id uuid;
  v_contract_record RECORD;
  v_amendment_id uuid;
  v_item jsonb;
  v_new_item_id uuid;
  v_original_check RECORD;
BEGIN
  SELECT id INTO v_user_id
  FROM public.users
  WHERE auth_id = auth.uid();

  IF v_user_id IS NULL THEN
    RETURN QUERY SELECT false, NULL::uuid, 'Usuario no encontrado';
    RETURN;
  END IF;

  SELECT holding_id INTO v_holding_id
  FROM public.user_holdings
  WHERE user_id = v_user_id;

  IF v_holding_id IS NULL THEN
    RETURN QUERY SELECT false, NULL::uuid, 'Usuario sin holding asociado';
    RETURN;
  END IF;

  SELECT c.*
  INTO v_contract_record
  FROM public.contracts c
  WHERE c.id = p_contract_id
    AND c.holding_id = v_holding_id;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::uuid, 'Contrato no encontrado o sin permisos';
    RETURN;
  END IF;

  IF jsonb_array_length(p_items) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      IF (v_item->>'original_item_id') IS NOT NULL AND (v_item->>'original_item_id') <> '' THEN
        SELECT id, churn_date, renewed_by_item_id, categoria
        INTO v_original_check
        FROM public.contract_items
        WHERE id = (v_item->>'original_item_id')::uuid
          AND contract_id = p_contract_id;

        IF FOUND THEN
          IF v_original_check.churn_date IS NOT NULL THEN
            RAISE EXCEPTION 'No se puede renovar el item %: ya tiene churn_date=%',
              v_original_check.id, v_original_check.churn_date
              USING ERRCODE = 'P0001';
          END IF;
          IF v_original_check.renewed_by_item_id IS NOT NULL THEN
            RAISE EXCEPTION 'No se puede renovar el item %: ya fue renovado por item %',
              v_original_check.id, v_original_check.renewed_by_item_id
              USING ERRCODE = 'P0001';
          END IF;
          IF v_original_check.categoria IN ('CHURN', 'DOWNSELL') THEN
            RAISE EXCEPTION 'No se puede renovar el item %: es de tipo % y no es renovable',
              v_original_check.id, v_original_check.categoria
              USING ERRCODE = 'P0001';
          END IF;
        END IF;
      END IF;
    END LOOP;
  END IF;

  INSERT INTO public.contract_amendments (
    contract_id, type, effective_date, reason, metadata,
    approval_required, requested_by, status
  ) VALUES (
    p_contract_id,
    'renewal'::contract_amendment_type,
    p_effective_date,
    COALESCE(p_reason, 'Renovación de contrato'),
    p_metadata,
    p_approval_required,
    v_user_id,
    CASE WHEN p_approval_required THEN 'Pending' ELSE 'Approved' END
  ) RETURNING id INTO v_amendment_id;

  IF jsonb_array_length(p_items) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      INSERT INTO public.contract_items (
        contract_id, product_name, price, final_price, currency,
        billing_frequency, billing_method, start_date, end_date,
        term_months, is_recurring, renews_item_id, product_id, holding_id
      ) VALUES (
        p_contract_id,
        v_item->>'product_name',
        COALESCE((v_item->>'price')::numeric, 0),
        COALESCE((v_item->>'final_price')::numeric, (v_item->>'price')::numeric, 0),
        COALESCE(v_item->>'currency', 'USD'),
        COALESCE(v_item->>'billing_frequency', 'monthly'),
        COALESCE(v_item->>'billing_method', 'advance'),
        p_effective_date,
        CASE
          WHEN (v_item->>'term_months')::integer > 0
          THEN p_effective_date + ((v_item->>'term_months')::integer || ' months')::interval
          ELSE NULL
        END,
        COALESCE((v_item->>'term_months')::integer, 12),
        COALESCE((v_item->>'is_recurring')::boolean, true),
        COALESCE((v_item->>'original_item_id')::uuid, NULL),
        NULLIF(v_item->>'product_id', '')::uuid,
        v_holding_id
      ) RETURNING id INTO v_new_item_id;

      INSERT INTO public.contract_amendment_items (
        amendment_id, new_item_id, original_item_id, scope, item_metadata
      ) VALUES (
        v_amendment_id,
        v_new_item_id,
        (v_item->>'original_item_id')::uuid,
        'permanent'::amendment_scope_type,
        v_item
      );
    END LOOP;
  END IF;

  INSERT INTO public.contract_lifecycle_events (
    contract_id, event_type, event_subtype, title, description,
    effective_date, amount_delta, event_status, created_by, metadata
  ) VALUES (
    p_contract_id,
    'renewal', 'standard_renewal',
    'Renovación de Contrato',
    COALESCE(p_reason, 'Renovación automática de contrato'),
    p_effective_date,
    0,
    CASE WHEN p_approval_required THEN 'pending' ELSE 'approved' END,
    v_user_id,
    jsonb_build_object(
      'amendment_id', v_amendment_id,
      'items_count', jsonb_array_length(p_items),
      'approval_required', p_approval_required
    )
  );

  RETURN QUERY SELECT true, v_amendment_id, 'Renovación creada exitosamente';

EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT false, NULL::uuid, 'Error al crear renovación: ' || SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_contract_renewal(p_contract_id uuid, p_effective_date date, p_term_months integer DEFAULT NULL::integer, p_new_end_date date DEFAULT NULL::date, p_copy_items boolean DEFAULT true, p_metadata jsonb DEFAULT '{}'::jsonb, p_approval_required boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_holding_id uuid;
  v_contract_record RECORD;
  v_company_tax_rate numeric;
  v_original_item_id uuid;
  v_original_item RECORD;
  v_new_item_id uuid;
  v_new_start_date date := p_effective_date;
  v_new_end_date date;
  v_lifecycle_event_id uuid;
  v_amendment_id uuid;
  v_created_items jsonb := '[]'::jsonb;
  v_created_invoices jsonb := '[]'::jsonb;
  v_invoice_count integer := 0;
  v_used_term integer;
  v_freq_raw text;
  v_freq text;
  v_period_months int := 1;
  v_method_raw text;
  v_method text;
  v_monthly_base numeric := 0;
  v_period_amount numeric := 0;
  v_period_start date;
  v_period_end date;
  v_issue_date date;
  v_due_date date;
  v_subtotal numeric;
  v_tax_amount numeric;
  v_total numeric;
  v_new_invoice_id uuid;
  v_custom_schedule jsonb;
  v_entry jsonb;
  v_sched_date date;
  v_sched_amount numeric;
  v_bp_end date;
  v_renewal_final_price numeric;
  v_renewal_unit_price numeric;
  v_renewal_quantity numeric;
  v_renewal_price numeric;
  v_item_qty numeric;
  v_item_unit_price numeric;
  v_has_price_change boolean;
  v_original_monthly numeric;
  v_renewal_monthly numeric;
  v_child RECORD;
  v_child_monthly numeric;
  v_children_monthly_sum numeric := 0;
  v_children_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  SELECT id INTO v_user_id FROM public.users WHERE auth_id = auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no encontrado';
  END IF;
  SELECT holding_id INTO v_holding_id FROM public.user_holdings WHERE user_id = v_user_id;
  IF v_holding_id IS NULL THEN
    RAISE EXCEPTION 'Usuario sin holding asociado';
  END IF;
  SELECT c.*, comp.tax_rate INTO v_contract_record
  FROM public.contracts c
  JOIN public.companies comp ON c.company_id = comp.id
  WHERE c.id = p_contract_id AND c.holding_id = v_holding_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contrato no encontrado o sin permisos';
  END IF;
  v_company_tax_rate := v_contract_record.tax_rate;
  IF v_company_tax_rate IS NULL THEN
    RAISE EXCEPTION 'TAX_RATE_NOT_CONFIGURED: La empresa % no tiene configurada una tasa de impuesto (tax_rate). Configure el impuesto en la empresa antes de generar facturas.', v_contract_record.company_id
      USING ERRCODE = 'P0001';
  END IF;
  v_original_item_id := COALESCE((p_metadata->>'original_item_id')::uuid, NULL);
  IF v_original_item_id IS NULL THEN
    RAISE EXCEPTION 'original_item_id requerido en metadata';
  END IF;
  SELECT * INTO v_original_item
  FROM public.contract_items
  WHERE id = v_original_item_id AND contract_id = p_contract_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item original no encontrado';
  END IF;

  IF v_original_item.churn_date IS NOT NULL THEN
    RAISE EXCEPTION 'No se puede renovar el item %: ya tiene churn_date=%',
      v_original_item.id, v_original_item.churn_date
      USING ERRCODE = 'P0001';
  END IF;
  IF v_original_item.renewed_by_item_id IS NOT NULL THEN
    RAISE EXCEPTION 'No se puede renovar el item %: ya fue renovado por item %',
      v_original_item.id, v_original_item.renewed_by_item_id
      USING ERRCODE = 'P0001';
  END IF;
  IF v_original_item.categoria IN ('CHURN', 'DOWNSELL') THEN
    RAISE EXCEPTION 'No se puede renovar el item %: es de tipo % y no es renovable',
      v_original_item.id, v_original_item.categoria
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.contract_amendments (
    contract_id, type, effective_date, approval_required, metadata, reason, status, requested_by, holding_id
  ) VALUES (
    p_contract_id,
    'RENEWAL'::public.contract_amendment_type,
    p_effective_date,
    p_approval_required,
    COALESCE(p_metadata, '{}'::jsonb),
    'Contract renewal',
    CASE WHEN p_approval_required THEN 'Pending' ELSE 'Approved' END,
    v_user_id,
    v_holding_id
  ) RETURNING id INTO v_amendment_id;

  IF p_approval_required THEN
    INSERT INTO public.contract_lifecycle_events (
      contract_id, event_type, event_status, title, description, effective_date, created_by, holding_id, metadata
    ) VALUES (
      p_contract_id, 'renewal', 'pending', 'Solicitud de Renovación',
      'Renovación de contrato pendiente de aprobación', p_effective_date,
      v_user_id, v_holding_id,
      jsonb_build_object(
        'amendment_id', v_amendment_id, 'original_item_id', v_original_item_id,
        'term_months', p_term_months, 'new_end_date', p_new_end_date, 'approval_required', true
      )
    ) RETURNING id INTO v_lifecycle_event_id;
    RETURN jsonb_build_object(
      'success', true, 'approval_required', true, 'amendment_id', v_amendment_id,
      'lifecycle_event_id', v_lifecycle_event_id,
      'message', 'Solicitud de renovación creada pendiente de aprobación'
    );
  END IF;

  v_used_term := COALESCE(p_term_months, v_original_item.term_months, 1);
  IF p_new_end_date IS NOT NULL THEN
    v_new_end_date := p_new_end_date;
  ELSE
    v_new_end_date := (v_new_start_date + (v_used_term || ' month')::interval - interval '1 day')::date;
  END IF;

  v_freq_raw := lower(COALESCE(p_metadata->>'billing_frequency', v_original_item.billing_frequency, 'Mensual'));
  IF v_freq_raw LIKE '%mensual%' OR v_freq_raw LIKE '%month%' THEN
    v_period_months := 1; v_freq := 'Mensual';
  ELSIF v_freq_raw LIKE '%trimes%' OR v_freq_raw LIKE '%quarter%' THEN
    v_period_months := 3; v_freq := 'Trimestral';
  ELSIF v_freq_raw LIKE '%semes%' OR v_freq_raw LIKE '%semi%' THEN
    v_period_months := 6; v_freq := 'Semestral';
  ELSIF v_freq_raw LIKE '%anual%' OR v_freq_raw LIKE '%annual%' OR v_freq_raw LIKE '%year%' THEN
    v_period_months := 12; v_freq := 'Anual';
  ELSE
    v_period_months := 1; v_freq := 'Mensual';
  END IF;

  v_method_raw := lower(COALESCE(p_metadata->>'billing_method', v_original_item.billing_method, 'Anticipado'));
  IF v_method_raw LIKE '%vencid%' OR v_method_raw LIKE '%arrear%' OR v_method_raw LIKE '%post%' THEN
    v_method := 'Vencido';
  ELSE
    v_method := 'Anticipado';
  END IF;

  v_renewal_final_price := COALESCE((p_metadata->>'final_price_override')::numeric, v_original_item.final_price);
  v_renewal_unit_price := COALESCE((p_metadata->>'unit_price_override')::numeric, v_original_item.unit_price);
  v_renewal_quantity := COALESCE((p_metadata->>'quantity_override')::numeric, v_original_item.quantity);
  v_renewal_price := COALESCE((p_metadata->>'price_override')::numeric, v_original_item.price);

  v_original_monthly := COALESCE(
    v_original_item.monthly_price,
    CASE WHEN COALESCE(v_original_item.term_months, 0) > 0
         THEN ROUND(v_original_item.final_price / v_original_item.term_months, 2)
         ELSE 0 END
  );
  v_renewal_monthly := CASE WHEN COALESCE(v_used_term, 0) > 0
                            THEN ROUND(v_renewal_final_price / v_used_term, 2)
                            ELSE 0 END;
  v_has_price_change := (
    v_original_monthly IS NOT NULL
    AND v_renewal_monthly IS NOT NULL
    AND ABS(v_renewal_monthly - v_original_monthly) >= 0.01
  );

  FOR v_child IN
    SELECT id, monthly_price, final_price, term_months
    FROM public.contract_items
    WHERE contract_id = p_contract_id
      AND related_item_id = v_original_item.id
      AND COALESCE(categoria, '') = 'UPSELL'
      AND churn_date IS NULL
      AND renewed_by_item_id IS NULL
  LOOP
    v_child_monthly := COALESCE(
      v_child.monthly_price,
      CASE WHEN COALESCE(v_child.term_months, 0) > 0
           THEN ROUND(v_child.final_price / v_child.term_months, 2)
           ELSE 0 END
    );
    v_children_monthly_sum := v_children_monthly_sum + v_child_monthly;
    v_children_ids := array_append(v_children_ids, v_child.id);
  END LOOP;

  IF array_length(v_children_ids, 1) > 0 THEN
    v_renewal_final_price := v_renewal_final_price + ROUND(v_children_monthly_sum * v_used_term, 2);
  END IF;

  INSERT INTO public.contract_items (
    contract_id, product_id, product_name, term_months, currency, price, discount_type, discount_value,
    final_price, billing_method, billing_frequency, start_date, end_date, is_recurring, renews_item_id, holding_id,
    unit_price, quantity,
    categoria, item_type, unit_of_measure,
    annual_unit_price, annual_price, price_entry_mode
  ) VALUES (
    p_contract_id, v_original_item.product_id, v_original_item.product_name, v_used_term,
    v_original_item.currency, v_renewal_price, v_original_item.discount_type, v_original_item.discount_value,
    v_renewal_final_price, v_method, v_freq, v_new_start_date, v_new_end_date,
    v_original_item.is_recurring, v_original_item.id, v_holding_id,
    v_renewal_unit_price, v_renewal_quantity,
    'RENEWAL', v_original_item.item_type, v_original_item.unit_of_measure,
    v_original_item.annual_unit_price, v_original_item.annual_price, v_original_item.price_entry_mode
  ) RETURNING id INTO v_new_item_id;

  UPDATE public.contract_items SET renewed_by_item_id = v_new_item_id WHERE id = v_original_item.id;

  IF array_length(v_children_ids, 1) > 0 THEN
    UPDATE public.contract_items
    SET renewed_by_item_id = v_new_item_id
    WHERE id = ANY(v_children_ids);
  END IF;

  IF v_has_price_change THEN
    IF COALESCE(v_original_item.price_entry_mode, 'monthly') = 'annual' THEN
      UPDATE public.contract_items
      SET annual_unit_price       = ROUND(v_renewal_unit_price * 12, 6),
          annual_price            = ROUND(v_renewal_unit_price * 12 * COALESCE(v_renewal_quantity, 1), 2),
          renewal_base_unit_price = v_original_item.unit_price
      WHERE id = v_new_item_id;
    ELSE
      UPDATE public.contract_items
      SET renewal_base_unit_price = v_original_item.unit_price
      WHERE id = v_new_item_id;
    END IF;
  END IF;

  v_created_items := v_created_items || jsonb_build_object(
    'id', v_new_item_id, 'product_name', v_original_item.product_name,
    'final_price', v_renewal_final_price, 'start_date', v_new_start_date, 'end_date', v_new_end_date,
    'price_changed', v_has_price_change,
    'renewal_base_unit_price', CASE WHEN v_has_price_change THEN v_original_item.unit_price ELSE NULL END,
    'consolidated_children_count', COALESCE(array_length(v_children_ids, 1), 0),
    'consolidated_children_monthly_sum', v_children_monthly_sum,
    'consolidated_children_ids', to_jsonb(v_children_ids)
  );

  v_monthly_base := COALESCE(v_renewal_final_price, v_renewal_price, 0) / NULLIF(v_used_term, 0);
  IF v_monthly_base IS NULL THEN v_monthly_base := 0; END IF;

  v_custom_schedule := p_metadata->'custom_schedule';
  IF v_custom_schedule IS NOT NULL AND jsonb_typeof(v_custom_schedule) = 'array' AND jsonb_array_length(v_custom_schedule) > 0 THEN
    FOR v_entry IN SELECT * FROM jsonb_array_elements(v_custom_schedule)
    LOOP
      v_sched_date := (v_entry->>'date')::date;
      v_sched_amount := COALESCE((v_entry->>'amount')::numeric, 0);
      IF v_sched_date IS NULL THEN CONTINUE; END IF;

      v_subtotal := v_sched_amount;
      v_tax_amount := ROUND(v_subtotal * (v_company_tax_rate / 100), 2);
      v_total := v_subtotal + v_tax_amount;
      v_issue_date := v_sched_date;
      v_due_date := v_issue_date + interval '30 days';
      v_bp_end := (v_sched_date + (v_period_months || ' month')::interval - interval '1 day')::date;

      INSERT INTO public.invoices (
        company_id, client_id, client_entity_id, contract_id,
        scheduled_at, original_issue_date, issue_date, due_date,
        vat, amount_contract_currency, amount_invoice_currency,
        total_invoice_currency, total_system_currency,
        contract_currency, invoice_currency, fx_contract_to_invoice,
        status, invoice_type, document_type, export_type, invoice_series,
        holding_id, issuer_legal_name, issuer_tax_id, issuer_address, client_tax_id,
        notes
      ) VALUES (
        v_contract_record.company_id, v_contract_record.client_id,
        v_contract_record.client_entity_id, p_contract_id,
        v_sched_date, v_sched_date, v_issue_date, v_due_date,
        v_tax_amount, v_subtotal, v_subtotal, v_total, v_total,
        v_original_item.currency, v_original_item.currency, 1.0,
        'Por Emitir',
        'Automatica',
        'FACTURA', 1, 'FAC',
        v_holding_id,
        (SELECT legal_name FROM companies WHERE id = v_contract_record.company_id),
        (SELECT tax_id FROM companies WHERE id = v_contract_record.company_id),
        (SELECT legal_address FROM companies WHERE id = v_contract_record.company_id),
        (SELECT ce.tax_id FROM client_entities ce WHERE ce.id = v_contract_record.client_entity_id),
        'Renovación de contrato'
      ) RETURNING id INTO v_new_invoice_id;

      v_item_qty := COALESCE(v_renewal_quantity, 1);
      v_item_unit_price := ROUND(v_subtotal / v_item_qty, 6);

      INSERT INTO public.invoice_items (
        invoice_id, contract_item_id, product_id,
        description, quantity, unit_of_measure,
        unit_price_contract_currency, unit_price_invoice_currency,
        discount_pct,
        subtotal_contract_currency, subtotal_invoice_currency,
        tax_amount_contract_currency, tax_amount_invoice_currency,
        total_contract_currency, total_invoice_currency,
        contract_currency, invoice_currency, fx_contract_to_invoice,
        holding_id, contract_id,
        billing_period_start, billing_period_end
      ) VALUES (
        v_new_invoice_id, v_new_item_id, v_original_item.product_id,
        v_original_item.product_name || CASE WHEN NULLIF(TRIM(v_original_item.account), '') IS NOT NULL THEN ' Cuenta ' || TRIM(v_original_item.account) ELSE '' END || ' - Periodo '
          || TO_CHAR(v_sched_date, 'DD/MM/YYYY') || ' a '
          || TO_CHAR(v_bp_end, 'DD/MM/YYYY'),
        v_item_qty, COALESCE(v_original_item.unit_of_measure, 'UND'),
        v_item_unit_price, v_item_unit_price,
        0,
        v_subtotal, v_subtotal,
        v_tax_amount, v_tax_amount,
        v_total, v_total,
        v_original_item.currency, v_original_item.currency, 1,
        v_holding_id, p_contract_id,
        v_sched_date, v_bp_end
      );

      v_invoice_count := v_invoice_count + 1;
      v_created_invoices := v_created_invoices || jsonb_build_object(
        'id', v_new_invoice_id, 'scheduled_at', v_sched_date, 'amount', v_total
      );
    END LOOP;
  ELSE
    v_period_start := v_new_start_date;
    WHILE v_period_start <= v_new_end_date LOOP
      v_period_end := (v_period_start + (v_period_months || ' month')::interval - interval '1 day')::date;
      IF v_period_end > v_new_end_date THEN
        v_period_end := v_new_end_date;
      END IF;

      v_period_amount := ROUND(COALESCE(v_monthly_base, 0) * v_period_months, 2);

      IF v_method = 'Vencido' THEN
        v_issue_date := v_period_end;
      ELSE
        v_issue_date := v_period_start;
      END IF;
      v_due_date := v_issue_date + interval '30 days';

      v_subtotal := v_period_amount;
      v_tax_amount := ROUND(v_subtotal * (v_company_tax_rate / 100), 2);
      v_total := v_subtotal + v_tax_amount;

      INSERT INTO public.invoices (
        company_id, client_id, client_entity_id, contract_id,
        scheduled_at, original_issue_date, issue_date, due_date,
        vat, amount_contract_currency, amount_invoice_currency,
        total_invoice_currency, total_system_currency,
        contract_currency, invoice_currency, fx_contract_to_invoice,
        status, invoice_type, document_type, export_type, invoice_series,
        holding_id, issuer_legal_name, issuer_tax_id, issuer_address, client_tax_id,
        notes
      ) VALUES (
        v_contract_record.company_id, v_contract_record.client_id,
        v_contract_record.client_entity_id, p_contract_id,
        CASE WHEN v_method = 'Vencido' THEN v_period_end ELSE v_period_start END,
        CASE WHEN v_method = 'Vencido' THEN v_period_end ELSE v_period_start END,
        v_issue_date, v_due_date,
        v_tax_amount, v_subtotal, v_subtotal, v_total, v_total,
        v_original_item.currency, v_original_item.currency, 1.0,
        'Por Emitir',
        'Automatica',
        'FACTURA', 1, 'FAC',
        v_holding_id,
        (SELECT legal_name FROM companies WHERE id = v_contract_record.company_id),
        (SELECT tax_id FROM companies WHERE id = v_contract_record.company_id),
        (SELECT legal_address FROM companies WHERE id = v_contract_record.company_id),
        (SELECT ce.tax_id FROM client_entities ce WHERE ce.id = v_contract_record.client_entity_id),
        'Renovación de contrato'
      ) RETURNING id INTO v_new_invoice_id;

      v_item_qty := COALESCE(v_renewal_quantity, 1);
      v_item_unit_price := ROUND(v_subtotal / v_item_qty, 6);

      INSERT INTO public.invoice_items (
        invoice_id, contract_item_id, product_id,
        description, quantity, unit_of_measure,
        unit_price_contract_currency, unit_price_invoice_currency,
        discount_pct,
        subtotal_contract_currency, subtotal_invoice_currency,
        tax_amount_contract_currency, tax_amount_invoice_currency,
        total_contract_currency, total_invoice_currency,
        contract_currency, invoice_currency, fx_contract_to_invoice,
        holding_id, contract_id,
        billing_period_start, billing_period_end
      ) VALUES (
        v_new_invoice_id, v_new_item_id, v_original_item.product_id,
        v_original_item.product_name || CASE WHEN NULLIF(TRIM(v_original_item.account), '') IS NOT NULL THEN ' Cuenta ' || TRIM(v_original_item.account) ELSE '' END || ' - Periodo '
          || TO_CHAR(v_period_start, 'DD/MM/YYYY') || ' a '
          || TO_CHAR(v_period_end, 'DD/MM/YYYY'),
        v_item_qty, COALESCE(v_original_item.unit_of_measure, 'UND'),
        v_item_unit_price, v_item_unit_price,
        0,
        v_subtotal, v_subtotal,
        v_tax_amount, v_tax_amount,
        v_total, v_total,
        v_original_item.currency, v_original_item.currency, 1,
        v_holding_id, p_contract_id,
        v_period_start, v_period_end
      );

      v_invoice_count := v_invoice_count + 1;
      v_created_invoices := v_created_invoices || jsonb_build_object(
        'id', v_new_invoice_id,
        'scheduled_at', CASE WHEN v_method = 'Vencido' THEN v_period_end ELSE v_period_start END,
        'amount', v_total
      );

      v_period_start := (v_period_start + (v_period_months || ' month')::interval)::date;
    END LOOP;
  END IF;

  UPDATE public.contract_amendments
  SET status = 'Approved', approved_by = v_user_id
  WHERE id = v_amendment_id;

  INSERT INTO public.contract_lifecycle_events (
    contract_id, event_type, event_status, title, description,
    effective_date, created_by, completed_at, holding_id, metadata
  ) VALUES (
    p_contract_id, 'renewal', 'completed', 'Renovación Aplicada',
    'Renovación de contrato aplicada automáticamente', p_effective_date,
    v_user_id, now(), v_holding_id,
    jsonb_build_object(
      'amendment_id', v_amendment_id, 'created_items', v_created_items,
      'created_invoices', v_created_invoices, 'invoice_count', v_invoice_count,
      'auto_applied', true, 'billing_frequency', v_freq, 'billing_method', v_method,
      'price_changed', v_has_price_change,
      'consolidated_children_count', COALESCE(array_length(v_children_ids, 1), 0),
      'consolidated_children_ids', to_jsonb(v_children_ids)
    )
  ) RETURNING id INTO v_lifecycle_event_id;

  RETURN jsonb_build_object(
    'success', true, 'approval_required', false, 'amendment_id', v_amendment_id,
    'lifecycle_event_id', v_lifecycle_event_id, 'created_items', v_created_items,
    'created_invoices', v_created_invoices, 'invoice_count', v_invoice_count,
    'price_changed', v_has_price_change,
    'consolidated_children_count', COALESCE(array_length(v_children_ids, 1), 0),
    'message', 'Renovación aplicada exitosamente'
  );
EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'Error en renovación: %', SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_contract_upsell(p_contract_id uuid, p_items jsonb, p_effective_date date, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_approval_required boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_holding uuid;
  v_user uuid;
  v_item jsonb;
  v_result jsonb;
  v_total_delta numeric := 0;
  v_items_summary jsonb := '[]'::jsonb;
BEGIN
  SELECT public.get_contract_holding(p_contract_id) INTO v_holding;
  IF v_holding IS NULL THEN
    RAISE EXCEPTION 'Contrato no encontrado';
  END IF;

  SELECT public.get_current_user_id() INTO v_user;

  INSERT INTO public.contract_amendments(
    contract_id, holding_id, type, status, effective_date, reason, metadata, approval_required, requested_by
  ) VALUES (
    p_contract_id,
    v_holding,
    'UPSELL',
    CASE WHEN p_approval_required THEN 'Pending' ELSE 'Approved' END,
    p_effective_date,
    p_reason,
    COALESCE(p_metadata, '{}'::jsonb),
    p_approval_required,
    v_user
  ) RETURNING id INTO v_id;

  IF p_items IS NOT NULL THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
      INSERT INTO public.contract_amendment_items(
        amendment_id, holding_id, original_item_id, price_delta, quantity_delta,
        start_date_override, end_date_override, scope, notes, item_metadata
      ) VALUES (
        v_id,
        v_holding,
        NULLIF(v_item->>'original_item_id', '')::uuid,
        (v_item->>'price_delta')::numeric,
        (v_item->>'quantity_delta')::numeric,
        NULLIF(v_item->>'start_date_override', '')::date,
        NULLIF(v_item->>'end_date_override', '')::date,
        NULLIF(v_item->>'scope', '')::amendment_scope_type,
        v_item->>'notes',
        COALESCE(v_item->'item_metadata', '{}'::jsonb)
      );

      -- Acumular delta para el resumen
      v_total_delta := v_total_delta + COALESCE((v_item->>'price_delta')::numeric, 0);
      v_items_summary := v_items_summary || jsonb_build_array(
        jsonb_build_object(
          'original_item_id', v_item->>'original_item_id',
          'price_delta', v_item->>'price_delta'
        )
      );
    END LOOP;
  END IF;

  IF NOT p_approval_required THEN
    v_result := public.approve_contract_amendment(v_id, true, 'Auto-aprobado');

    -- NUEVO: Registrar evento en el historial del ciclo de vida
    -- La función approve_contract_amendment ya llama a log_lifecycle_event,
    -- pero solo cuando hay aprobación manual. Para auto-aprobaciones,
    -- el evento ya se registra dentro de approve_contract_amendment.
    -- No necesitamos duplicar la llamada aquí.
  END IF;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_credit_note_safe(p_invoice_id uuid, p_credit_type credit_note_type, p_reason credit_note_reason, p_amount_contract_currency numeric, p_notes text DEFAULT NULL::text, p_new_date date DEFAULT NULL::date, p_nc_issue_date date DEFAULT NULL::date, p_nc_invoice_number text DEFAULT NULL::text, p_nc_fx_rate numeric DEFAULT NULL::numeric, p_revenue_treatment text DEFAULT NULL::text)
 RETURNS TABLE(success boolean, credit_note_id uuid, new_invoice_id uuid, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_holding_id uuid;
  v_invoice public.invoices%ROWTYPE;
  v_nc_invoice_id uuid;
  v_replacement_id uuid := NULL;
  v_replacement_scheduled_at date;
  v_replacement_due_date date;
  v_existing_cancellation_count integer;
  v_ratio numeric;
  v_amount_invoice numeric;
  v_total_subtotal_contract numeric := 0;
  v_total_subtotal_invoice numeric := 0;
  v_total_tax_contract numeric := 0;
  v_total_tax_invoice numeric := 0;
  v_nc_total numeric := 0;
  v_fx_system_ratio numeric;
  v_nc_initial_status text;
  v_orig_item RECORD;
  v_new_item_id uuid;
  v_nc_fx_to_invoice numeric;
  v_nc_issue_date date;
  -- F2: distribución proporcional del descuento entre líneas de la original
  v_orig_total_subtotal numeric := 0;
  v_dist_line_count integer := 0;
  v_dist_line_idx integer := 0;
  v_dist_remaining numeric;
  v_line_amount numeric;
  -- IVA de la NC: SIEMPRE neto × tax_rate de la factura original (regla de
  -- negocio 2026-07-27) — nunca se prorratea el IVA almacenado.
  v_line_tax numeric;
  v_line_tax_invoice numeric;
BEGIN
  SELECT id INTO v_user_id FROM public.users WHERE auth_id = auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado o no encontrado';
  END IF;

  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Factura no encontrada'; END IF;

  v_holding_id := v_invoice.holding_id;

  IF NOT EXISTS (SELECT 1 FROM public.user_holdings WHERE user_id = v_user_id AND holding_id = v_holding_id) THEN
    RAISE EXCEPTION 'Sin permisos sobre el holding de la factura';
  END IF;

  IF v_invoice.document_type = 'NC' THEN RAISE EXCEPTION 'No se puede emitir una NC sobre otra NC'; END IF;
  IF v_invoice.status = 'Cancelada' THEN RAISE EXCEPTION 'La factura ya está cancelada'; END IF;
  IF v_invoice.status NOT IN ('Emitida','Enviada','Vencida','Pagada') THEN
    RAISE EXCEPTION 'No se puede emitir NC sobre una factura en estado "%". Solo se permite sobre Emitida, Enviada, Vencida o Pagada.', v_invoice.status;
  END IF;

  IF p_credit_type = 'cancellation' THEN
    SELECT COUNT(*) INTO v_existing_cancellation_count
    FROM public.invoices
    WHERE related_invoice_id = p_invoice_id AND credit_type = 'cancellation' AND document_type = 'NC';
    IF v_existing_cancellation_count > 0 THEN RAISE EXCEPTION 'Ya existe una NC de anulación previa para esta factura'; END IF;
    -- F2: el tratamiento de revenue solo aplica a descuentos
    IF p_revenue_treatment IS NOT NULL THEN
      RAISE EXCEPTION 'El tratamiento de revenue solo aplica a NC de tipo descuento';
    END IF;
  ELSIF p_credit_type = 'discount' THEN
    IF p_amount_contract_currency IS NULL OR p_amount_contract_currency <= 0 THEN
      RAISE EXCEPTION 'El monto del descuento debe ser mayor a 0';
    END IF;
    IF p_amount_contract_currency > COALESCE(v_invoice.amount_contract_currency, 0) THEN
      RAISE EXCEPTION 'El monto del descuento (%) no puede ser mayor al monto de la factura (%)',
        p_amount_contract_currency, v_invoice.amount_contract_currency;
    END IF;
    -- F2: devengo del descuento OBLIGATORIO (sin default implícito)
    IF p_revenue_treatment IS NULL OR p_revenue_treatment NOT IN ('impact_month', 'defer_forward') THEN
      RAISE EXCEPTION 'Debes indicar cómo devengar el descuento: impact_month (impactar el mes de la NC) o defer_forward (devengar hacia adelante)';
    END IF;
  END IF;

  IF COALESCE(v_invoice.amount_contract_currency, 0) > 0 AND COALESCE(v_invoice.amount_invoice_currency, 0) > 0 THEN
    v_ratio := v_invoice.amount_contract_currency::numeric / v_invoice.amount_invoice_currency::numeric;
  ELSE
    v_ratio := 1;
  END IF;

  v_nc_initial_status := CASE p_credit_type WHEN 'cancellation' THEN 'Cancelada' ELSE 'Emitida' END;

  v_nc_issue_date    := COALESCE(p_nc_issue_date, CURRENT_DATE);
  v_nc_fx_to_invoice := COALESCE(p_nc_fx_rate, v_invoice.fx_contract_to_invoice, 1);

  INSERT INTO public.invoices(
    holding_id, company_id, client_id, client_entity_id, contract_id,
    issue_date, due_date, scheduled_at, original_issue_date,
    contract_currency, invoice_currency, system_currency,
    amount_contract_currency, amount_invoice_currency,
    vat, total_invoice_currency, amount_system_currency, total_system_currency,
    fx_contract_to_invoice, fx_contract_to_system,
    status, invoice_type, document_type, related_invoice_id,
    issuer_tax_id, issuer_legal_name, issuer_address,
    client_tax_id, payment_method, fiscal_regime, export_type,
    tax_rate, notes, invoice_number,
    credit_type, credit_reason, nc_revenue_treatment
  ) VALUES (
    v_holding_id, v_invoice.company_id, v_invoice.client_id, v_invoice.client_entity_id, v_invoice.contract_id,
    v_nc_issue_date, v_nc_issue_date, v_nc_issue_date, v_nc_issue_date,
    v_invoice.contract_currency, v_invoice.invoice_currency, v_invoice.system_currency,
    0, 0, 0, 0, 0, 0,
    v_nc_fx_to_invoice, COALESCE(v_invoice.fx_contract_to_system, 1),
    v_nc_initial_status, 'Manual', 'NC', p_invoice_id,
    v_invoice.issuer_tax_id, v_invoice.issuer_legal_name, v_invoice.issuer_address,
    v_invoice.client_tax_id, v_invoice.payment_method, v_invoice.fiscal_regime, v_invoice.export_type,
    v_invoice.tax_rate,
    'NC ' || p_credit_type::text || ' / ' || p_reason::text || COALESCE(' — ' || p_notes, ''),
    p_nc_invoice_number,
    p_credit_type::text, p_reason::text,
    CASE WHEN p_credit_type = 'discount' THEN p_revenue_treatment ELSE NULL END
  ) RETURNING id INTO v_nc_invoice_id;

  IF p_credit_type = 'cancellation' THEN
    FOR v_orig_item IN SELECT * FROM public.invoice_items WHERE invoice_id = p_invoice_id ORDER BY created_at LOOP
      INSERT INTO public.invoice_items(
        holding_id, invoice_id, contract_id, product_id,
        description, quantity, unit_of_measure, discount_pct, tax_code,
        unit_price_contract_currency, unit_price_invoice_currency,
        subtotal_contract_currency, subtotal_invoice_currency,
        tax_amount_contract_currency, tax_amount_invoice_currency,
        total_contract_currency, total_invoice_currency,
        contract_currency, invoice_currency, fx_contract_to_invoice,
        billing_period_start, billing_period_end
      ) VALUES (
        v_holding_id, v_nc_invoice_id, v_orig_item.contract_id, v_orig_item.product_id,
        COALESCE(v_orig_item.description, '') || ' (NC anulación)',
        v_orig_item.quantity, COALESCE(v_orig_item.unit_of_measure, 'UND'), COALESCE(v_orig_item.discount_pct, 0), v_orig_item.tax_code,
        -ABS(COALESCE(v_orig_item.unit_price_contract_currency, 0)), -ABS(COALESCE(v_orig_item.unit_price_invoice_currency, 0)),
        -ABS(COALESCE(v_orig_item.subtotal_contract_currency, 0)), -ABS(COALESCE(v_orig_item.subtotal_invoice_currency, 0)),
        -ABS(COALESCE(v_orig_item.tax_amount_contract_currency, 0)), -ABS(COALESCE(v_orig_item.tax_amount_invoice_currency, 0)),
        -ABS(COALESCE(v_orig_item.total_contract_currency, 0)), -ABS(COALESCE(v_orig_item.total_invoice_currency, 0)),
        v_orig_item.contract_currency, v_orig_item.invoice_currency, COALESCE(v_orig_item.fx_contract_to_invoice, 1),
        v_orig_item.billing_period_start, v_orig_item.billing_period_end
      ) RETURNING id INTO v_new_item_id;

      IF v_orig_item.contract_item_id IS NOT NULL THEN
        UPDATE public.invoice_items SET contract_item_id = v_orig_item.contract_item_id WHERE id = v_new_item_id;
      END IF;
    END LOOP;
  ELSE
    -- F2: la NC de descuento se distribuye proporcionalmente entre las líneas
    -- POSITIVAS de la factura original (por subtotal en moneda de contrato),
    -- heredando contract_item_id (vía UPDATE post-insert, bypass del trigger
    -- standardize), producto y billing period. La última línea absorbe el
    -- residuo de redondeo para que la suma sea exacta. Patrón NC32.
    SELECT COALESCE(SUM(subtotal_contract_currency), 0), COUNT(*)
    INTO v_orig_total_subtotal, v_dist_line_count
    FROM public.invoice_items
    WHERE invoice_id = p_invoice_id AND COALESCE(subtotal_contract_currency, 0) > 0;

    IF v_dist_line_count = 0 OR v_orig_total_subtotal <= 0 THEN
      -- Fallback (factura sin líneas con subtotal positivo): línea única
      -- genérica sin vínculo a ítem — comportamiento previo. Invisible para el
      -- devengo por ítem; solo netea el total facturado del documento.
      v_amount_invoice := p_amount_contract_currency / NULLIF(v_ratio, 0);
      IF v_amount_invoice IS NULL THEN v_amount_invoice := p_amount_contract_currency; END IF;
      v_line_tax := ROUND(p_amount_contract_currency * COALESCE(v_invoice.tax_rate, 0) / 100, 2);
      v_line_tax_invoice := ROUND(v_amount_invoice * COALESCE(v_invoice.tax_rate, 0) / 100, 2);

      INSERT INTO public.invoice_items(
        holding_id, invoice_id, contract_id, description, quantity, unit_of_measure, discount_pct,
        unit_price_contract_currency, unit_price_invoice_currency,
        subtotal_contract_currency, subtotal_invoice_currency,
        tax_amount_contract_currency, tax_amount_invoice_currency,
        total_contract_currency, total_invoice_currency,
        contract_currency, invoice_currency, fx_contract_to_invoice
      ) VALUES (
        v_holding_id, v_nc_invoice_id, v_invoice.contract_id,
        'Descuento aplicado' || COALESCE(' — ' || p_notes, ''),
        1, 'UND', 0,
        -ABS(p_amount_contract_currency), -ABS(v_amount_invoice),
        -ABS(p_amount_contract_currency), -ABS(v_amount_invoice),
        -ABS(v_line_tax), -ABS(v_line_tax_invoice),
        -ABS(p_amount_contract_currency + v_line_tax), -ABS(v_amount_invoice + v_line_tax_invoice),
        v_invoice.contract_currency, v_invoice.invoice_currency, COALESCE(v_invoice.fx_contract_to_invoice, 1)
      );
    ELSE
      v_dist_remaining := p_amount_contract_currency;
      v_dist_line_idx := 0;

      FOR v_orig_item IN
        SELECT * FROM public.invoice_items
        WHERE invoice_id = p_invoice_id AND COALESCE(subtotal_contract_currency, 0) > 0
        ORDER BY created_at, id
      LOOP
        v_dist_line_idx := v_dist_line_idx + 1;
        IF v_dist_line_idx = v_dist_line_count THEN
          v_line_amount := v_dist_remaining;
        ELSE
          v_line_amount := ROUND(p_amount_contract_currency * v_orig_item.subtotal_contract_currency / v_orig_total_subtotal, 2);
          v_dist_remaining := v_dist_remaining - v_line_amount;
        END IF;

        v_amount_invoice := v_line_amount / NULLIF(v_ratio, 0);
        IF v_amount_invoice IS NULL THEN v_amount_invoice := v_line_amount; END IF;
        v_line_tax := ROUND(v_line_amount * COALESCE(v_invoice.tax_rate, 0) / 100, 2);
        v_line_tax_invoice := ROUND(v_amount_invoice * COALESCE(v_invoice.tax_rate, 0) / 100, 2);

        INSERT INTO public.invoice_items(
          holding_id, invoice_id, contract_id, product_id,
          description, quantity, unit_of_measure, discount_pct, tax_code,
          unit_price_contract_currency, unit_price_invoice_currency,
          subtotal_contract_currency, subtotal_invoice_currency,
          tax_amount_contract_currency, tax_amount_invoice_currency,
          total_contract_currency, total_invoice_currency,
          contract_currency, invoice_currency, fx_contract_to_invoice,
          billing_period_start, billing_period_end
        ) VALUES (
          v_holding_id, v_nc_invoice_id, v_orig_item.contract_id, v_orig_item.product_id,
          COALESCE(v_orig_item.description, '') || ' (NC descuento)',
          1, 'UND', 0, v_orig_item.tax_code,
          -ABS(v_line_amount), -ABS(v_amount_invoice),
          -ABS(v_line_amount), -ABS(v_amount_invoice),
          -ABS(v_line_tax), -ABS(v_line_tax_invoice),
          -ABS(v_line_amount + v_line_tax), -ABS(v_amount_invoice + v_line_tax_invoice),
          v_orig_item.contract_currency, v_orig_item.invoice_currency, COALESCE(v_orig_item.fx_contract_to_invoice, 1),
          v_orig_item.billing_period_start, v_orig_item.billing_period_end
        ) RETURNING id INTO v_new_item_id;

        IF v_orig_item.contract_item_id IS NOT NULL THEN
          UPDATE public.invoice_items SET contract_item_id = v_orig_item.contract_item_id WHERE id = v_new_item_id;
        END IF;
      END LOOP;
    END IF;
  END IF;

  IF p_nc_fx_rate IS NOT NULL AND p_nc_fx_rate > 0 THEN
    UPDATE public.invoice_items
    SET unit_price_invoice_currency = ROUND(unit_price_contract_currency / p_nc_fx_rate, 2),
        subtotal_invoice_currency   = ROUND(subtotal_contract_currency   / p_nc_fx_rate, 2),
        tax_amount_invoice_currency = ROUND(tax_amount_contract_currency / p_nc_fx_rate, 2),
        total_invoice_currency      = ROUND(total_contract_currency      / p_nc_fx_rate, 2),
        fx_contract_to_invoice      = p_nc_fx_rate
    WHERE invoice_id = v_nc_invoice_id;
  END IF;

  SELECT COALESCE(SUM(subtotal_contract_currency), 0), COALESCE(SUM(subtotal_invoice_currency), 0),
         COALESCE(SUM(tax_amount_contract_currency), 0), COALESCE(SUM(tax_amount_invoice_currency), 0)
  INTO v_total_subtotal_contract, v_total_subtotal_invoice, v_total_tax_contract, v_total_tax_invoice
  FROM public.invoice_items WHERE invoice_id = v_nc_invoice_id;

  IF COALESCE(v_invoice.fx_contract_to_invoice, 0) > 0 THEN
    v_fx_system_ratio := COALESCE(v_invoice.fx_contract_to_system, v_invoice.fx_contract_to_invoice) / v_invoice.fx_contract_to_invoice;
  ELSE
    v_fx_system_ratio := 1;
  END IF;

  UPDATE public.invoices
  SET amount_contract_currency = v_total_subtotal_contract,
      amount_invoice_currency  = v_total_subtotal_invoice,
      vat                      = v_total_tax_contract,
      total_invoice_currency   = v_total_subtotal_invoice + v_total_tax_invoice,
      amount_system_currency   = (v_total_subtotal_invoice) * v_fx_system_ratio,
      total_system_currency    = (v_total_subtotal_invoice + v_total_tax_invoice) * v_fx_system_ratio
  WHERE id = v_nc_invoice_id;

  v_nc_total := v_total_subtotal_contract + v_total_tax_contract;

  IF p_credit_type = 'cancellation' THEN
    UPDATE public.invoices
    SET status = 'Cancelada',
        notes = COALESCE(notes || E'\n', '') || 'Anulada por NC ' || v_nc_invoice_id::text
    WHERE id = p_invoice_id;

    v_replacement_scheduled_at := COALESCE(p_new_date, v_invoice.scheduled_at, CURRENT_DATE);

    IF v_invoice.due_date IS NOT NULL AND v_invoice.issue_date IS NOT NULL THEN
      v_replacement_due_date := v_replacement_scheduled_at + (v_invoice.due_date - v_invoice.issue_date);
    ELSE
      v_replacement_due_date := v_replacement_scheduled_at + INTERVAL '30 days';
    END IF;

    INSERT INTO public.invoices(
      holding_id, company_id, client_id, client_entity_id, contract_id,
      issue_date, due_date, scheduled_at, original_issue_date,
      contract_currency, invoice_currency, system_currency,
      amount_contract_currency, amount_invoice_currency,
      vat, total_invoice_currency, amount_system_currency, total_system_currency,
      fx_contract_to_invoice, fx_contract_to_system,
      status, invoice_type, document_type,
      issuer_tax_id, issuer_legal_name, issuer_address,
      client_tax_id, payment_method, fiscal_regime, export_type,
      tax_rate, notes
    ) VALUES (
      v_holding_id, v_invoice.company_id, v_invoice.client_id, v_invoice.client_entity_id, v_invoice.contract_id,
      v_replacement_scheduled_at, v_replacement_due_date, v_replacement_scheduled_at, v_replacement_scheduled_at,
      v_invoice.contract_currency, v_invoice.invoice_currency, v_invoice.system_currency,
      v_invoice.amount_contract_currency, v_invoice.amount_invoice_currency,
      v_invoice.vat, v_invoice.total_invoice_currency, v_invoice.amount_system_currency, v_invoice.total_system_currency,
      COALESCE(v_invoice.fx_contract_to_invoice, 1), COALESCE(v_invoice.fx_contract_to_system, 1),
      'Por Emitir', 'Manual', 'FACTURA',
      v_invoice.issuer_tax_id, v_invoice.issuer_legal_name, v_invoice.issuer_address,
      v_invoice.client_tax_id, v_invoice.payment_method, v_invoice.fiscal_regime, v_invoice.export_type,
      v_invoice.tax_rate,
      'Reemplazo de ' || COALESCE(v_invoice.invoice_number, v_invoice.id::text) || ' (anulada por NC)'
    ) RETURNING id INTO v_replacement_id;

    FOR v_orig_item IN SELECT * FROM public.invoice_items WHERE invoice_id = p_invoice_id ORDER BY created_at LOOP
      INSERT INTO public.invoice_items(
        holding_id, invoice_id, contract_id, product_id,
        description, quantity, unit_of_measure, discount_pct, tax_code,
        unit_price_contract_currency, unit_price_invoice_currency,
        subtotal_contract_currency, subtotal_invoice_currency,
        tax_amount_contract_currency, tax_amount_invoice_currency,
        total_contract_currency, total_invoice_currency,
        contract_currency, invoice_currency, fx_contract_to_invoice,
        billing_period_start, billing_period_end
      ) VALUES (
        v_holding_id, v_replacement_id, v_orig_item.contract_id, v_orig_item.product_id,
        v_orig_item.description, v_orig_item.quantity, COALESCE(v_orig_item.unit_of_measure, 'UND'),
        COALESCE(v_orig_item.discount_pct, 0), v_orig_item.tax_code,
        v_orig_item.unit_price_contract_currency, v_orig_item.unit_price_invoice_currency,
        v_orig_item.subtotal_contract_currency, v_orig_item.subtotal_invoice_currency,
        v_orig_item.tax_amount_contract_currency, v_orig_item.tax_amount_invoice_currency,
        v_orig_item.total_contract_currency, v_orig_item.total_invoice_currency,
        v_orig_item.contract_currency, v_orig_item.invoice_currency, COALESCE(v_orig_item.fx_contract_to_invoice, 1),
        v_orig_item.billing_period_start, v_orig_item.billing_period_end
      ) RETURNING id INTO v_new_item_id;

      IF v_orig_item.contract_item_id IS NOT NULL THEN
        UPDATE public.invoice_items SET contract_item_id = v_orig_item.contract_item_id WHERE id = v_new_item_id;
      END IF;
    END LOOP;
  END IF;

  IF v_invoice.contract_id IS NOT NULL THEN
    PERFORM public.log_lifecycle_event(
      v_invoice.contract_id,
      CASE WHEN p_credit_type = 'cancellation' THEN 'INVOICE_CANCELLED' ELSE 'INVOICE_CREDIT_NOTE' END,
      'NC manual por ' || p_reason::text,
      CURRENT_DATE, v_nc_total,
      'NC ' || p_credit_type::text || ' sobre factura ' || COALESCE(v_invoice.invoice_number, 'sin número'),
      COALESCE(p_notes, ''),
      jsonb_build_object(
        'original_invoice_id', p_invoice_id,
        'nc_invoice_id', v_nc_invoice_id,
        'replacement_invoice_id', v_replacement_id,
        'credit_type', p_credit_type::text,
        'credit_reason', p_reason::text,
        'nc_status', v_nc_initial_status,
        'nc_issue_date', v_nc_issue_date,
        'nc_invoice_number', p_nc_invoice_number,
        'nc_fx_rate', p_nc_fx_rate,
        'nc_revenue_treatment', CASE WHEN p_credit_type = 'discount' THEN p_revenue_treatment ELSE NULL END
      ),
      p_reason::text, 'Recorded'
    );
  END IF;

  RETURN QUERY SELECT true, v_nc_invoice_id, v_replacement_id,
    CASE WHEN p_credit_type = 'cancellation'
         THEN 'Nota de crédito registrada (Cancelada, no afecta KPIs) y factura de reemplazo Por Emitir generada'
         ELSE 'Nota de crédito (descuento) registrada'
    END::text;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_legacy_contract_with_items(p_contract_data jsonb, p_items jsonb[], p_client_entity_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_company_id uuid DEFAULT NULL::uuid, p_group_by_period boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_holding_id           uuid;
  v_company_id           uuid;
  v_contract_id          uuid;
  v_item                 jsonb;
  v_item_id              uuid;
  v_client_id            uuid;
  v_existing_client_id   uuid;
  v_contract_currency    text;
  v_booking_date         date;
  v_contract_end_date    date;
  v_contract_start_date  date;
  v_total_contract_value numeric;
  v_has_previous_contract boolean;
  v_item_categoria       text;
  -- Variables para generacion per-item de contract_invoices
  v_contract_item        record;
  v_item_period_months   integer;
  v_item_num_periods     integer;
  v_item_period_amount   numeric;
  v_item_invoice_date    date;
  v_invoices_created     integer := 0;
BEGIN
  -- Obtener holding_id
  IF p_user_id IS NOT NULL THEN
    SELECT holding_id INTO v_holding_id
    FROM user_holdings WHERE user_id = p_user_id LIMIT 1;
  ELSE
    SELECT holding_id INTO v_holding_id
    FROM user_holdings WHERE user_id = auth.uid() LIMIT 1;
  END IF;
  IF v_holding_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No se pudo obtener holding_id del usuario');
  END IF;
  -- Resolver company_id
  IF p_company_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM companies WHERE id = p_company_id AND holding_id = v_holding_id) THEN
      v_company_id := p_company_id;
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'La compania especificada no pertenece al holding');
    END IF;
  ELSE
    SELECT id INTO v_company_id FROM companies WHERE holding_id = v_holding_id LIMIT 1;
  END IF;
  IF v_company_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No se encontro una compania para el holding');
  END IF;
  -- Validar client_id
  v_client_id := (p_contract_data->>'client_id')::uuid;
  IF v_client_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Debe seleccionar un cliente comercial');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM clients WHERE id = v_client_id AND holding_id = v_holding_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cliente no pertenece al holding');
  END IF;
  -- Asociar client_entity <-> client si aun no tiene client_id
  SELECT client_id INTO v_existing_client_id FROM client_entities WHERE id = p_client_entity_id;
  IF v_existing_client_id IS NULL THEN
    UPDATE client_entities SET client_id = v_client_id WHERE id = p_client_entity_id;
    RAISE NOTICE 'Client entity % asociado con client %', p_client_entity_id, v_client_id;
  ELSIF v_existing_client_id != v_client_id THEN
    RAISE NOTICE 'Client entity % ya asociado con client %, usando % para el contrato',
      p_client_entity_id, v_existing_client_id, v_client_id;
  END IF;
  -- FIX: Asegurar registro en junction table (client_entity_clients)
  INSERT INTO client_entity_clients (client_entity_id, client_id, holding_id, is_primary)
  VALUES (
    p_client_entity_id,
    v_client_id,
    v_holding_id,
    NOT EXISTS (SELECT 1 FROM client_entity_clients WHERE client_entity_id = p_client_entity_id)
  )
  ON CONFLICT (client_entity_id, client_id) DO NOTHING;
  -- Valores del contrato
  v_contract_currency    := p_contract_data->>'contract_currency';
  v_booking_date         := COALESCE((p_contract_data->>'booking_date')::date,   CURRENT_DATE);
  v_contract_end_date    := (p_contract_data->>'contract_end_date')::date;
  v_contract_start_date  := COALESCE((p_contract_data->>'contract_start_date')::date, v_booking_date);
  v_total_contract_value := COALESCE((p_contract_data->>'total_value')::numeric, 0);
  -- Categoria dinamica
  SELECT EXISTS (
    SELECT 1 FROM contracts
    WHERE client_id = v_client_id AND holding_id = v_holding_id
      AND is_legacy = true AND booking_date < v_booking_date
  ) INTO v_has_previous_contract;
  v_item_categoria := CASE WHEN v_has_previous_contract THEN 'UPSELL' ELSE 'NEW' END;
  -- Crear contrato legacy
  INSERT INTO contracts (
    holding_id, client_id, client_entity_id, company_id,
    contract_number, client_name_commercial, legal_client_name,
    legal_representative_name, legal_representative_id,
    contract_currency, type, status, term, total_value,
    booking_date, contract_end_date,
    is_legacy, legacy_status, legacy_cutoff_date, legacy_reconciliation_pct,
    notes, custom_fields, group_invoices_by_period, created_at
  ) VALUES (
    v_holding_id, v_client_id, p_client_entity_id, v_company_id,
    p_contract_data->>'contract_number',
    p_contract_data->>'client_name_commercial',
    p_contract_data->>'legal_client_name',
    p_contract_data->>'legal_representative_name',
    p_contract_data->>'legal_representative_id',
    v_contract_currency,
    COALESCE(p_contract_data->>'type', 'Servicio'),
    'En revisión',  -- FIX: acento correcto (antes: 'En revision')
    COALESCE((p_contract_data->>'term')::integer, 12),
    v_total_contract_value,
    v_booking_date, v_contract_end_date,
    true, 'in_reconciliation',
    (p_contract_data->>'legacy_cutoff_date')::date,
    0,
    p_contract_data->>'notes',
    COALESCE((p_contract_data->'custom_fields')::jsonb, '{}'::jsonb),
    p_group_by_period,
    NOW()
  )
  RETURNING id INTO v_contract_id;
  -- Insertar items del contrato
  FOREACH v_item IN ARRAY p_items LOOP
    INSERT INTO contract_items (
      contract_id, holding_id,
      product_id, product_name, term_months, currency,
      item_type, unit_of_measure,
      unit_price, quantity, price,
      discount_type, discount_value, final_price,
      start_date, end_date,
      billing_method, billing_frequency,
      is_recurring, categoria, account, custom_fields
    ) VALUES (
      v_contract_id, v_holding_id,
      (v_item->>'product_id')::uuid,
      v_item->>'product_name',
      COALESCE((v_item->>'term_months')::integer, 12),
      COALESCE(v_item->>'currency', v_contract_currency),
      v_item->>'item_type',
      v_item->>'unit_of_measure',
      (v_item->>'unit_price')::numeric,
      (v_item->>'quantity')::numeric,
      (v_item->>'price')::numeric,
      v_item->>'discount_type',
      COALESCE((v_item->>'discount_value')::numeric, 0),
      (v_item->>'final_price')::numeric,
      (v_item->>'start_date')::date,
      (v_item->>'end_date')::date,
      v_item->>'billing_method',
      v_item->>'billing_frequency',
      true,
      v_item_categoria,
      v_item->>'account',
      '{}'::jsonb
    )
    RETURNING id INTO v_item_id;
  END LOOP;
  -- Generar contract_invoices por item
  FOR v_contract_item IN
    SELECT id, product_name, final_price, term_months, billing_frequency, start_date, end_date
    FROM contract_items
    WHERE contract_id = v_contract_id
  LOOP
    v_item_period_months := CASE COALESCE(v_contract_item.billing_frequency, 'Mensual')
      WHEN 'Mensual'    THEN 1
      WHEN 'Trimestral' THEN 3
      WHEN 'Semestral'  THEN 6
      WHEN 'Anual'      THEN 12
      WHEN 'Bianual'    THEN 24
      ELSE 1
    END;
    v_item_num_periods := CEIL(
      COALESCE(v_contract_item.term_months, 12)::numeric / v_item_period_months
    );
    v_item_period_amount := ROUND(
      COALESCE(v_contract_item.final_price, 0) / NULLIF(v_item_num_periods, 0),
      2
    );
    FOR i IN 0..(v_item_num_periods - 1) LOOP
      v_item_invoice_date :=
        COALESCE(v_contract_item.start_date, v_contract_start_date)
        + (i * v_item_period_months * INTERVAL '1 month');
      IF v_item_invoice_date <= COALESCE(v_contract_item.end_date, v_contract_end_date, v_item_invoice_date) THEN
        INSERT INTO contract_invoices (
          contract_id, holding_id, invoice_date, amount, currency,
          status, contract_item_details, is_editable, is_satisfied
        ) VALUES (
          v_contract_id, v_holding_id, v_item_invoice_date, v_item_period_amount, v_contract_currency,
          'Programada',
          jsonb_build_array(jsonb_build_object(
            'contract_item_id', v_contract_item.id,
            'product_name',     v_contract_item.product_name,
            'amount',           v_item_period_amount
          )),
          true, false
        );
        v_invoices_created := v_invoices_created + 1;
      END IF;
    END LOOP;
  END LOOP;
  -- Consolidar por periodo si aplica
  IF p_group_by_period THEN
    WITH per_item_data AS (
      SELECT id, invoice_date, amount, contract_item_details
      FROM contract_invoices
      WHERE contract_id = v_contract_id
        AND COALESCE(is_satisfied, false) = false
    ),
    grouped AS (
      SELECT
        invoice_date,
        SUM(amount)  AS total_amount,
        jsonb_agg(detail ORDER BY (detail->>'contract_item_id')::text) AS combined_details
      FROM per_item_data,
      LATERAL jsonb_array_elements(contract_item_details) AS detail
      GROUP BY invoice_date
    ),
    deleted AS (
      DELETE FROM contract_invoices
      WHERE contract_id = v_contract_id
        AND COALESCE(is_satisfied, false) = false
    )
    INSERT INTO contract_invoices (
      contract_id, holding_id, invoice_date, amount, currency,
      status, contract_item_details, is_editable, is_satisfied
    )
    SELECT
      v_contract_id, v_holding_id, invoice_date, total_amount, v_contract_currency,
      'Programada', combined_details, true, false
    FROM grouped;
  END IF;
  RAISE NOTICE '[LEGACY_CONTRACT] Contract % created: % raw invoices, group_by_period=%',
    v_contract_id, v_invoices_created, p_group_by_period;
  RETURN jsonb_build_object(
    'success',         true,
    'contract_id',     v_contract_id,
    'contract_number', p_contract_data->>'contract_number'
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

