CREATE OR REPLACE FUNCTION public.create_user_holding_association_safe(p_user_id uuid, p_holding_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    -- Log para debugging
    RAISE NOTICE 'create_user_holding_association_safe called with user_id: %, holding_id: %', p_user_id, p_holding_id;

    -- Verificar que el usuario existe
    IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) THEN
        RAISE EXCEPTION 'User ID % does not exist', p_user_id;
    END IF;

    -- Verificar que el holding existe
    IF NOT EXISTS (SELECT 1 FROM public.company_holdings WHERE id = p_holding_id) THEN
        RAISE EXCEPTION 'Holding ID % does not exist', p_holding_id;
    END IF;

    -- Insertar la asociación (idempotente con ON CONFLICT)
    INSERT INTO public.user_holdings (user_id, holding_id)
    VALUES (p_user_id, p_holding_id)
    ON CONFLICT (user_id, holding_id) DO NOTHING;

    RAISE NOTICE 'User-holding association created/confirmed: user_id=%, holding_id=%', p_user_id, p_holding_id;

    RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_mrr_legacy_group(p_record_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_invoice_ids uuid[];
  v_deleted_count int;
  v_reverted_count int;
BEGIN
  -- Validar que los registros no estén migrados
  IF EXISTS (
    SELECT 1 FROM mrr_legacy
    WHERE id = ANY(p_record_ids)
      AND migrated_to_contract_id IS NOT NULL
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No se puede eliminar MRR Legacy ya migrado a contrato'
    );
  END IF;

  -- Obtener IDs de facturas afectadas
  SELECT ARRAY_AGG(DISTINCT invoice_legacy_id)
  INTO v_invoice_ids
  FROM mrr_legacy
  WHERE id = ANY(p_record_ids);

  -- Eliminar registros MRR Legacy
  DELETE FROM mrr_legacy
  WHERE id = ANY(p_record_ids);

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  -- Revertir estado de facturas a 'pending'
  -- Solo si no tienen otros registros MRR Legacy activos
  UPDATE invoices_legacy
  SET reconciliation_status = 'pending'
  WHERE id = ANY(v_invoice_ids)
    AND reconciliation_status = 'mrr_legacy'
    AND NOT EXISTS (
      SELECT 1 FROM mrr_legacy
      WHERE invoice_legacy_id = invoices_legacy.id
    );

  GET DIAGNOSTICS v_reverted_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count,
    'reverted_invoices', v_reverted_count
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_user_complete(user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  _holding_id uuid;
BEGIN
  -- Primero obtener el holding_id asociado al usuario
  SELECT holding_id INTO _holding_id FROM public.user_holdings WHERE user_id = delete_user_complete.user_id;

  -- Eliminar asociaciones en user_holdings
  DELETE FROM public.user_holdings WHERE user_id = delete_user_complete.user_id;

  -- Eliminar asociaciones en user_companies
  DELETE FROM public.user_companies WHERE user_id = delete_user_complete.user_id;

  -- Eliminar el usuario de la tabla users
  DELETE FROM public.users WHERE auth_id = delete_user_complete.user_id;

  -- Opcionalmente, si quieres también eliminar el holding si solo pertenecía a este usuario
  -- (descomenta si quieres esta funcionalidad)
  /*
  IF _holding_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.user_holdings WHERE holding_id = _holding_id AND user_id != delete_user_complete.user_id) THEN
      DELETE FROM public.company_holdings WHERE id = _holding_id;
    END IF;
  END IF;
  */

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.detect_invoice_changes(new_data jsonb, old_data jsonb, relevant_fields text[] DEFAULT ARRAY['name'::text, 'amount_total'::text, 'state'::text, 'invoice_date'::text])
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    field TEXT;
BEGIN
    -- Si no hay datos anteriores, siempre hay cambios
    IF old_data IS NULL THEN
        RETURN TRUE;
    END IF;

    -- Comparar cada campo relevante
    FOREACH field IN ARRAY relevant_fields
    LOOP
        IF (new_data ->> field) IS DISTINCT FROM (old_data ->> field) THEN
            RETURN TRUE;
        END IF;
    END LOOP;

    RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.detect_invoice_line_changes(new_data jsonb, old_data jsonb, relevant_fields text[] DEFAULT ARRAY['name'::text, 'quantity'::text, 'price_unit'::text, 'price_subtotal'::text])
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    field TEXT;
BEGIN
    -- Si no hay datos anteriores, siempre hay cambios
    IF old_data IS NULL THEN
        RETURN TRUE;
    END IF;

    -- Comparar cada campo relevante
    FOREACH field IN ARRAY relevant_fields
    LOOP
        IF (new_data ->> field) IS DISTINCT FROM (old_data ->> field) THEN
            RETURN TRUE;
        END IF;
    END LOOP;

    RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.detect_invoice_line_changes_with_dynamic_mapping(new_data jsonb, existing_line_id uuid, holding_id_param uuid)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    mapping_config JSONB;
    mapping_entry RECORD;
    source_field TEXT;
    target_field TEXT;
    source_value TEXT;
    target_value TEXT;
    has_changes BOOLEAN := FALSE;
    dynamic_sql TEXT;
BEGIN
    -- Obtener configuración de mapeo jerárquico para líneas
    SELECT fm.mapping_config INTO mapping_config
    FROM field_mappings fm
    WHERE fm.holding_id = holding_id_param
        AND fm.source_model = 'account.move'
        AND fm.target_table = 'invoices_legacy'
        AND fm.mapping_type = 'hierarchical'
        AND fm.is_active = true
    ORDER BY fm.created_at DESC
    LIMIT 1;

    -- Si hay mapeo configurado, usar comparación dinámica
    IF mapping_config IS NOT NULL AND mapping_config->'line_mappings' IS NOT NULL THEN
        -- Iterar sobre cada mapeo de línea configurado
        FOR mapping_entry IN SELECT * FROM jsonb_each(mapping_config->'line_mappings')
        LOOP
            -- Extraer campo fuente (Odoo)
            source_field := COALESCE(
                (mapping_entry.value->>'source'),
                (mapping_entry.value->>'odoo_field')
            );

            -- Campo destino (invoice_items_legacy)
            target_field := mapping_entry.key;

            IF source_field IS NOT NULL AND target_field IS NOT NULL THEN
                -- Obtener valor de Odoo (manejo de campos anidados)
                IF source_field LIKE '%_id' AND source_field != 'name' THEN
                    -- Campos relacionales como product_id (tomar el nombre)
                    source_value := new_data -> source_field ->> 1;
                ELSE
                    -- Campos simples
                    source_value := new_data ->> source_field;
                END IF;

                -- Consulta dinámica para obtener valor de invoice_items_legacy
                BEGIN
                    dynamic_sql := format(
                        'SELECT %I FROM invoice_items_legacy WHERE id = $1',
                        target_field
                    );

                    EXECUTE dynamic_sql INTO target_value USING existing_line_id;

                EXCEPTION WHEN OTHERS THEN
                    target_value := NULL;
                    RAISE NOTICE 'Error accediendo campo %: %', target_field, SQLERRM;
                END;

                -- Comparar valores
                IF source_value IS DISTINCT FROM target_value THEN
                    has_changes := TRUE;
                    RAISE NOTICE 'Cambio detectado en línea %: % -> %', target_field, target_value, source_value;
                    EXIT; -- Salir del loop si encuentra cambios
                END IF;
            END IF;
        END LOOP;

        -- Siempre comparar odoo_line_id (crítico)
        BEGIN
            EXECUTE 'SELECT odoo_line_id FROM invoice_items_legacy WHERE id = $1' 
            INTO target_value USING existing_line_id;

            IF (new_data ->> 'id') IS DISTINCT FROM target_value THEN
                has_changes := TRUE;
                RAISE NOTICE 'Cambio detectado en odoo_line_id';
            END IF;
        EXCEPTION WHEN OTHERS THEN
            has_changes := TRUE;
        END;

    ELSE
        -- FALLBACK: Si no hay mapeo, usar comparación básica de campos críticos
        BEGIN
            SELECT 
                CASE 
                    WHEN (new_data ->> 'name') IS DISTINCT FROM iil.description OR
                         (new_data ->> 'quantity') IS DISTINCT FROM iil.quantity::TEXT OR
                         (new_data ->> 'price_unit') IS DISTINCT FROM iil.unit_price::TEXT OR
                         (new_data ->> 'price_subtotal') IS DISTINCT FROM iil.subtotal::TEXT OR
                         (new_data -> 'product_id' ->> 1) IS DISTINCT FROM iil.product_name OR
                         (new_data ->> 'id') IS DISTINCT FROM iil.odoo_line_id
                    THEN TRUE
                    ELSE FALSE
                END
            INTO has_changes
            FROM invoice_items_legacy iil
            WHERE iil.id = existing_line_id;

        EXCEPTION WHEN OTHERS THEN
            has_changes := TRUE;
        END;
    END IF;

    RETURN has_changes;

EXCEPTION WHEN OTHERS THEN
    -- Si hay error, asumir que hay cambios
    RAISE NOTICE 'Error en detect_invoice_line_changes_with_dynamic_mapping: %', SQLERRM;
    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.detect_partner_changes(new_data jsonb, old_data jsonb, relevant_fields text[] DEFAULT ARRAY['name'::text, 'email'::text, 'vat'::text])
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    field TEXT;
BEGIN
    -- Si no hay datos anteriores, siempre hay cambios
    IF old_data IS NULL THEN
        RETURN TRUE;
    END IF;

    -- Comparar cada campo relevante
    FOREACH field IN ARRAY relevant_fields
    LOOP
        IF (new_data ->> field) IS DISTINCT FROM (old_data ->> field) THEN
            RETURN TRUE;
        END IF;
    END LOOP;

    RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.detect_partner_changes(new_data jsonb, old_data jsonb, holding_id_param uuid)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    mapping_config JSONB;
    mapping_entry RECORD;
    source_field TEXT;
    new_value TEXT;
    old_value TEXT;
BEGIN
    -- Si no hay datos anteriores, es un cambio
    IF old_data IS NULL THEN
        RETURN TRUE;
    END IF;

    -- Obtener el mapeo activo para este holding
    SELECT fm.mapping_config INTO mapping_config
    FROM field_mappings fm
    WHERE fm.holding_id = holding_id_param
        AND fm.source_model = 'res.partner'
        AND fm.target_table = 'client_entities'
        AND fm.is_active = true
    ORDER BY fm.created_at DESC
    LIMIT 1;

    -- Si no hay mapeo configurado, usar campos básicos
    IF mapping_config IS NULL OR mapping_config->'mappings' IS NULL THEN
        -- Fallback a campos básicos comunes
        IF (new_data ->> 'name') IS DISTINCT FROM (old_data ->> 'name') OR
           (new_data ->> 'email') IS DISTINCT FROM (old_data ->> 'email') OR
           (new_data ->> 'vat') IS DISTINCT FROM (old_data ->> 'vat') THEN
            RETURN TRUE;
        END IF;
        RETURN FALSE;
    END IF;

    -- Comparar cada campo mapeado (compatible con nuevo formato)
    FOR mapping_entry IN SELECT * FROM jsonb_each(mapping_config->'mappings')
    LOOP
        -- Extraer el nombre del campo fuente del mapeo (compatible con ambos formatos)
        source_field := COALESCE(
            mapping_entry.value->>'sourceField'->>'name',  -- Formato antiguo
            mapping_entry.value->>'odoo_field'             -- Formato nuevo
        );

        IF source_field IS NOT NULL THEN
            -- Obtener valores para comparar
            new_value := new_data ->> source_field;
            old_value := old_data ->> source_field;

            -- Si hay diferencia, es un cambio
            IF new_value IS DISTINCT FROM old_value THEN
                RETURN TRUE;
            END IF;
        END IF;
    END LOOP;

    -- No se detectaron cambios
    RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.detect_partner_changes_with_mapping(new_data jsonb, old_data jsonb, holding_id_param uuid)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    mapping_config JSONB;
    mapping_entry JSONB;
    source_field TEXT;
BEGIN
    -- Si no hay datos anteriores, siempre hay cambios
    IF old_data IS NULL THEN
        RETURN TRUE;
    END IF;

    -- Obtener el mapeo activo para este holding
    SELECT fm.mapping_config INTO mapping_config
    FROM field_mappings fm
    WHERE fm.holding_id = holding_id_param
        AND fm.source_model = 'res.partner'
        AND fm.target_table = 'client_entities'
        AND fm.is_active = true
    ORDER BY fm.created_at DESC
    LIMIT 1;

    -- Si no hay mapeo configurado, usar campos básicos
    IF mapping_config IS NULL OR mapping_config->'mappings' IS NULL THEN
        -- Fallback a campos básicos comunes
        IF (new_data ->> 'name') IS DISTINCT FROM (old_data ->> 'name') OR
           (new_data ->> 'email') IS DISTINCT FROM (old_data ->> 'email') OR
           (new_data ->> 'vat') IS DISTINCT FROM (old_data ->> 'vat') THEN
            RETURN TRUE;
        END IF;
        RETURN FALSE;
    END IF;

    -- Comparar cada campo mapeado
    FOR mapping_entry IN SELECT * FROM jsonb_each(mapping_config->'mappings')
    LOOP
        -- Extraer el nombre del campo fuente del mapeo
        source_field := mapping_entry.value->>'sourceField'->>'name';

        IF source_field IS NOT NULL THEN
