  IF OLD.company_currency          IS DISTINCT FROM NEW.company_currency          THEN v_fields_changed := array_append(v_fields_changed, 'company_currency'); END IF;
  IF OLD.system_currency           IS DISTINCT FROM NEW.system_currency           THEN v_fields_changed := array_append(v_fields_changed, 'system_currency'); END IF;
  IF OLD.fx_rate_to_system         IS DISTINCT FROM NEW.fx_rate_to_system         THEN v_fields_changed := array_append(v_fields_changed, 'fx_rate_to_system'); END IF;
  IF OLD.quote_id                  IS DISTINCT FROM NEW.quote_id                  THEN v_fields_changed := array_append(v_fields_changed, 'quote_id'); END IF;
  IF OLD.renewed_from_contract_id  IS DISTINCT FROM NEW.renewed_from_contract_id  THEN v_fields_changed := array_append(v_fields_changed, 'renewed_from_contract_id'); END IF;
  IF OLD.renewed_to_contract_id    IS DISTINCT FROM NEW.renewed_to_contract_id    THEN v_fields_changed := array_append(v_fields_changed, 'renewed_to_contract_id'); END IF;

  v_changed_locked := COALESCE(array_length(v_fields_changed, 1), 0) > 0;
  IF NOT v_changed_locked THEN
    RETURN NEW;
  END IF;

  v_cutoff := public.get_cutoff_date(OLD.holding_id, OLD.company_id);
  IF v_cutoff IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.contract_items
     WHERE contract_id = NEW.id
       AND start_date <= v_cutoff
  ) INTO v_has_locked_item;

  IF NOT v_has_locked_item THEN
    RETURN NEW;
  END IF;

  v_warn_msg := format(
    'UPDATE bloqueado en contracts.%s — al menos un ítem tiene start_date <= cutoff %s (company %s)',
    array_to_string(v_fields_changed, ','), v_cutoff, OLD.company_id
  );

  IF v_mode = 'warn' THEN
    INSERT INTO public.period_guard_warnings(
      triggered_by, table_name, operation, contract_id,
      holding_id, company_id, cutoff_date, fields_changed, message,
      payload
    ) VALUES (
      public.get_current_user_id(), 'contracts', 'UPDATE', NEW.id,
      OLD.holding_id, OLD.company_id, v_cutoff, v_fields_changed, v_warn_msg,
      jsonb_build_object(
        'old', to_jsonb(OLD),
        'new', to_jsonb(NEW)
      )
    );
    RETURN NEW;
  END IF;

  RAISE EXCEPTION
    'No se puede modificar campo(s) padre del contrato (%): existe al menos un ítem con start_date <= % (período cerrado de la compañía)',
    array_to_string(v_fields_changed, ','), v_cutoff
    USING ERRCODE = 'P0001',
          HINT = 'Reabrir el período correspondiente o restringir el cambio';
END $function$

CREATE OR REPLACE FUNCTION public.trg_set_contract_item_categoria()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_client_id UUID;
  v_calculated_categoria TEXT;
BEGIN
  IF NEW.categoria IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT client_id INTO v_client_id
  FROM contracts
  WHERE id = NEW.contract_id;

  IF NEW.product_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_calculated_categoria := calculate_contract_item_categoria(
    NEW.contract_id,
    v_client_id,
    NEW.product_id
  );

  NEW.categoria := v_calculated_categoria;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_validate_cutoff_company_holding_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_company_holding uuid;
BEGIN
  SELECT holding_id INTO v_company_holding
  FROM public.companies WHERE id = NEW.company_id;

  IF v_company_holding IS DISTINCT FROM NEW.holding_id THEN
    RAISE EXCEPTION
      'company_id % no pertenece al holding_id % (pertenece a %)',
      NEW.company_id, NEW.holding_id, v_company_holding;
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trigger_generate_invoices_on_contract_signed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_result RECORD;
  v_existing_invoices_count INTEGER := 0;
BEGIN
  -- Only trigger on status change to 'Firmado' or 'Activo'
  IF NEW.status IN ('Firmado', 'Activo') AND (OLD.status IS NULL OR OLD.status != NEW.status) THEN

    -- Verificar si ya existen facturas reales para este contrato
    SELECT COUNT(*) INTO v_existing_invoices_count 
    FROM invoices 
    WHERE contract_id = NEW.id;

    IF v_existing_invoices_count > 0 THEN
      RAISE NOTICE '[INVOICE_GEN] Skipping invoice generation for contract % - % invoices already exist', 
        NEW.contract_number, v_existing_invoices_count;
      RETURN NEW;
    END IF;

    RAISE NOTICE '[INVOICE_GEN] Contract % status changed to %, generating invoices...', NEW.contract_number, NEW.status;

    -- Call the function to generate missing invoices
    SELECT * INTO v_result FROM public.generate_missing_invoices_for_contract(NEW.id);

    IF v_result.success THEN
      RAISE NOTICE '[INVOICE_GEN] Successfully generated % invoices for contract %', v_result.generated_count, NEW.contract_number;
    ELSE
      RAISE WARNING '[INVOICE_GEN] Failed to generate invoices for contract %: %', NEW.contract_number, v_result.message;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trigger_generate_invoices_on_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_result RECORD;
    v_existing_invoices_count INTEGER := 0;
BEGIN
    -- Only trigger when status changes to 'Activo'
    IF NEW.status = 'Activo' AND (OLD.status IS NULL OR OLD.status != 'Activo') THEN

        -- Verificar si ya existen facturas reales para este contrato
        SELECT COUNT(*) INTO v_existing_invoices_count 
        FROM invoices 
        WHERE contract_id = NEW.id;

        IF v_existing_invoices_count > 0 THEN
            RAISE NOTICE '[INVOICE_GEN] Skipping invoice generation for contract % - % invoices already exist', 
                NEW.id, v_existing_invoices_count;
            RETURN NEW;
        END IF;

        RAISE NOTICE '[INVOICE_GEN] Contract % changed to Activo, generating invoices', NEW.id;

        -- Call the invoice generation function
        SELECT * INTO v_result FROM public.generate_missing_invoices_for_contract(NEW.id);

        IF v_result.success THEN
            RAISE NOTICE '[INVOICE_GEN] Successfully generated % invoices for contract %', v_result.generated_count, NEW.id;
        ELSE
            RAISE WARNING '[INVOICE_GEN] Failed to generate invoices for contract %: %', NEW.id, v_result.message;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trigger_pending_renewal_on_item_change()
