CREATE OR REPLACE FUNCTION public.validate_client_agent_config_email_sender()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_sender_holding_id UUID;
BEGIN
  -- Si hay email_sender_address_id en config_json, validar que pertenezca al holding
  IF NEW.config_json ? 'email_sender_address_id' AND 
     NEW.config_json->>'email_sender_address_id' IS NOT NULL AND
     NEW.config_json->>'email_sender_address_id' != '' THEN

    -- Obtener holding_id del email_sender_address
    SELECT hess.holding_id INTO v_sender_holding_id
    FROM email_sender_addresses esa
    INNER JOIN holding_email_sender_settings hess ON esa.domain_config_id = hess.id
    WHERE esa.id = (NEW.config_json->>'email_sender_address_id')::uuid;

    -- Validar que pertenezca al mismo holding
    IF v_sender_holding_id IS NULL THEN
      RAISE EXCEPTION 'Email sender address not found';
    END IF;

    IF v_sender_holding_id != NEW.holding_id THEN
      RAISE EXCEPTION 'Email sender address does not belong to this holding';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_contract_currency_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF current_setting('sapira.skip_currency_validation', true) = 'on' THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.contract_items ci
    WHERE ci.contract_id = NEW.id AND ci.currency IS DISTINCT FROM NEW.contract_currency) THEN
    RAISE EXCEPTION 'Contract currency (%) must match all contract items currency', NEW.contract_currency;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.validate_contract_item_currency_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_contract_currency text;
BEGIN
  IF current_setting('sapira.skip_currency_validation', true) = 'on' THEN RETURN NEW; END IF;
  SELECT contract_currency INTO v_contract_currency
  FROM public.contracts WHERE id = NEW.contract_id;
  IF v_contract_currency IS NOT NULL AND NEW.currency IS DISTINCT FROM v_contract_currency THEN
    RAISE EXCEPTION 'Contract item currency (%) must match contract currency (%)', NEW.currency, v_contract_currency;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.validate_email_matches_domain()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  domain_name TEXT;
BEGIN
  -- Obtener el dominio de la configuración
  SELECT sender_domain INTO domain_name
  FROM holding_email_sender_settings
  WHERE id = NEW.domain_config_id;

  -- Validar que el email termina con @dominio
  IF NEW.from_email NOT LIKE '%@' || domain_name THEN
    RAISE EXCEPTION 'El email % no pertenece al dominio %', NEW.from_email, domain_name;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_fx_confirmation_before_firmado()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Solo validar si el contrato está cambiando a estado 'Firmado'
  IF NEW.status = 'Firmado' AND (OLD.status IS NULL OR OLD.status != 'Firmado') THEN
    -- Validar que fx_company_confirmed_at esté establecido
    IF NEW.fx_company_confirmed_at IS NULL THEN
      RAISE EXCEPTION 'Debe confirmar la política FX de Compañía antes de firmar el contrato';
    END IF;

    -- Validar que fx_invoice_confirmed_at esté establecido
    IF NEW.fx_invoice_confirmed_at IS NULL THEN
      RAISE EXCEPTION 'Debe confirmar la política FX de Facturación antes de firmar el contrato';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_hierarchical_mapping(mapping_config jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Verificar que tenga las secciones requeridas
    IF mapping_config IS NULL THEN
        RETURN FALSE;
    END IF;

    -- Debe tener al menos primary_mappings
    IF NOT (mapping_config ? 'primary_mappings') THEN
        RETURN FALSE;
    END IF;

    -- Si es jerárquico, debe tener secondary_mappings
    IF (mapping_config ? 'mapping_type') AND 
       (mapping_config ->> 'mapping_type' = 'hierarchical') AND
       NOT (mapping_config ? 'secondary_mappings') THEN
        RETURN FALSE;
    END IF;

    -- Verificar que primary_mappings sea un objeto
    IF jsonb_typeof(mapping_config -> 'primary_mappings') != 'object' THEN
        RETURN FALSE;
    END IF;

    -- Si existe secondary_mappings, verificar que sea un objeto
    IF (mapping_config ? 'secondary_mappings') AND
       jsonb_typeof(mapping_config -> 'secondary_mappings') != 'object' THEN
        RETURN FALSE;
    END IF;

    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_holding_fx_period_rates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Validar que period_end sea mayor que period_start
  IF NEW.period_end < NEW.period_start THEN
    RAISE EXCEPTION 'La fecha de fin del período debe ser posterior a la fecha de inicio';
  END IF;

  -- Validar que la tasa sea positiva
  IF NEW.rate <= 0 THEN
    RAISE EXCEPTION 'La tasa de cambio debe ser un valor positivo';
  END IF;

  -- Validar que las monedas sean diferentes
  IF NEW.from_currency = NEW.to_currency THEN
    RAISE EXCEPTION 'Las monedas de origen y destino deben ser diferentes';
  END IF;

  -- Validar que no existan períodos superpuestos para la misma combinación
  IF EXISTS (
    SELECT 1
    FROM public.holding_fx_period_rates
    WHERE id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND holding_id = NEW.holding_id
      AND from_currency = NEW.from_currency
      AND to_currency = NEW.to_currency
      AND (
        -- Verifica si hay superposición de períodos
        (NEW.period_start <= period_end AND NEW.period_end >= period_start)
      )
  ) THEN
    RAISE EXCEPTION 'Ya existe una tasa de cambio para este par de monedas en el período especificado. Los períodos no pueden superponerse.';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_legacy_activation(p_contract_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_holding_id uuid;
  v_contract record;
  v_can_activate boolean := true;
  v_reconciliation_pct numeric := 0;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_total_contract_mrr numeric := 0;
  v_total_billed_mrr numeric := 0;
  v_confirmed_matches_count integer := 0;
  v_contract_items_count integer := 0;
  v_orphan_mrr_data jsonb;
BEGIN
  -- =====================================================
  -- 1. Validar que el contrato existe y es legacy
  -- =====================================================
  SELECT 
    c.holding_id,
    c.is_legacy,
    c.start_date,
    c.end_date,
    c.contract_currency
  INTO v_contract
  FROM contracts c
  WHERE c.id = p_contract_id;

  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_object(
      'type', 'contract_not_found',
      'message', 'Contract does not exist or access denied'
    );
    v_can_activate := false;

    RETURN jsonb_build_object(
      'can_activate', v_can_activate,
      'reconciliation_pct', 0,
      'blockers', v_blockers,
      'warnings', v_warnings
    );
  END IF;

  v_holding_id := v_contract.holding_id;

  -- Verificar permisos RLS
  IF v_holding_id != public.get_user_holding_id() THEN
    v_blockers := v_blockers || jsonb_build_object(
      'type', 'access_denied',
      'message', 'Access denied to this contract'
    );
    v_can_activate := false;

    RETURN jsonb_build_object(
      'can_activate', v_can_activate,
      'reconciliation_pct', 0,
      'blockers', v_blockers,
      'warnings', v_warnings
    );
  END IF;

  -- BLOCKER: Debe estar marcado como legacy
  IF v_contract.is_legacy = false THEN
    v_blockers := v_blockers || jsonb_build_object(
      'type', 'not_legacy',
      'message', 'Contract is not marked as legacy'
    );
    v_can_activate := false;
  END IF;

  -- =====================================================
  -- 2. Validar contract_items
  -- =====================================================
  SELECT 
    COUNT(*),
    COALESCE(SUM(final_price), 0)
  INTO v_contract_items_count, v_total_contract_mrr
  FROM contract_items
  WHERE contract_id = p_contract_id
    AND holding_id = v_holding_id;

  -- BLOCKER: Debe tener al menos un contract_item
  IF v_contract_items_count = 0 THEN
    v_blockers := v_blockers || jsonb_build_object(
      'type', 'no_contract_items',
      'message', 'Contract must have at least one contract_item defined'
    );
    v_can_activate := false;
  END IF;

  -- =====================================================
  -- 3. Validar matches confirmados
  -- =====================================================
  SELECT 
    COUNT(*),
    COALESCE(SUM(amount_contract_currency), 0)
  INTO v_confirmed_matches_count, v_total_billed_mrr
  FROM invoice_items_legacy_match
  WHERE contract_id = p_contract_id
    AND status = 'confirmed'
    AND holding_id = v_holding_id;

  -- BLOCKER: Debe tener al menos un match confirmado
  IF v_confirmed_matches_count = 0 THEN
    v_blockers := v_blockers || jsonb_build_object(
      'type', 'no_confirmed_matches',
      'message', 'Contract must have at least one confirmed legacy invoice match'
    );
    v_can_activate := false;
  END IF;

  -- =====================================================
  -- 4. Validar FX en matches
  -- =====================================================
  DECLARE
    v_missing_fx_count integer;
  BEGIN
    SELECT COUNT(*)
    INTO v_missing_fx_count
    FROM invoice_items_legacy_match m
    WHERE m.contract_id = p_contract_id
      AND m.status = 'confirmed'
      AND m.holding_id = v_holding_id
      AND (m.fx_contract_to_invoice IS NULL OR m.fx_contract_to_invoice <= 0);

    IF v_missing_fx_count > 0 THEN
      v_blockers := v_blockers || jsonb_build_object(
        'type', 'missing_fx_rate',
        'message', format('%s confirmed matches are missing valid fx_contract_to_invoice rate', v_missing_fx_count)
      );
      v_can_activate := false;
    END IF;
  END;

  -- =====================================================
  -- 5. Validar fechas de facturas dentro del rango contractual
  -- =====================================================
  IF v_contract.start_date IS NOT NULL OR v_contract.end_date IS NOT NULL THEN
    DECLARE
      v_out_of_range_count integer;
      v_min_date date;
      v_max_date date;
    BEGIN
      SELECT COUNT(*), MIN(il.issue_date), MAX(il.issue_date)
      INTO v_out_of_range_count, v_min_date, v_max_date
      FROM invoice_items_legacy_match m
      INNER JOIN invoice_items_legacy iil ON iil.id = m.invoice_item_legacy_id
      INNER JOIN invoices_legacy il ON il.id = iil.invoices_legacy_id
      WHERE m.contract_id = p_contract_id
        AND m.status = 'confirmed'
        AND m.holding_id = v_holding_id
        AND (
          (v_contract.start_date IS NOT NULL AND il.issue_date < v_contract.start_date)
          OR
          (v_contract.end_date IS NOT NULL AND il.issue_date > v_contract.end_date)
        );

      IF v_out_of_range_count > 0 THEN
        v_blockers := v_blockers || jsonb_build_object(
          'type', 'invoices_out_of_range',
          'message', format('%s invoices have issue_date outside contract date range (%s to %s). Found dates from %s to %s',
            v_out_of_range_count,
            COALESCE(v_contract.start_date::text, 'N/A'),
            COALESCE(v_contract.end_date::text, 'N/A'),
            v_min_date,
            v_max_date
          )
        );
        v_can_activate := false;
      END IF;
    END;
  END IF;

  -- =====================================================
  -- 6. Calcular reconciliation_pct
  -- =====================================================
  IF v_total_contract_mrr > 0 THEN
    v_reconciliation_pct := ROUND((v_total_billed_mrr / NULLIF(v_total_contract_mrr, 0)) * 100, 2);
  ELSE
    v_reconciliation_pct := 0;
  END IF;

  -- =====================================================
  -- 7. WARNINGS: Orphan MRR
  -- =====================================================
  -- Detectar matches confirmados sin contract_item_id asignado
  DECLARE
    v_orphan_count integer;
    v_orphan_amount numeric;
  BEGIN
    SELECT 
      COUNT(*),
      COALESCE(SUM(m.amount_contract_currency), 0)
    INTO v_orphan_count, v_orphan_amount
    FROM invoice_items_legacy_match m
    WHERE m.contract_id = p_contract_id
      AND m.contract_item_id IS NULL
      AND m.status = 'confirmed'
      AND m.holding_id = v_holding_id;

    IF v_orphan_count > 0 THEN
      v_warnings := v_warnings || jsonb_build_object(
        'type', 'orphan_mrr',
        'message', format('%s confirmed matches (%s %s) are not assigned to any contract_item',
          v_orphan_count,
          ROUND(v_orphan_amount, 2),
          v_contract.contract_currency
        )
      );
    END IF;
  END;

  -- =====================================================
  -- 8. WARNINGS: Discrepancia MRR >20%
  -- =====================================================
  IF v_total_contract_mrr > 0 THEN
    DECLARE
      v_discrepancy_pct numeric;
    BEGIN
      v_discrepancy_pct := ABS(((v_total_billed_mrr - v_total_contract_mrr) / NULLIF(v_total_contract_mrr, 0)) * 100);

      IF v_discrepancy_pct > 20 THEN
        v_warnings := v_warnings || jsonb_build_object(
          'type', 'mrr_discrepancy',
          'message', format('MRR discrepancy of %s%%. Contract MRR: %s, Billed MRR: %s (%s)',
            ROUND(v_discrepancy_pct, 1),
            ROUND(v_total_contract_mrr, 2),
            ROUND(v_total_billed_mrr, 2),
            v_contract.contract_currency
          )
        );
      END IF;
    END;
  END IF;

  -- =====================================================
  -- 9. WARNINGS: Items sin facturas (CMRR risk)
  -- =====================================================
  FOR v_orphan_mrr_data IN
    SELECT 
      ci.id as item_id,
      ci.product_name,
      ci.final_price
    FROM contract_items ci
    WHERE ci.contract_id = p_contract_id
      AND ci.holding_id = v_holding_id
      AND NOT EXISTS (
        SELECT 1 
        FROM invoice_items_legacy_match m
        WHERE m.contract_id = p_contract_id
          AND m.contract_item_id = ci.id
          AND m.status = 'confirmed'
          AND m.holding_id = v_holding_id
      )
  LOOP
    v_warnings := v_warnings || jsonb_build_object(
      'type', 'cmrr_risk',
      'item_id', v_orphan_mrr_data->>'item_id',
      'message', format('Contract item "%s" (%s %s) has no confirmed invoices',
        v_orphan_mrr_data->>'product_name',
        v_orphan_mrr_data->>'final_price',
        v_contract.contract_currency
      )
    );
  END LOOP;

  -- =====================================================
  -- Retornar resultado completo
  -- =====================================================
  RETURN jsonb_build_object(
    'can_activate', v_can_activate,
    'reconciliation_pct', v_reconciliation_pct,
    'blockers', v_blockers,
    'warnings', v_warnings
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_legacy_reconciliation(p_invoice_legacy_id uuid)
 RETURNS TABLE(is_valid boolean, total_invoice numeric, total_matched numeric, total_confirmed numeric, unmatched_amount numeric, lines_count integer, lines_matched integer, lines_confirmed integer, warnings jsonb, blockers jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result RECORD;
  v_warnings JSONB := '[]'::JSONB;
  v_blockers JSONB := '[]'::JSONB;
  v_is_valid BOOLEAN := true;
BEGIN
  SELECT 
    il.total_invoice_currency,
    COUNT(DISTINCT iil.id) as lines_total,
    COUNT(DISTINCT CASE WHEN EXISTS (
      SELECT 1 FROM invoice_items_legacy_match m 
      WHERE m.invoice_item_legacy_id = iil.id
    ) THEN iil.id END) as lines_with_match,
    COUNT(DISTINCT CASE WHEN EXISTS (
      SELECT 1 FROM invoice_items_legacy_match m 
      WHERE m.invoice_item_legacy_id = iil.id AND m.status = 'confirmed'
    ) THEN iil.id END) as lines_with_confirmed,
    COALESCE(SUM(
      (SELECT SUM(m.amount_invoice_currency) 
       FROM invoice_items_legacy_match m 
       WHERE m.invoice_item_legacy_id = iil.id)
    ), 0) as total_matched_amount,
    COALESCE(SUM(
      (SELECT SUM(m.amount_invoice_currency) 
       FROM invoice_items_legacy_match m 
       WHERE m.invoice_item_legacy_id = iil.id AND m.status = 'confirmed')
    ), 0) as total_confirmed_amount
  INTO v_result
  FROM invoices_legacy il
  LEFT JOIN invoice_items_legacy iil ON iil.invoices_legacy_id = il.id
  WHERE il.id = p_invoice_legacy_id
    AND il.holding_id = get_current_user_holding_id()
  GROUP BY il.id, il.total_invoice_currency;

  IF v_result.lines_with_confirmed < v_result.lines_total THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code', 'INCOMPLETE_LINES',
      'message', format('Only %s of %s lines have confirmed matches', 
                        v_result.lines_with_confirmed, v_result.lines_total)
    );
    v_is_valid := false;
  END IF;

  IF ABS(v_result.total_confirmed_amount - v_result.total_invoice_currency) > 0.01 THEN
    IF ABS(v_result.total_confirmed_amount - v_result.total_invoice_currency) / v_result.total_invoice_currency > 0.02 THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code', 'AMOUNT_MISMATCH',
        'message', format('Confirmed amount (%s) differs from invoice total (%s) by more than 2%%',
                          v_result.total_confirmed_amount, v_result.total_invoice_currency)
      );
      v_is_valid := false;
    ELSE
      v_warnings := v_warnings || jsonb_build_object(
        'code', 'MINOR_AMOUNT_DIFF',
        'message', format('Small difference between confirmed amount (%s) and invoice total (%s)',
                          v_result.total_confirmed_amount, v_result.total_invoice_currency)
      );
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM invoice_items_legacy_match m
    JOIN invoice_items_legacy iil ON iil.id = m.invoice_item_legacy_id
    WHERE iil.invoices_legacy_id = p_invoice_legacy_id
      AND m.status = 'confirmed'
      AND (m.fx_contract_to_invoice IS NULL OR m.fx_contract_to_invoice <= 0)
  ) THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code', 'INVALID_FX',
      'message', 'Some confirmed matches have invalid FX rates'
    );
    v_is_valid := false;
  END IF;

  RETURN QUERY SELECT 
    v_is_valid,
    v_result.total_invoice_currency,
    v_result.total_matched_amount,
    v_result.total_confirmed_amount,
    v_result.total_invoice_currency - v_result.total_confirmed_amount,
    v_result.lines_total,
    v_result.lines_with_match,
    v_result.lines_with_confirmed,
    v_warnings,
    v_blockers;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_match_total()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_line_subtotal NUMERIC;
  v_matched_total NUMERIC;
BEGIN
  -- Obtener el SUBTOTAL (sin IVA) del item de factura
  SELECT subtotal INTO v_line_subtotal
  FROM invoice_items_legacy
  WHERE id = NEW.invoice_item_legacy_id;

  -- Calcular el total ya asignado a este item (excluyendo el registro actual si es UPDATE)
  SELECT COALESCE(SUM(amount_invoice_currency), 0)
  INTO v_matched_total
  FROM invoice_items_legacy_match
  WHERE invoice_item_legacy_id = NEW.invoice_item_legacy_id
    AND (TG_OP = 'INSERT' OR id != NEW.id);

  -- Validar que el total matched no exceda el subtotal del item (con 1% de tolerancia)
  IF (v_matched_total + NEW.amount_invoice_currency) > (v_line_subtotal * 1.01) THEN
    RAISE EXCEPTION 'Total matched (%) exceeds line subtotal (%)', 
      v_matched_total + NEW.amount_invoice_currency, v_line_subtotal;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_user_has_holding()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    user_record_id UUID;
    has_holding BOOLEAN := false;
BEGIN
    -- Obtener el ID del usuario interno
    SELECT id INTO user_record_id 
    FROM public.users 
    WHERE auth_id = auth.uid();

    -- Si no encontramos por auth_id, intentar por email
    IF user_record_id IS NULL THEN
        SELECT id INTO user_record_id 
        FROM public.users 
        WHERE email = (SELECT email FROM auth.users WHERE id = auth.uid());
    END IF;

    -- Si no existe usuario interno, retornar false
    IF user_record_id IS NULL THEN
        RETURN false;
    END IF;

    -- Verificar si tiene holding válido
    SELECT EXISTS(
        SELECT 1 FROM public.user_holdings uh
        INNER JOIN public.company_holdings ch ON uh.holding_id = ch.id
        WHERE uh.user_id = user_record_id
    ) INTO has_holding;

    RETURN has_holding;
END;
$function$
